window.MEFOS_FIXED_BANK.push(...[{"id":"neuro20261004-1.5.2-115","number":"115","statement":"En el reflejo fotomotor a la luz, la vía aferente viaja por el nervio óptico (II par) y las neuronas eferentes parasimpáticas nacen en el núcleo de Edinger-Westphal. ¿A través de qué ganglio periférico hacen sinapsis estas fibras preganglionares antes de inervar el músculo esfíncter de la pupila?:","options":["Ganglio ciliar","Ganglio pterigopalatino","Ganglio ótico","Ganglio geniculado"],"answer":0,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.2 - PARES CRANEALES | entrada I-072 / G0608 del banco canónico | integración: Tema 1.5.2 + Tema 1.11.1 + Tema 1.12 | archivos: Neuro_Parte3.pdf | referencias indicadas: wuolah-free-tema-4-preguntas.pdf / Tema 1.5.2 - Pares craneales 25- 26 (1).pdf","topic":"1.5.2","document":"02-TECC29-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.2-116","number":"116","statement":"Los somas de las neuronas de primer orden responsables de la audición se localizan en el ganglio espiral (de Corti). ¿Dónde realizan su primera sinapsis en el tronco del encéfalo?:","options":["Núcleos cocleares anterior (ventral) y posterior (dorsal) en el ángulo pontobulbar.","Núcleo vestibular superior de Bechterew.","Núcleo ambiguo.","Núcleo del tracto solitario."],"answer":0,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.2 - PARES CRANEALES | entrada I-073 / G0609 del banco canónico | integración: Tema 1.5.1 + Tema 1.5.2 + Tema 1.11.2 | archivos: Neuro_Parte3.pdf | referencias indicadas: ex. 2021 (respuestas).pdf / examenes neuro compl (1).pdf","topic":"1.5.2","document":"02-TECC29-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.2-117","number":"117","statement":"La hiperacusia (sensibilidad excesiva a los sonidos graves o intensos) por parálisis del músculo del estribo (estapedio) es consecuencia de la lesión de qué par craneal:","options":["Nervio trigémino (V3)","Nervio facial (VII)","Nervio vestibulococlear (VIII)","Nervio vago (X)"],"answer":1,"explanation":"[Nota de la clave] El músculo estapedio atenúa las vibraciones y está inervado por una rama motora del VII par; al paralizarse, los sonidos se perciben anormalmente fuertes).","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.2 - PARES CRANEALES | entrada I-074 / G0610 del banco canónico | integración: Tema 1.5.2 + Tema 1.11.2 | archivos: Neuro_Parte3.pdf | referencias indicadas: wuolah-free-UNIRESUMEN-DOCUMENTO-GRATIS-PARES- CRANEALES.pdf / TEMA 4 – PARES CRANEALES .pdf","topic":"1.5.2","document":"02-TECC29-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.2-118","number":"118","statement":"¿Cuáles de los siguientes pares craneales tienen su origen aparente alineado en el surco retroolivar (postolivar) del bulbo raquídeo, ordenados de cefálico a caudal?:","options":["VI, VII y VIII","IX (glosofaríngeo), X (vago) y XI (accesorio)","III, IV y V","XII (hipogloso) y XI (accesorio)"],"answer":1,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.2 - PARES CRANEALES | entrada I-075 / G0612 del banco canónico | integración: Tema 1.5.1 + Tema 1.5.2 | archivos: Neuro_Parte3.pdf | referencias indicadas: wuolah-free-EXAMEN-2017-2018-1 (1).pdf / examenes neuro compl (1).pdf","topic":"1.5.2","document":"02-TECC29-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.2-119","number":"119","statement":"La secreción salival de la glándula parótida se estimula por fibras parasimpáticas cuyo recorrido completo incluye la siguiente secuencia anatómica exacta:","options":["Núcleo salivatorio inferior → IX par → N. timpánico (de Jacobson) → N. petroso menor → Ganglio ótico → N. auriculotemporal (V3) → Glándula parótida.","Núcleo salivatorio superior → VII par → N. petroso mayor → Ganglio pterigopalatino → Glándula parótida.","Núcleo dorsal del vago → X par → Ganglio celiaco → Glándula parótida.","Núcleo ambiguo → IX par → Ganglio lingual → Glándula parótida."],"answer":0,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.2 - PARES CRANEALES | entrada I-076 / G0614 del banco canónico | integración: Tema 1.5.2 + Tema 1.12 | archivos: Neuro_Parte3.pdf | referencias indicadas: wuolah-free-tema-4-preguntas.pdf / Tema 1.5.2 - Pares craneales 25- 26 (1).pdf","topic":"1.5.2","document":"02-TECC29-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.2-120","number":"120","statement":"Los axones no mielinizados del I par craneal (nervio olfatorio) atraviesan qué estructura ósea de la base del cráneo para hacer sinapsis en el bulbo olfatorio:","options":["Conducto óptico","Lámina cribosa del hueso etmoides","Foramen esfenopalatino","Fisura orbitaria superior"],"answer":1,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.2 - PARES CRANEALES | entrada I-077 / G0616 del banco canónico | integración: Tema 1.5.2 + Tema 1.11.3 | archivos: Neuro_Parte3.pdf | referencias indicadas: wuolah-free-UNIRESUMEN-DOCUMENTO-GRATIS-PARES- CRANEALES.pdf / wuolah-free-tema-4-preguntas.pdf","topic":"1.5.2","document":"02-TECC29-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.2-121","number":"121","statement":"¿Qué pares craneales discurren juntos atravesando el conducto auditivo interno (CAI) en el peñasco del hueso temporal?:","options":["V y VI","VII (nervio facial) y VIII (nervio vestibulococlear)","IX y X","XI y XII"],"answer":1,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.2 - PARES CRANEALES | entrada I-078 / G0617 del banco canónico | integración: Tema 1.5.2 + Tema 1.11.2 | archivos: Neuro_Parte3.pdf | referencias indicadas: wuolah-free-tema-4-preguntas.pdf / ex. 2 (respuestas).pdf","topic":"1.5.2","document":"02-TECC29-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.2-122","number":"122","statement":"El núcleo dorsal del nervio vago (X) proporciona fibras preganglionares parasimpáticas para el control autónomo de:","options":["Las glándulas lagrimales y mucosas nasales.","Las vísceras del tórax y abdomen hasta el ángulo esplénico (izquierdo) del colon.","Exclusivamente la glándula parótida.","El músculo esfíncter de la pupila."],"answer":1,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.2 - PARES CRANEALES | entrada I-079 / G0619 del banco canónico | integración: Tema 1.5.2 + Tema 1.12 | archivos: Neuro_Parte3.pdf | referencias indicadas: wuolah-free-tema-4-preguntas.pdf / Tema 1.5.2 - Pares craneales 25- 26 (1).pdf","topic":"1.5.2","document":"02-TECC29-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.2-123","number":"123","statement":"El núcleo ambiguo (ubicado en el bulbo raquídeo) aloja las motoneuronas branquiales que dan origen a las eferencias motoras de los siguientes pares craneales:","options":["V, VI y VII","IX (glosofaríngeo), X (vago) y la porción craneal del XI (accesorio)","III, IV y VI","Únicamente el nervio troclear (IV)"],"answer":1,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.2 - PARES CRANEALES | entrada I-080 / G0626 del banco canónico | integración: Tema 1.5.1 + Tema 1.5.2 | archivos: Neuro_Parte3.pdf | referencias indicadas: wuolah-free-UNIRESUMEN-DOCUMENTO-GRATIS-PARES- CRANEALES.pdf (Pregunta #29)","topic":"1.5.2","document":"02-TECC29-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.2-124","number":"124","statement":"Las fibras simpáticas posganglionares procedentes del plexo carotídeo que acompañan al III par craneal en el interior de la órbita inervan:","options":["El músculo esfíncter de la pupila","El músculo elevador del párpado superior (porción tarsal de Müller) y el músculo dilatador de la pupila","La glándula submandibular","El músculo ciliar"],"answer":1,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.2 - PARES CRANEALES | entrada I-081 / G0627 del banco canónico | integración: Tema 1.5.2 + Tema 1.12 | archivos: Neuro_Parte3.pdf | referencias indicadas: wuolah-free-UNIRESUMEN-DOCUMENTO-GRATIS-PARES- CRANEALES.pdf (Pregunta #58)","topic":"1.5.2","document":"02-TECC29-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.2-125","number":"125","statement":"La porción rostral (gustativa) del núcleo del tracto solitario recibe la sensibilidad gustativa conducida por los siguientes pares craneales:","options":["VII (nervio facial), IX (glosofaríngeo) y X (nervio vago)","V (trigémino), VII y IX","I (olfatorio), II (óptico) y VIII (vestibulococlear)","Exclusivamente el nervio trigémino (V3)10"],"answer":0,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.2 - PARES CRANEALES | entrada I-082 / G0629 del banco canónico | integración: Tema 1.5.2 + Tema 1.11.3 | archivos: Neuro_Parte3.pdf | referencias indicadas: wuolah-free-UNIRESUMEN-DOCUMENTO-GRATIS-PARES- CRANEALES.pdf (Pregunta #65)","topic":"1.5.2","document":"02-TECC29-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.2-126","number":"126","statement":"Respecto a la inervación sensitiva de las meninges, el nervio trigémino (V) recaba la sensibilidad de la duramadre localizada en:","options":["La fosa craneal posterior exclusivamente","La fosa craneal anterior y la fosa craneal media (a través de V1, V2 y V3)712","La cavidad medular cervical","La duramadre carece por completo de inervación sensitiva"],"answer":1,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.2 - PARES CRANEALES | entrada I-083 / G0630 del banco canónico | integración: Tema 1.3 + Tema 1.5.2 | archivos: Neuro_Parte3.pdf | referencias indicadas: wuolah-free-UNIRESUMEN-DOCUMENTO-GRATIS-PARES- CRANEALES.pdf (Pregunta #83) / examenes neuro compl (1).pdf","topic":"1.5.2","document":"02-TECC29-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.2-127","number":"127","statement":"Seleccione la afirmación CORRECTA sobre las estructuras del tronco del encéfalo y sus vías:","options":["Las fibras tectoespinales originan el lemnisco medial.","Las fibras arciformes internas originan el lemnisco lateral.","Las pirámides del bulbo raquídeo llevan información propioceptiva.","En el nivel de la oliva inferior se encuentra la entrada/origen aparente del nervio vago (X).","El nervio facial describe un giro alrededor del núcleo del tracto solitario."],"answer":3,"explanation":"Desmonte da Armadilha: As fibras arciformes internas originam o lemnisco medial; as pirâmides levam informação motora/corticoespinal; e a alça/joelho do nervio facial contorna o núcleo do nervio abducens VI, elevando o colículo facial no soalho do IV ventrículo).","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.2 - PARES CRANEALES | entrada I-084 / G0649 del banco canónico | integración: Tema 1.5.1 + Tema 1.5.2 + Tema 1.10 | archivos: Neuro_Parte3.pdf | referencias indicadas: wuolah-free-Examen-Neuro-3.pdf / Preguntas temas 3,4,5,6.pdf / TEMA 3 – TRONCO DEL ENCÉFALO.pdf","topic":"1.5.2","document":"02-TECC29-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.2-128","number":"128","statement":"Señale la relación CORRECTA sobre los núcleos y áreas del tronco del encéfalo:","options":["Núcleos del Rafe — Localizados en la franja lateral de la protuberancia y mesencéfalo.","Núcleo olivar inferior — Relacionado con la localización de la fuente sonora en el plano horizontal.","Núcleo de Edinger-Westphal — Localizado en el mesencéfalo, próximo al acueducto cerebral.","Área tegmental ventral — Componente del sistema motor extrapiramidal ubicado en el bulbo raquídeo."],"answer":2,"explanation":"Hack de Inversão Olivar da Professora Aitana: O núcleo olivar superior [na protuberância] é quem processa a localização sonora horizontal; o olivar inferior [no bulbo] projeta ao cerebelo como fibras trepadoras).","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.2 - PARES CRANEALES | entrada I-085 / G0650 del banco canónico | integración: Tema 1.5.1 + Tema 1.5.2 + Tema 1.9.3 | archivos: Neuro_Parte3.pdf | referencias indicadas: examenes neuro compl (1).pdf / perguntas neuro julio exame.docx","topic":"1.5.2","document":"02-TECC29-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.2-129","number":"129","statement":"Un infarto vascular por oclusión de ramas de la arteria cerebral posterior que compromete el pie del pedúnculo cerebral ventral y el fascículo eferente del III par craneal provoca el Síndrome alterno de Weber. ¿Cuál es la manifestación clínica característica?:","options":["Hemiparesia/hemiplejía contralateral y parálisis ipsilateral del nervio oculomotor (III par: ptosis, ojo desviado hacia fuera y midriasis).","Parálisis facial periférica ipsilateral y ataxia cerebelosa.","Anestesia termoalgésica homolateral de la cara y hemicuerpo.","Pérdida auditiva bilateral completa."],"answer":0,"explanation":"Hack de Síndromes Alternos: A lesão do tronco produz déficit motor/sensitivo no hemicorpo CONTRALATERAL [devido aos tratos longos decusados] e déficit de par craniano IPSILATERAL [pela lesão do núcleo ou raiz no mesmo lado]).","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.2 - PARES CRANEALES | entrada I-086 / G0682 del banco canónico | integración: Tema 1.3 + Tema 1.5.1 + Tema 1.5.2 | archivos: Neuro_Parte3.pdf | referencias indicadas: wuolah-free-tema-3-preguntas.pdf / 09-24 Clase de Anatomía_ Estructuras del Mesencéfalo","topic":"1.5.2","document":"02-TECC29-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.2-130","number":"130","statement":"En la superficie dorsal del puente (suelo del cuarto ventrículo), el colículo facial NO está constituido internamente por el soma del núcleo del nervio facial, sino por:","options":["El núcleo del nervio abducens (VI par) rodeado por el bucle o rodilla interna de los axones del nervio facial (VII par).","El núcleo del nervio trigémino (V par) rodeado por fibras del nervio vestibulococlear.","El núcleo del nervio hipogloso (XII par) rodeado por axones del nervio vago.","El núcleo ambiguo rodeado por fibras del glosofaríngeo."],"answer":0,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.2 - PARES CRANEALES | entrada I-087 / G0691 del banco canónico | integración: Tema 1.5.1 + Tema 1.5.2 | archivos: Neuro_Parte3.pdf | referencias indicadas: 10-30 Clase magistral_ Neuroanatomía meníngea / 09-23 Clase_ Núcleos de la Protuberancia / examenes neuro compl (1).pdf","topic":"1.5.2","document":"02-TECC29-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.2-131","number":"131","statement":"En la superficie anterolateral del bulbo raquídeo, la oliva bulbar está delimitada medialmente por el surco preolivar y lateralmente por el surco retroolivar. ¿Qué par craneal emerge específicamente del surco preolivar?:","options":["Nervio hipogloso (XII par).","Nervio glosofaríngeo (IX par).","Nervio vago (X par).","Nervio abducens (VI par)."],"answer":0,"explanation":"[Nota de la clave] Hack Direcional do Surco: Do surco PREolivar emerge unicamente o XII par. Do surco RETROolivar emergem os pares IX, X e XI).","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.2 - PARES CRANEALES | entrada I-088 / G0701 del banco canónico | integración: Tema 1.5.1 + Tema 1.5.2 | archivos: Neuro_Parte3.pdf | referencias indicadas: wuolah-free-tema-3-preguntas.pdf / TEMA 3 – TRONCO DEL ENCÉFALO.pdf","topic":"1.5.2","document":"02-TECC29-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.2-132","number":"132","statement":"Respecto al núcleo motor del nervio troclear (IV par craneal), señale la opción FALSA:","options":["Se localiza en la región tegmental del mesencéfalo a nivel del colículo inferior.","Sus axones emergen por la superficie posterior/dorsal del tronco del encéfalo.","Sus fibras decusan completamente en el velo medular superior antes de salir del encéfalo.","Sus fibras inervan el músculo oblicuo inferior del ojo del mismo lado sin cruzar."],"answer":3,"explanation":"Hack de la Falsa Inervación: Es la FALSA porque el nervio troclear inerva el músculo oblicuo superior [no el inferior] y sus fibras decusan totalmente [se cruzan con el lado opuesto] antes de emerger por la cara posterior).","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.2 - PARES CRANEALES | entrada I-089 / G0706 del banco canónico | integración: Tema 1.5.1 + Tema 1.5.2 | archivos: Neuro_Parte3.pdf | referencias indicadas: 09-24 Clase de Anatomía_ Estructuras del Mesencéfalo / wuolah-free- UNIRESUMEN-DOCUMENTO-GRATIS-PARES-CRANEALES.pdf","topic":"1.5.2","document":"02-TECC29-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.2-133","number":"133","statement":"El \"colículo facial\" en la fosa romboidea de la protuberancia es una elevación anatómica producida por:","options":["Los somas del núcleo motor del nervio facial únicamente.","La rodilla interna de los axones del nervio facial (VII) rodeando al núcleo del nervio abducens (VI).","El núcleo del nervio trigémino (V) en su porción motora.","El pedúnculo cerebeloso superior."],"answer":1,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.2 - PARES CRANEALES | entrada I-090 / G0707 del banco canónico | integración: Tema 1.5.1 + Tema 1.5.2 | archivos: Neuro_Parte3.pdf | referencias indicadas: wuolah-free-UNIRESUMEN-DOCUMENTO-GRATIS-PARES- CRANEALES.pdf / 10-30 Clase magistral_ Neuroanatomía meníngea","topic":"1.5.2","document":"02-TECC29-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.2-134","number":"134","statement":"En la región anterior (ventral) del bulbo raquídeo, las pirámides están separadas de la oliva bulbar por:","options":["El surco preolivar (de donde emergen los filetes del nervio hipogloso XII).","El surco retroolivar.","La fisura media anterior.","El surco bulbopontino."],"answer":0,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.2 - PARES CRANEALES | entrada I-091 / G0709 del banco canónico | integración: Tema 1.5.1 + Tema 1.5.2 | archivos: Neuro_Parte3.pdf | referencias indicadas: 09-22 Clase_ Anatomía del tronco del encéfalo / TEMA 3 – TRONCO DEL ENCÉFALO.pdf","topic":"1.5.2","document":"02-TECC29-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.2-135","number":"135","statement":"La vía corticonuclear (corticobulbar) transporta órdenes motoras voluntarias desde la corteza cerebral hacia los núcleos motores de los pares craneales en el tronco del encéfalo. ¿Por qué porción específica de la cápsula interna discurre este haz motor?:","options":["Rodilla de la cápsula interna.","Brazo anterior de la cápsula interna.","Brazo posterior de la cápsula interna.","Porción retrolenticular de la cápsula interna."],"answer":0,"explanation":"No incluida en el material.","hack":"Distribución anatómica de haces motores en la Cápsula Interna: Rodilla: Vía Corticonuclear / Corticobulbar (inerva motoneuronas de los pares craneales III, IV, V, VI, VII, IX, X, XI, XII). Un ictus en la rodilla afecta la cara y la deglución. Brazo Posterior: Vía Corticoespinal (inerva motoneuronas de miembros y tronco) + Radiaciones somatosensoriales.","source":"Neurociencias – Tema 1.5.2 - PARES CRANEALES | entrada I-092 / G0818 del banco canónico | integración: Tema 1.5.1 + Tema 1.5.2 + Tema 1.7 + Tema 1.9.1 | archivos: Neuro_Adicional_Parte1.pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #105) / 12-04 Clase_ Tractos Corticoespinal, Corticonuclear y Rubroespinal / Tema 1.7 - Telencéfalo","topic":"1.5.2","document":"02-TECC29-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.2-136","number":"136","statement":"¿Cuáles son los pares craneales que surgen del tronco del encéfalo por el surco preolivar del bulbo raquídeo?:","options":["Vago (X)","Abducens (VI)","Hipogloso (XII)","Glosofaríngeo (IX)","Accesorio (XI)"],"answer":2,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.2 - PARES CRANEALES | entrada I-093 / G0906 del banco canónico | integración: Tema 1.5.1 + Tema 1.5.2 | referencias indicadas: wuolah-free-tema-4-preguntas.pdf / TEMA 4 – PARES CRANEALES .pdf","topic":"1.5.2","document":"02-TECC29-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.2-137","number":"137","statement":"Durante el desarrollo embrionario, el núcleo motor del XII par craneal:","options":["Se ubicará en la placa basal del mielencéfalo.","Se ubicará en la placa alar del metencéfalo.","Se origina a partir del neuroepitelio de la capa marginal.","Se origina en la placa del suelo, aunque ocupará su posición definitiva en la placa del techo."],"answer":0,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.2 - PARES CRANEALES | entrada I-094 / G0911 del banco canónico | integración: Tema 1.2 + Tema 1.5.2 | archivos: NEURO_275_ORGANIZADO_POR_TEMA_HACK24(1).pdf; NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf | referencias indicadas: NEURO_275_ORGANIZADO_POR_TEMA_HACK24(1).pdf","topic":"1.5.2","document":"02-TECC29-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.2-138","number":"138","statement":"La formación reticular:","options":["Solamente se encuentra en protuberancia y bulbo raquídeo.","Participa en la modulación del dolor.","No tiene influencia de los ciclos del sueño y vigilia.","Su única función es regular la función cardiaca y respiratoria."],"answer":1,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.2 - PARES CRANEALES | entrada I-095 / G0969 del banco canónico | integración: Tema 1.5.1 + Tema 1.5.2 | archivos: NEURO_275_ORGANIZADO_POR_TEMA_HACK24(1).pdf; NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf | referencias indicadas: NEURO_275_ORGANIZADO_POR_TEMA_HACK24(1).pdf","topic":"1.5.2","document":"02-TECC29-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.2-139","number":"139","statement":"¿Cuál de los siguientes nervios craneales emerge por la unión bulboprotuberancial y es responsable de los movimientos de abducción del ojo?","options":["Nervio óptico (II).","Nervio oculomotor (III).","Nervio troclear (IV).","Nervio abducens (VI)."],"answer":3,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.2 - PARES CRANEALES | entrada I-096 / G0971 del banco canónico | integración: Tema 1.5.1 + Tema 1.5.2 | archivos: NEURO_275_ORGANIZADO_POR_TEMA_HACK24(1).pdf; NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf | referencias indicadas: NEURO_275_ORGANIZADO_POR_TEMA_HACK24(1).pdf","topic":"1.5.2","document":"02-TECC29-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.2-140","number":"140","statement":"Indica la relación INCORRECTA sobre los ganglios de la rama parasimpática de los nervios craneales:","options":["Núcleo de Edinger-Westphal - Ganglio ciliar.","Núcleo salivar superior - Ganglio pterigopalatino.","Núcleo salivar inferior - Ganglio ótico.","Núcleo accesorio - Ganglio yugular."],"answer":3,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.2 - PARES CRANEALES | entrada I-097 / G0977 del banco canónico | integración: Tema 1.5.2 + Tema 1.12 | archivos: NEURO_275_ORGANIZADO_POR_TEMA_HACK24(1).pdf; NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf | referencias indicadas: NEURO_275_ORGANIZADO_POR_TEMA_HACK24(1).pdf","topic":"1.5.2","document":"02-TECC29-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.2-141","number":"141","statement":"¿Cuál de los siguientes nervios craneales tiene su salida en la región dorsal del tronco del encéfalo?","options":["Nervio oculomotor.","Nervio troclear.","Nervio abducens.","Nervio facial."],"answer":1,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.2 - PARES CRANEALES | entrada I-098 / G0978 del banco canónico | integración: Tema 1.5.1 + Tema 1.5.2 | archivos: NEURO_275_ORGANIZADO_POR_TEMA_HACK24(1).pdf; NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf | referencias indicadas: NEURO_275_ORGANIZADO_POR_TEMA_HACK24(1).pdf","topic":"1.5.2","document":"02-TECC29-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.2-142","number":"142","statement":"Un paciente presenta ptosis palpebral (caída del párpado superior), dilatación pupilar y el ojo desviado hacia fuera. ¿Qué nervio craneal está lesionado?","options":["Nervio óptico (II).","Nervio oculomotor (III).","Nervio troclear (IV).","Nervio abducens (VI)."],"answer":1,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.2 - PARES CRANEALES | entrada I-099 / G0982 del banco canónico | integración: Tema 1.5.2 + Tema 1.11.1 + Tema 1.12 | archivos: NEURO_275_ORGANIZADO_POR_TEMA_HACK24(1).pdf; NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf | referencias indicadas: NEURO_275_ORGANIZADO_POR_TEMA_HACK24(1).pdf","topic":"1.5.2","document":"02-TECC29-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.2-143","number":"143","statement":"Indica la afirmación INCORRECTA sobre las modalidades aferentes de los nervios craneales:","options":["La sensibilidad somática general del epitelio corneal es recogida por ramas del nervio oftálmico.","El ganglio geniculado alberga los somas de neuronas que recogen sensibilidad gustativa.","La información somatosensitiva de la lengua es recogida, en parte, por el nervio trigémino.","La faringe es inervada únicamente por ramas del nervio glosofaríngeo."],"answer":3,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.2 - PARES CRANEALES | entrada I-100 / G0983 del banco canónico | integración: Tema 1.5.2 + Tema 1.6 | archivos: NEURO_275_ORGANIZADO_POR_TEMA_HACK24(1).pdf; NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf | referencias indicadas: NEURO_275_ORGANIZADO_POR_TEMA_HACK24(1).pdf","topic":"1.5.2","document":"02-TECC29-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.2-144","number":"144","statement":"Un paciente presenta ptosis palpebral (caída del párpado superior), dilatación pupilar y el ojo desviado hacia fuera. ¿Qué nervio craneal está lesionado?","options":["Óptico (II).","Oculomotor (III).","Troclear (IV).","Abducens (VI)."],"answer":1,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.2 - PARES CRANEALES | entrada I-101 / G0984 del banco canónico | integración: Tema 1.5.2 + Tema 1.11.1 + Tema 1.12 | archivos: NEURO_275_ORGANIZADO_POR_TEMA_HACK24(1).pdf; NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf | referencias indicadas: NEURO_275_ORGANIZADO_POR_TEMA_HACK24(1).pdf","topic":"1.5.2","document":"02-TECC29-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.2-145","number":"145","statement":"Con respecto a los neurotransmisores del SNA es FALSO que:","options":["La acetilcolina es el principal neurotransmisor en los ganglios simpáticos y parasimpáticos.","Los efectores del parasimpático presentan receptores para acetilcolina.","Todas las neuronas postganglionares simpáticas liberan noradrenalina.","En el SNA se liberan neurotransmisores diferentes de la noradrenalina y la acetilcolina, como el ATP y el óxido nítrico."],"answer":2,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.2 - PARES CRANEALES | entrada I-102 / G1138 del banco canónico | integración: Tema 1.5.1 + Tema 1.5.2 + Tema 1.6 + Tema 1.8 + Tema 1.9.1 + Tema 1.9.3 + Tema 1.10 + Tema 1.11.1 + Tema 1.12 | archivos: NEURO_275_ORGANIZADO_POR_TEMA_HACK24(1).pdf; NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf | referencias indicadas: NEURO_275_ORGANIZADO_POR_TEMA_HACK24(1).pdf","topic":"1.5.2","document":"02-TECC29-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.2-146","number":"146","statement":"Si se produce una lesión en la porción craneal (tronco encefálico) de la división parasimpática del SNA, se verá afectada la inervación de las siguientes estructuras, EXCEPTO:","options":["Glándulas salivales.","Bronquios.","Vejiga urinaria (o uréteres inferiores).","Corazón."],"answer":2,"explanation":"No incluida en el material.","hack":"Hack de la División Craneal vs. Sacra del Parasimpático: Porción CRANEAL (Pares III, VII, IX y X): Inerva estructuras de la cabeza, cuello, tórax (corazón, bronquios) y la mayor parte del abdomen (hasta el ángulo esplénico del colon). Porción SACRA (S2, S3, S4): Inerva las vísceras pélvicas (vejiga urinaria, recto, genitales). Por tanto, una lesión troncular afectará glándulas, bronquios y corazón, pero NUNCA a la vejiga urinaria.","source":"Neurociencias – Tema 1.5.2 - PARES CRANEALES | entrada I-103 / G1240 del banco canónico | integración: Tema 1.5.1 + Tema 1.5.2 + Tema 1.12 | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #5, #161, #217) / perguntas neuro julio exame.docx (Pregunta #68, #15) / TEMA 15 – SISTEMA NERVIOSO AUTÓNOMO.pdf","topic":"1.5.2","document":"02-TECC29-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.2-147","number":"147","statement":"¿Cuál de los siguientes efectos fisiológicos viscerales depende de la estimulación parasimpática transmitida a través del Nervio Vago (X par craneal)?:","options":["Aumento de la secreción gástrica y de la motilidad intestinal.","Erección de los cuerpos cavernosos del pene.","Relajación del músculo detrusor de la vejiga urinaria.","Miosis y acomodación del cristalino."],"answer":0,"explanation":"No incluida en el material.","hack":"Hack del Alcance del Nervio Vago (X Par): Nervio Vago (X): Lleva parasimpático al TÓRAX Y ABDOMEN SUPERIOR/MEDIO (hasta el ángulo esplénico del colon) → Aumenta secreción de HCl, secreción pancreática y peristaltismo. Parasimpático Sacro (S2-S4): Controla el ABDOMEN INFERIOR Y PELVIS (vejiga, colon descendente, recto y erección). III, VII y IX Par: Controlan estructuras de la CABEZA (ojo, glándulas salivales y lagrimales).","source":"Neurociencias – Tema 1.5.2 - PARES CRANEALES | entrada I-104 / G1251 del banco canónico | integración: Tema 1.5.2 + Tema 1.12 | referencias indicadas: wuolah-free-Examen-Neuro-2.pdf (Pregunta #23) / wuolah-free-Examen-Neuro-3.pdf (Pregunta #33) / 11-28 Clase_ SNA","topic":"1.5.2","document":"02-TECC29-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.2-148","number":"148","statement":"La inervación parasimpática de las glándulas salivales mayores (submandibular y sublingual por el VII par craneal, y parótida por el IX par craneal) estimula una profusa secreción salival fluida. ¿Qué receptor muscarínico postsináptico media esta respuesta secretora acinar?:","options":["Receptores muscarínicos M3 (y M5).","Receptores adrenérgicos Alfa-2.","Receptores nicotínicos N2 de la placa neuromuscular.","Receptores histaminérgicos H1."],"answer":0,"explanation":"No incluida en el material.","hack":"Hack de los Receptores Muscarínicos M2 vs. M3:M2 (Cardíaco): Abundante en el corazón y músculo liso, produce efectos de freno (cronotropismo e inotropismo negativo). M3 (Glandular y Visceral): Media la secreción glandular (salival, gástrica, lacrimal) y la contracción del músculo liso visceral (peristaltismo e intestino).","source":"Neurociencias – Tema 1.5.2 - PARES CRANEALES | entrada I-105 / G1260 del banco canónico | integración: Tema 1.5.2 + Tema 1.12 | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #5, #161, #217) / TEMA 15 – SISTEMA NERVIOSO AUTÓNOMO.pdf / 09-22 Clase_ Anatomía del tronco del encéfalo y SNA","topic":"1.5.2","document":"02-TECC29-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.2-149","number":"149","statement":"El reflejo barorreceptor es el principal mecanismo de control autonómico a corto plazo de la presión arterial sistémica. ¿En qué núcleo sensitivo del tronco del encéfalo hacen su primera sinapsis los aferentes viscerales del seno carotídeo (IX par) y del arco aórtico (X par) para desencadenar los ajustes vasculares y cardíacos?:","options":["En el Núcleo del Tracto Solitario (NTS) en el bulbo raquídeo.","En el núcleo gracilis del bulbo raquídeo.","En el núcleo rojo del mesencéfalo.","En los núcleos salivatorios de la protuberancia."],"answer":0,"explanation":"No incluida en el material.","hack":"Hack del Núcleo del Tracto Solitario (NTS - Centro Aferente Visceral): Toda la información sensitiva visceral inconsciente (presión arterial por barorreceptores, pO₂/pCO₂ por quimiorreceptores, gusto y distensión abdominal) entra por los pares IX y X y sinapta en la porción visceral del Núcleo del Tracto Solitario (NTS).","source":"Neurociencias – Tema 1.5.2 - PARES CRANEALES | entrada I-106 / G1261 del banco canónico | integración: Tema 1.5.1 + Tema 1.5.2 + Tema 1.12 | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #168, #215) / ex. 2021 (respuestas).pdf (Pregunta #68) / 11-28 Clase_ SNA","topic":"1.5.2","document":"02-TECC29-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.2-150","number":"150","statement":"Las fibras sensitivas viscerales conducen información desde las vísceras hacia el SNC diferenciándose según la naturaleza funcional del estímulo. Señale el trayecto anatómico que siguen las aferencias nociceptivas (dolor visceral por isquemia o distensión) en comparación con las aferencias fisiológicas no nociceptivas (barorreceptores, pH, saciedad):","options":["Las aferencias nociceptivas viscerales acompañan a los nervios SIMPÁTICOS penetrando en los segmentos medulares T1-L2; mientras que las aferencias no nociceptivas acompañan a los nervios PARASIMPÁTICOS hacia el tronco encefálico (NTS por pares IX y X) y médula sacra (S2-S4).","El dolor visceral viaja exclusivamente por el nervio óptico (II par).","Las aferencias no nociceptivas viajan por las raíces anteriores motoras de C1-C8.","Todas las aferencias viscerales sinaptan en el cerebelo flóculo-nodular."],"answer":0,"explanation":"No incluida en el material.","hack":"Hack de la Ruta de Aferencias Viscerales (Dolor Simpático vs. Regulación Parasimpática): Dolor Visceral (Isquemia, cólico, distensión): Acompaña al SIMPÁTICO → Ramos comunicantes blancos → Ganglio de la raíz posterior → Astas posteriores medulares T1-L2 (da origen al dolor referido). Reflejos Fisiológicos (Barorrecepción, vaciado): Acompañan al PARASIMPÁTICO → Nervio Vago (X) o Nervios Pélvicos (S2-S4) → NTS o Médula sacra.","source":"Neurociencias – Tema 1.5.2 - PARES CRANEALES | entrada I-107 / G1262 del banco canónico | integración: Tema 1.4 + Tema 1.5.1 + Tema 1.5.2 + Tema 1.10 + Tema 1.12 | referencias indicadas: 11-28 Clase_ Sistema Nervioso Autónomo — Parasimpático, Aferencias Viscerales / TEMA 15 – SISTEMA NERVIOSO AUTÓNOMO.pdf / UNIDAD 1. Tema 1.12 SNA I-II.pdf","topic":"1.5.2","document":"02-TECC29-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.2-151","number":"151","statement":"Indique la acción antagónica CORRECTA de las divisiones simpática y parasimpática sobre las estructuras musculares intrínsecas del ojo (pupila y músculo ciliar):","options":["El parasimpático (III par, ganglio ciliar) produce Miosis (contracción del esfínter de la pupila por M3/M5) y Acomodación de cerca (contracción del músculo ciliar); mientras que el simpático (ganglio cervical superior) produce Midriasis (contracción del músculo radial por α1) y Relajación del músculo ciliar para visión lejana (por β2).","El simpático produce miosis y el parasimpático midriasis.","El parasimpático paraliza la córnea y el simpático destruye el cristalino.","Ambas divisiones producen constricción pupilar simultánea."],"answer":0,"explanation":"No incluida en el material.","hack":"Hack Ocular del SNA:PARASIMPÁTICO: Miosis (Esfínter del iris / M3) + Acomodación de cerca (Contracción del M. Ciliar / M3). SIMPÁTICO: Midriasis (Dilatador del iris / α1) + Acomodación lejana (Relajación del M. Ciliar / β2).","source":"Neurociencias – Tema 1.5.2 - PARES CRANEALES | entrada I-108 / G1263 del banco canónico | integración: Tema 1.5.2 + Tema 1.11.1 + Tema 1.12 | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #50, #94) / TEMA 15 – SISTEMA NERVIOSO AUTÓNOMO.pdf / 11-28 Clase_ SNA","topic":"1.5.2","document":"02-TECC29-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.2-152","number":"152","statement":"Un paciente acude por ptosis palpebral del ojo derecho. Para diferenciar de forma inmediata entre una lesión del Nervio Oculomotor (III par) y una lesión de la Cadena Simpática Cervical (Síndrome de Horner), ¿qué signo pupilar e inervatorio permite establecer el diagnóstico diferencial exacto?:","options":["La presencia de Midriasis arreactiva e incapacidad para aducir el ojo indica lesión del III Par (afectación parasimpática); mientras que la presencia de Miosis y ptosis parcial indica un Síndrome de Horner (afectación simpática).","El III par produce miosis y el simpático midriasis paralítica con estrabismo interno.","Ambos cuadros cursan con midriasis arreactiva bilateral.","La lesión del III par respeta siempre el músculo elevador del párpado superior."],"answer":0,"explanation":"No incluida en el material.","hack":"Hack Clínico Oculomotor vs. Simpático (Aitana HACK 24 - Cruzamento #3): Lesión del III Par (Motor Somático + Parasimpático): Ptosis completa (M. elevador) + Ojo desviado \"abajo y afuera\" + MIDRIASIS (falla el esfínter pupilar). Síndrome de Horner (Simpático Cervical): Ptosis parcial (M. tarsal liso de Müller) + MIOSIS (domina el tono parasimpático) + Anhidrosis.","source":"Neurociencias – Tema 1.5.2 - PARES CRANEALES | entrada I-109 / G1267 del banco canónico | integración: Tema 1.5.2 + Tema 1.11.1 + Tema 1.12 | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #205, #274) / wuolah-free-Examen-Neuro-3.pdf (Pregunta #41, #50) / 10-23 Clase_ Músculos Extraoculares","topic":"1.5.2","document":"02-TECC29-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.2-153","number":"153","statement":"Los axones del Tracto Corticonuclear (corticobulbar) se originan en la porción lateral de la corteza motora primaria y descienden para inervar las motoneuronas inferiores de los núcleos motores del tronco del encéfalo. Señale la afirmación CORRECTA respecto a la bilateralidad de esta inervación motora craneofacial:","options":["La mayoría de los núcleos motores reciben inervación corticonuclear bilateral, EXCEPTO la porción del Núcleo Motor del Facial (VII) que controla los músculos de la cara inferior (que recibe inervación contralateral pura) y el Núcleo del Hipogloso (XII) para el geniogloso.","Todos los núcleos motores del tronco reciben inervación estrictamente ipsilateral sin decusación.","La musculatura masticatoria inervada por el V3 recibe control motor 100% contralateral exclusivo.","El tracto corticonuclear no pasa por la cápsula interna y desciende por los cordones posteriores medulares."],"answer":0,"explanation":"No incluida en el material.","hack":"Hack de la Parálisis Facial Central vs. Periférica (Aitana HACK 24 - Cruzamento #7): Inervación Bilateral: Frente, cejas, ojos y músculos masticatorios (una lesión supranuclear de un lado NO paraliza la frente). Inervación Contralateral Pura: Músculos de la mitad inferior de la cara (cuadrante inferior contralateral). Por eso un ictus cortical causa parálisis central de la boca del lado opuesto, respetando el ojo y la frente.","source":"Neurociencias – Tema 1.5.2 - PARES CRANEALES | entrada I-110 / G1269 del banco canónico | integración: Tema 1.5.1 + Tema 1.5.2 + Tema 1.7 + Tema 1.9.1 | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #40) / 10-14 Clase_ Control Motor y Vías Descendentes / TEMA 8 – CORTEZA MOTORA Y VÍAS MOTORAS .pdf","topic":"1.5.2","document":"02-TECC29-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.2-154","number":"154","statement":"Durante la exploración del Reflejo Fotomotor, la iluminación del ojo derecho desencadena una miosis rápida en la pupila del ojo izquierdo (Reflejo Consensual). ¿Qué estructura mesencefálica permite que la señal aferente visual cruce a ambos lados para activar simultáneamente la eferencia parasimpática en el III par contralateral?:","options":["La comisura posterior (y la proyección bilateral desde el Área Pretectal hacia los dos Núcleos de Edinger-Westphal).","La decusación de las pirámides bulbares.","El cuerpo calloso ventral.","El fascículo longitudinal medial de la protuberancia."],"answer":0,"explanation":"No incluida en el material.","hack":"Hack de la Decusación Pretectal Consensual: Las células ganglionares especiales envían axones al Área Pretectal de ambos lados (cruzando por la Comisura Posterior del mesencéfalo). Cada área pretectal excita bilateralmente a los Núcleos de Edinger-Westphal (III Par) de la derecha y de la izquierda, asegurando que ambas pupilas se contraigan en perfecto equilibrio cromático y luminoso.","source":"Neurociencias – Tema 1.5.2 - PARES CRANEALES | entrada I-111 / G1274 del banco canónico | integración: Tema 1.5.1 + Tema 1.5.2 + Tema 1.11.1 + Tema 1.12 | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #120, #252, #274) / 10-27 Clase_ Vía Visual y Reflejos Oculares / TEMA 12 – VISIÓN.pdf","topic":"1.5.2","document":"02-TECC29-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.2-155","number":"155","statement":"Al estimular la córnea derecha con una mecha de algodón, se produce el parpadeo defensivo de ambos ojos (Reflejo Corneal). Sin embargo, al rozar la córnea derecha de un paciente con un traumatismo de la base del cráneo, no se produce parpadeo en ningún ojo; pero al rozar la córnea izquierda sano, ambos ojos parpadean normalmente. ¿Qué nervio craneal y qué rama específica se encuentra lesionada?:","options":["La rama Oftálmica del Nervio Trigémino (V1) derecha (aferencia sensitiva suspendida).","El Nervio Facial (VII) derecho (eferencia motora suspendida).","El Nervio Oculomotor (III) izquierdo.","El Nervio Óptico (II) derecho."],"answer":0,"explanation":"No incluida en el material.","hack":"Hack Aferencia (V1) vs. Eferencia (VII) en Reflejos Craneales: Lesión AFERENTE (V1 Derecho): Tocar la córnea DERECHA NO produce respuesta en NINGÚN ojo (el centro no se entera). Tocar la córnea IZQUIERDA produce parpadeo en AMBOS ojos. Lesión EFERENTE (VII Derecho): Tocar la córnea DERECHA no mueve el ojo derecho, pero el ojo IZQUIERDO SÍ parpadea (consensual motora conservada).","source":"Neurociencias – Tema 1.5.2 - PARES CRANEALES | entrada I-112 / G1275 del banco canónico | integración: Tema 1.5.1 + Tema 1.5.2 + Tema 1.11.1 | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #122, #185, #274) / 10-27 Clase_ Vía Visual y Reflejos Oculares / TEMA 4 – PARES CRANEALES .pdf","topic":"1.5.2","document":"02-TECC29-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.2-156","number":"156","statement":"Un paciente de 62 años es ingresado por instauración brusca de vértigo, ataxia de la marcha con desviación hacia la derecha, disfagia, disfonía, hipoestesia termoalgésica en la mitad DERECHA de la cara y pérdida de la sensibilidad dolorosa y térmica en el hemicuerpo IZQUIERDO. La resonancia magnética confirma un infarto bulbar dorsolateral derecho (Síndrome de Wallenberg). ¿Qué arteria cerebral/cerebelosa se encuentra ocluida y qué estructuras del bulbo dorsolateral justifican esta sintomatología mixta?:","options":["Oclusión de la Arteria Cerebelosa Posteroinferior (PICA); afectación del Núcleo Espinal del V (hipoestesia facial ipsilateral), Núcleo Ambiguo (disfagia y paresia velopalatina), Vía Espinotalámica (hipoestesia corporal contralateral) y Pedúnculo Cerebeloso Inferior / Vías Vestibulares (ataxia y vértigo).","Oclusión de la Arteria Espinal Anterior por afectación de las pirámides bulbares.","Oclusión de la Arteria Cerebral Media izquierda con afasia de Broca.","Sección completa de la cola de caballo en L5."],"answer":0,"explanation":"No incluida en el material.","hack":"Hack del Síndrome de Wallenberg (Bulbo Dorsolateral / PICA): Aitana lo usa como el ejemplo supremo de integración en clase: Cara IPSILATERAL (Dolor/Temp): Núcleo Espinal del Trigémino (V). Cuerpo CONTRALATERAL (Dolor/Temp): Vía Espinotalámica Lateral. Disfagia / Disfonía: Núcleo Ambiguo (pares IX y X). Ataxia / Vértigo: Pedúnculo Cerebeloso Inferior y Núcleos Vestibulares.","source":"Neurociencias – Tema 1.5.2 - PARES CRANEALES | entrada I-113 / G1285 del banco canónico | integración: Tema 1.3 + Tema 1.5.1 + Tema 1.5.2 + Tema 1.9.3 + Tema 1.10 + Tema 1.11.2 | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #185, #203) / 09-12 Clase_ Anatomía vascular cerebral / 10-30 Clase magistral_ Neuroanatomía meníngea, vías medulares","topic":"1.5.2","document":"02-TECC29-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.2-157","number":"157","statement":"La inervación sensitiva, gustativa y motora de la lengua está dividida entre cuatro pares craneales. Señale la correlación anatofisiológica CORRECTA sobre la sensibilidad gustativa y motora de la lengua:","options":["Los 2/3 anteriores reciben sensibilidad gustativa por el Nervio Cuerda del Tímpano (VII par, que viaja unido al nervio lingual de V3); el 1/3 posterior por el Nervio Glosofaríngeo (IX par); la base epiglótica por el Vago (X par); y toda la musculatura intrínseca/extrínseca es inervada por el Hipogloso (XII par, excepto el palatogloso inervado por X).","El nervio trigémino V3 inerva todos los botones gustativos de la lengua.","El nervio facial inerva todos los músculos intrínsecos de la lengua.","El nervio glosofaríngeo es exclusivamente motor somático."],"answer":0,"explanation":"No incluida en el material.","hack":"Hack de los 4 Reyes de la Lengua (V3, VII, IX, X, XII): Sensibilidad General (Tacto/Dolor): 2/3 anteriores = Lingual de V3; 1/3 posterior = IX Par. Sensibilidad Gustativa (Sabor): 2/3 anteriores = Cuerda del Tímpano del VII Par (vía lingual); 1/3 posterior = IX Par; Base = X Par. Motricidad: XII Par (Hipogloso).","source":"Neurociencias – Tema 1.5.2 - PARES CRANEALES | entrada I-114 / G1289 del banco canónico | integración: Tema 1.5.2 + Tema 1.11.3 | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #25, #62) / ex. 2021 (respuestas).pdf (Pregunta #23) / TEMA 14 – GUSTO Y OLFATO .pdf","topic":"1.5.2","document":"02-TECC29-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.2-158","number":"158","statement":"Un tumor pulmonar o una cirugía intratorácica que produce una lesión destructiva del Nervio Vago (X par) a nivel mediastínico por debajo de la emergencia del nervio laríngeo recurrente izquierdo. ¿Qué estructura de la cabeza o cuello NO se verá afectada por esta lesión intratorácica baja?:","options":["El Nervio Laríngeo Recurrente Izquierdo (que ya emergió rodeando el arco aórtico en el tórax superior para ascender a los músculos de la laringe).","El plexo cardíaco parasimpático.","El plexo pulmonar parasimpático.","El plexo celíaco para el estómago e intestino."],"answer":0,"explanation":"No incluida en el material.","hack":"Hack del Laríngeo Recurrente (Anatomía Topográfica): El Nervio Laríngeo Recurrente Izquierdo nace en el tórax superior, dobla por debajo del Arco Aórtico y \"recurre\" / sube inmediatamente hacia la laringe en el cuello. Por tanto, una lesión vagal más caudal en el mediastino inferior o abdomen destruirá la inervación parasimpática cardíaca, pulmonar o digestiva, pero NO afectará la voz/laringe.","source":"Neurociencias – Tema 1.5.2 - PARES CRANEALES | entrada I-115 / G1290 del banco canónico | integración: Tema 1.5.2 + Tema 1.12 | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #58, #59) / 11-28 Clase_ SNA / wuolah-free-EXAMEN-2017-2018-1 (1).pdf (Pregunta #59)","topic":"1.5.2","document":"02-TECC29-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.2-159","number":"159","statement":"Un joven sufre un traumatismo craneoencefálico en la región temporal con fractura del hueso escamoso. Tras un intervalo lúcido inicial, desarrolla cefalea intensa, estupor y anisocoria ipsilateral por herniación uncal. La TC muestra una colección hemática biconvexa (en forma de lenteja) entre el cráneo y la duramadre. ¿Qué vaso sanguíneo se ha desgarrado y cómo se diferencia de un Hematoma Subdural?:","options":["Desgarro de la Arteria Meníngea Media (rama de la maxilar) que produce un Hematoma Epidural arterial; a diferencia del Hematoma Subdural, que es de origen venoso por rotura de las venas puente en el espacio subaracnoideo/subdural y presenta forma en media luna.","Desgarro del seno sagital superior que produce un hematoma intraparenquimatoso.","Rotura de la arteria basilar con hemorragia ventricular pura.","Desgarro del plexo coroideo en el canal medular."],"answer":0,"explanation":"No incluida en el material.","hack":"Hack Hematoma Epidural (Arterial / Meníngea Media) vs. Subdural (Venoso / Venas Puente): Hematoma EPIDURAL: Traumatismo en el punto Pterion (temporal) → Rotura de la Arteria Meníngea Media → Presión arterial alta → Colección BICONVEXA / LENTEJA entre hueso y duramadre (intervalo lúcido breve). Hematoma SUBDURAL: Desgarro de Venas Puente (ancianos/atrofia) → Sangrado venoso lento → Colección EN MEDIA LUNA entre duramadre y aracnoides.","source":"Neurociencias – Tema 1.5.2 - PARES CRANEALES | entrada I-116 / G1296 del banco canónico | integración: Tema 1.3 + Tema 1.5.2 + Tema 1.7 | referencias indicadas: 09-09 Lección_ Cubiertas y Vascularización del Encéfalo / NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #120) / TEMA 1 – CUBIERTAS Y VASCULARIZACIÓN.pdf","topic":"1.5.2","document":"02-TECC29-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.2-160","number":"160","statement":"Analice las siguientes proposiciones integradoras de la neurobiología del sistema nervioso central extraídas del compendio oficial. Indique la ÚNICA combinación donde TODAS las proposiciones sean VERDADERAS:Las neuronas preganglionares autonómicas nacen del tubo neural, mientras que las postganglionares y sensitivas viscerales derivan de la cresta neural. El circuito de Papez conecta secuencialmente el Hipocampo → Fórnix → Cuerpos Mamilares → Tracto Mamilotalámico → Núcleo Anterior del Tálamo → Giro del Cíngulo. La parálisis facial central por lesión corticonuclear afecta únicamente al cuadrante inferior de la cara contralateral, respetando la frente y el ojo debido a la inervación bilateral de la porción superior del núcleo del VII par.","options":["1, 2 y 3 son VERDADERAS.","Solo 1 y 2 son verdaderas.","Solo 2 y 3 son verdaderas.","1, 2 y 3 son falsas."],"answer":0,"explanation":"No incluida en el material.","hack":"Hack del Gran Resumen de Integração Transversal: Proposición 1 (VERDADERA): Tubo Neural = Preganglionar / Cresta Neural = Postganglionar y Sensitivas Viscerales. Proposición 2 (VERDADERA): Ruta del Circuito de Papez (Memoria). Proposición 3 (VERDADERA): Parálisis Facial Central (Boca sola) vs. Periférica (Cara entera ipsilateral).","source":"Neurociencias – Tema 1.5.2 - PARES CRANEALES | entrada I-117 / G1297 del banco canónico | integración: Tema 1.2 + Tema 1.5.1 + Tema 1.5.2 + Tema 1.6 + Tema 1.7 + Tema 1.8 + Tema 1.9.1 + Tema 1.12 | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (HACK 24 - Preguntas de Integración #4, #14, #39, #40, #49, #106, #205, #241, #274)","topic":"1.5.2","document":"02-TECC29-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.2-161","number":"161","statement":"Durante el desarrollo de las placas motoras y sensitivas en el tubo neural, el Surco Limitante separa las placas alares de las placas basales. Indique la localización de origen embrionario del núcleo motor del XII par craneal (Hipogloso):","options":["En la Placa Basal (ventral) del Mielencéfalo.","En la Placa Alar (dorsal) del Metencéfalo.","En la Capa Marginal del Telencéfalo.","En la Placa del Techo del Mesencéfalo."],"answer":0,"explanation":"No incluida en el material.","hack":"Hack Placa Basal (Motor) vs. Placa Alar (Sensitivo): Placa BASAL (Ventral): Origina eferencias MOTORAS. Como el XII par (Hipogloso) inerva la musculatura de la lengua y se ubica en el bulbo (mielencéfalo), nace en la Placa Basal del Mielencéfalo. Placa ALAR (Dorsal): Origina aferencias SENSITIVAS.","source":"Neurociencias – Tema 1.5.2 - PARES CRANEALES | entrada I-118 / G1302 del banco canónico | integración: Tema 1.2 + Tema 1.5.1 + Tema 1.5.2 | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #3) / 10-30 Clase magistral_ Desarrollo embrionario / TEMA 16 – EMBRIOLOGÍA.pdf / perguntas neuro julio (Pregunta #66)","topic":"1.5.2","document":"02-TECC29-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.2-162","number":"162","statement":"¿Cómo se denomina el proceso de segmentación métamérica transitoria que ocurre en el Rombencéfalo embrionario para organizar el origen de los núcleos motores de varios pares craneales?1219:","options":["Rombómeras.","Somitas mesodérmicas.","Crestas ampulares.","Placodas efémeras."],"answer":0,"explanation":"No incluida en el material.","hack":"Hack de las Rombómeras (Aitana)1219: Aitana destaca en el audio: \"Las mismas segmentaciones que vemos en la médula espinal para formar las metámeras existen en el tronco del encéfalo (rombencéfalo) para formar los pares craneales y se llaman Rombómeras (hay 8 bien definidas)\"1219.","source":"Neurociencias – Tema 1.5.2 - PARES CRANEALES | entrada I-119 / G1304 del banco canónico | integración: Tema 1.2 + Tema 1.5.1 + Tema 1.5.2 | referencias indicadas: 10-30 Clase magistral_ Desarrollo embrionario / ex. 2 (respuestas).pdf (Pregunta #2)","topic":"1.5.2","document":"02-TECC29-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.2-163","number":"163","statement":"Las Rombómeras constituyen una segmentación metamérica interna transitoria del cerebro posterior (rombencéfalo). ¿Cuántos segmentos bien definidos se forman y qué componentes de los pares craneales organizan en asociación con los arcos faríngeos?:","options":["Se forman 8 rombómeras bien definidas que organizan los núcleos motores de los pares craneales motor eferentes (IV a XII).","Se forman 12 rombómeras que originan los fotorreceptores de la retina.","Se forman 3 rombómeras que originan exclusivamente el lóbulo frontal.","Se forman 20 rombómeras que forman los plexos coroideos."],"answer":0,"explanation":"No incluida en el material.","hack":"Hack de las 8 Rombómeras (Aitana HACK): Aitana enfatiza en la clase magistral: \"El rombencéfalo se segmenta en 8 rombómeras bien definidas. Cada rombómera expresa un gradiente de genes HOX que guía el desarrollo motor de los pares craneales (IV al XII) arrastrando la musculatura de los arcos faríngeos\".","source":"Neurociencias – Tema 1.5.2 - PARES CRANEALES | entrada I-120 / G1318 del banco canónico | integración: Tema 1.2 + Tema 1.5.1 + Tema 1.5.2 | referencias indicadas: 10-30 Clase magistral_ Desarrollo embrionario / NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #115) / ex. 2 (respuestas).pdf (Pregunta #2)","topic":"1.5.2","document":"02-TECC29-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.2-164","number":"164","statement":"En la cronología del desarrollo del sistema nervioso, la diferenciación celular precede al proceso de mielinización axónica. Señale la afirmación CORRECTA respecto al inicio de la mielinización en los nervios periféricos y craneales:","options":["En el sistema nervioso periférico, la mielinización comienza entre el 2º y 5º mes del desarrollo embrionario, iniciándose primero en los nervios motores y posteriormente en los sensitivos.","La mielinización ocurre antes en los axones asociativos corticales que en las raíces motoras.","Las fibras amielínicas C son mielinizadas por los oligodendrocitos del tubo neural en la 3ª semana.","La mielinización del SNC se completa totalmente antes del nacimiento en el día 28."],"answer":0,"explanation":"No incluida en el material.","hack":"Hack de la Mielinización (Primero Motor, Luego Sensitivo): Aitana lo remarca en la diapositiva de mielinización: \"Tanto en nervios espinales como en pares craneales, PRIMERO sucede la mielinización de los nervios motores y LUEGO los sensitivos\".","source":"Neurociencias – Tema 1.5.2 - PARES CRANEALES | entrada I-121 / G1320 del banco canónico | integración: Tema 1.2 + Tema 1.5.2 | referencias indicadas: Tema 1.2 - Embriología del SN 25-26.pdf / NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #115) / 11-06 Tutoría_ Neurofisiología y Neuroanatomía","topic":"1.5.2","document":"02-TECC29-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.2-165","number":"165","statement":"Sobre los senos venosos durales y la anatomía del seno cavernoso, señale la afirmación FALSA:","options":["En el interior del seno cavernoso (bañado directamente por la sangre venosa) se encuentra alojado el nervio facial (VII par craneal).","El seno sagital inferior recorre el borde inferior libre de la hoz del cerebro y conduce su sangre hacia el seno recto.","Los senos esfenoparietales de la fosa craneal anterior drenan su contenido directamente en los senos cavernosos.","Los senos venosos son conductos desprovistos de válvula constituidos entre las capas perióstica y meníngea de la duramadre."],"answer":0,"explanation":"No incluida en el material.","hack":"Hack del Contenido del Seno Cavernoso (Aitana HACK): Atraviesa el CENTRO del Seno Cavernoso: Arteria Carótida Interna y Nervio Abducens (VI par). Discurren en la PARED LATERAL: III par, IV par, V1 y V2.El VII par (Facial) NUNCA pasa por el seno cavernoso; penetra directamente en el peñasco por el conducto auditivo interno.","source":"Neurociencias – Tema 1.5.2 - PARES CRANEALES | entrada I-122 / G1332 del banco canónico | integración: Tema 1.3 + Tema 1.5.2 | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #220) / ex. 2021 (respuestas).pdf (Pregunta #3) / Recopilación preguntas neuro (1).pdf / perguntas neuro julio","topic":"1.5.2","document":"02-TECC29-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.2-166","number":"166","statement":"El seno cavernoso es una fosa venosa dural compleja situada a ambos lados de la silla turca. ¿Qué par craneal discurre por el CENTRO del seno cavernoso (bañado directamente por la sangre venosa) junto a la Arteria Carótida Interna?:","options":["Nervio Abducens (VI par craneal).","Nervio Oculomotor (III par craneal).","Nervio Troclear (IV par craneal).","Rama Maxilar del Trigémino (V2)."],"answer":0,"explanation":"No incluida en el material.","hack":"Hack de la Posición en el Seno Cavernoso (Centro vs. Pared Lateral): Atraviesa el CENTRO (Lumen Venoso): Arteria Carótida Interna y Nervio Abducens (VI). Es el primer nervio en paralisarse ante una trombosis o aneurisma carotídeo interno dentro del seno. En la PARED LATERAL: III, IV, V1 y V2 (de arriba a abajo).","source":"Neurociencias – Tema 1.5.2 - PARES CRANEALES | entrada I-123 / G1342 del banco canónico | integración: Tema 1.3 + Tema 1.5.2 | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #220) / 09-09 Clase_ Prolongaciones de la Duramadre y Senos Venosos / Tema 1.3 - Cubiertas y vascularización del encéfalo 25-26.pdf","topic":"1.5.2","document":"02-TECC29-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.2-167","number":"167","statement":"Un gran hematoma o masa en el hemisferio cerebral desplaza el uncus del lóbulo temporal a través del borde libre de la tienda del cerebelo (Herniación Uncal o Transtentorial). ¿Qué par craneal resulta comprimido en la incisura tentorial produciendo midriasis paralítica e incapacidad para mover el ojo?:","options":["Nervio Oculomotor (III par craneal).","Nervio Óptico (II par craneal).","Nervio Trigémino (V par craneal).","Nervio Hipogloso (XII par craneal)."],"answer":0,"explanation":"No incluida en el material.","hack":"Hack del Anuncio de Herniación Uncal (Anisocoria / Miosis → Midriasis III Par): Al herniarse el uncus temporal por la escotadura tentorial, comprime primero las fibras parasimpáticas periféricas del Nervio Oculomotor (III) que discurren por fuera del tronco, causando MIDRIASIS paralítica e irreactiva ipsilateral (signo de focalidad crítico previo a la compresión del pedúnculo cerebral).","source":"Neurociencias – Tema 1.5.2 - PARES CRANEALES | entrada I-124 / G1348 del banco canónico | integración: Tema 1.3 + Tema 1.5.2 + Tema 1.7 | referencias indicadas: 09-09 Lección_ Cubiertas y Vascularización del Encéfalo / NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #120) / Tema 1.3 - Cubiertas y vascularización del encéfalo 25-26.pdf","topic":"1.5.2","document":"02-TECC29-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.2-168","number":"168","statement":"La duramadre craneal es una estructura rica en terminaciones sensitivas nociceptivas responsables del dolor de cabeza en meningitis o tumores. ¿Qué par craneal proporciona la mayor parte de la inervación sensitiva a la duramadre de las fosas craneales anterior y media?:","options":["El Nervio Trigémino (V par craneal, a través de sus ramas V1, V2 y V3).","El Nervio Facial (VII par craneal).","El Nervio Hipogloso (XII par craneal).","El Nervio Olfatorio (I par craneal)."],"answer":0,"explanation":"No incluida en el material.","hack":"Hack de la Inervación Dural (V1/V2/V3 vs. X/C1-C3): Fosa Craneal Anterior y Media + Hoz del Cerebro: Inervadas por las ramas meníngeas del Nervio Trigémino (V). Fosa Craneal Posterior + Tienda del Cerebelo: Inervadas por ramos meníngeos del Nervio Vago (X) y nervios espinales cervicales superiores (C1-C3).","source":"Neurociencias – Tema 1.5.2 - PARES CRANEALES | entrada I-125 / G1353 del banco canónico | integración: Tema 1.3 + Tema 1.5.2 | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #83) / perguntas neuro julio / TEMA 1 – CUBIERTAS Y VASCULARIZACIÓN.pdf","topic":"1.5.2","document":"02-TECC29-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.2-169","number":"169","statement":"Las cisternas subaracnoideas son dilataciones donde el espacio subaracnoideo se ensancha significativamente. Señale la localización anatómica de la Cisterna Interpeduncular:","options":["Se ubica en la cara ventral del mesencéfalo, entre los dos pedúnculos cerebrales, alojando en su interior al Polígono de Willis y al origen del III par craneal.","Se ubica por encima del cuerpo calloso entre las dos hemisferios.","Se ubica en el interior del canal ependimario lumbar.","Se ubica en la fosa nasal anterior."],"answer":0,"explanation":"No incluida en el material.","hack":"Hack de la Cisterna Interpeduncular (Polígono de Willis / III Par): La Cisterna Interpeduncular baña la fosa interpeduncular del mesencéfalo. Contiene el Polígono de Willis y la emergencia del Nervio Oculomotor (III). Su sangrado por rotura aneurismática causa una hemorragia subaracnoidea grave.","source":"Neurociencias – Tema 1.5.2 - PARES CRANEALES | entrada I-126 / G1356 del banco canónico | integración: Tema 1.3 + Tema 1.5.1 + Tema 1.5.2 | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #83) / ex. 2021 (respuestas).pdf (Pregunta #1) / perguntas neuro julio","topic":"1.5.2","document":"02-TECC29-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.2-170","number":"170","statement":"Un proceso infeccioso de la región facial media (Triángulo de la Muerte) puede diseminarse por vía venosa retrógrada hacia el seno cavernoso causando una Trombosis del Seno Cavernoso. ¿Qué nervio craneal de los que discurren por el seno cavernoso es el PRIMERO en afectarse clínicamente produciendo paresia de la aducción ocular?:","options":["El Nervio Abducens (VI par craneal), por encontrarse suspendido libremente en el interior del lumen venoso junto a la arteria carótida interna.","El Nervio Óptico (II par craneal).","El Nervio Olfatorio (I par craneal).","El Nervio Hipogloso (XII par craneal)."],"answer":0,"explanation":"No incluida en el material.","hack":"Hack Vulnerabilidad del VI Par en el Seno Cavernoso: Aitana lo explica en las tutorías: A diferencia del III, IV y V1 (que están \"protegidos\" en la pared dural lateral), el VI Par (Abducens) viaja dentro de la sangre venosa del seno cavernoso pegado a la carótida interna. Cualquier aumento de presión, inflamación o trombosis dentro del seno comprime de inmediato al VI Par, imposibilitando la abducción ocular del lado afecto.","source":"Neurociencias – Tema 1.5.2 - PARES CRANEALES | entrada I-127 / G1358 del banco canónico | integración: Tema 1.3 + Tema 1.5.2 | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #220) / 09-09 Clase_ Prolongaciones de la Duramadre y Senos Venosos / 11-06 Tutoría","topic":"1.5.2","document":"02-TECC29-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.2-171","number":"171","statement":"Con relación a la anatomía del Seno Cavernoso y el trayecto de los nervios craneales que con él se relacionan, señale la afirmación FALSA:","options":["La división mandibular del nervio trigémino (V3) discurre por la pared lateral del seno cavernoso antes de salir por el foramen oval.","El nervio abducens (VI par) es especialmente susceptible a lesiones por encontrarse en el centro del seno y en contacto directo con la arteria carótida interna.","El nervio oculomotor (III par) y el nervio troclear (IV par) discurren por la pared dural lateral del seno cavernoso.","Los senos esfenoparietales de la fosa craneal anterior drenan su sangre venosa directamente en los senos cavernosos."],"answer":0,"explanation":"No incluida en el material.","hack":"Hack de la Falsa Trayectoria de V3 en el Seno Cavernoso: Aitana lo enfatiza en la tutoría de exámenes: Transcurren por la Pared LATERAL del Seno Cavernoso: III Par, IV Par, V1 (Oftálmico) y V2 (Maxilar). NO pasa por el Seno Cavernoso: V3 (Mandibular) nace en el ganglio trigeminal y sale directamente hacia abajo por el Foramen Oval sin tocar la pared del seno. La banca intenta hacer creer que las tres ramas del trigémino pasan por la pared del seno cavernoso.","source":"Neurociencias – Tema 1.5.2 - PARES CRANEALES | entrada I-128 / G1365 del banco canónico | integración: Tema 1.3 + Tema 1.5.2 | pregunta original 36 de la carga nueva | referencias indicadas: wuolah-free-UNIRESUMEN-DOCUMENTO-GRATIS-PARES-CRANEALES.pdf (Preguntas #35 y #36) / ex. 2021 (respuestas).pdf (Pregunta #3) / 11-06 Tutoría","topic":"1.5.2","document":"02-TECC29-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.2-172","number":"172","statement":"La hoz del cerebro (falx cerebri) y la tienda del cerebelo (tentorium cerebelli) reciben inervación sensitiva para la conducción del dolor meníngeo. ¿Qué rama específica del nervio trigémino proporciona la inervación a la hoz del cerebro y a la tienda del cerebelo (a través del Nervio Tentorial de Arnold)?:","options":["Ramas del Nervio Oftálmico (V1).","Ramas del Nervio Mandibular (V3).","Ramas del Nervio Maxilar (V2).","Ramos posteriores de los nervios espinales cervicales C4-C5."],"answer":0,"explanation":"No incluida en el material.","hack":"Hack Inervación de la Hoz del Cerebro (V1 / Oftálmico): V1 (Nervio Oftálmico): Emite el Nervio Recurrente Meningeo / Tentorial (de Arnold) que vuelve hacia atrás para inervar la Hoz del Cerebro y la Tienda del Cerebelo. Por ello, la irritación meníngea supratentorial refiere dolor hacia la región frontal y retroorbitaria (campo de V1).","source":"Neurociencias – Tema 1.5.2 - PARES CRANEALES | entrada I-129 / G1372 del banco canónico | integración: Tema 1.3 + Tema 1.5.2 + Tema 1.9.3 | pregunta original 43 de la carga nueva | referencias indicadas: wuolah-free-Examen-Neuro-recu-junio-2023 orc.pdf (Pregunta #8) / Tema 1.3 - Cubiertas y vascularización del encéfalo 25-26.pdf / 09-09 Clase_ Prolongaciones de la Duramadre","topic":"1.5.2","document":"02-TECC29-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.2-173","number":"173","statement":"El Tentorio o Tienda del Cerebelo (tentorium cerebelli) divide la cavidad craneal en dos compartimentos principales: supratentorial e infratentorial. ¿Qué estructura anatómica atraviesa el borde libre anterior (incisura tentorial) de esta prolongación dural?:","options":["El Mesencéfalo.","El Bulbo Raquídeo en la decusación de las pirámides.","La arteria meníngea media en el foramen espinoso.","El canal ependimario de la médula lumbar."],"answer":0,"explanation":"No incluida en el material.","hack":"Hack de la Incisura Tentorial y el Mesencéfalo (Aitana HACK): La abertura cóncava anterior de la tienda del cerebelo (incisura del tentorio) rodea estrechamente al Mesencéfalo y da paso a los tractos ascendentes/descendentes y al nervio oculomotor (III par). Ante un edema supratentorial masivo, la herniación uncal comprime el mesencéfalo y el III par en este borde rígido.","source":"Neurociencias – Tema 1.5.2 - PARES CRANEALES | entrada I-130 / G1380 del banco canónico | integración: Tema 1.3 + Tema 1.5.1 + Tema 1.5.2 + Tema 1.9.3 | pregunta original 51 de la carga nueva | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Preguntas #257, #258) / 09-09 Clase_ Prolongaciones de la Duramadre y Senos Venosos / Tema 1.3 - Cubiertas y vascularización del encéfalo 25-26.pdf","topic":"1.5.2","document":"02-TECC29-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.2-174","number":"174","statement":"La Arteria Cerebelosa Anteroinferior (AICA) es una importante rama del sistema vertebro-basilar. Indique el núcleo motor de par craneal y el nervio periférico que discurren en íntima relación con la AICA en el ángulo pontocerebeloso:","options":["Los nervios Facial (VII par) y Vestibulococlear (VIII par).","El nervio olfatorio (I par).","El nervio hipogloso (XII par).","El nervio troclear (IV par) exclusivamente."],"answer":0,"explanation":"No incluida en el material.","hack":"Hack AICA + VII y VIII Par en el Ángulo Pontocerebeloso: La AICA rodea el puente e ingresa al ángulo pontocerebeloso junto al VII y VIII Par Craneal, emitiendo allí la Arteria Laberíntica. Un bucle vascular o neurinoma en esta zona comprime el VII y VIII par e interrumpe el flujo de la AICA.","source":"Neurociencias – Tema 1.5.2 - PARES CRANEALES | entrada I-131 / G1391 del banco canónico | integración: Tema 1.3 + Tema 1.5.2 + Tema 1.11.2 | pregunta original 62 de la carga nueva | referencias indicadas: 09-12 Clase_ Anatomía vascular cerebral / ex. 2021 (respuestas).pdf (Pregunta #8) / TEMA 1 – CUBIERTAS Y VASCULARIZACIÓN.pdf","topic":"1.5.2","document":"02-TECC29-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.2-175","number":"175","statement":"Un aneurisma sacular en la unión de la Arteria Carótida Interna con la Arteria Comunicante Posterior pende hacia la fosa interpeduncular. ¿Qué par craneal resulta comprimido directamente produciendo diplopía y ptosis palpebral con pupilas midriáticas?:","options":["El Nervio Oculomotor (III par craneal).","El Nervio Abducens (VI par craneal).","El Nervio Troclear (IV par craneal).","El Nervio Trigémino (V par craneal)."],"answer":0,"explanation":"No incluida en el material.","hack":"Hack Aneurisma Comunicante Posterior = Compresión del III Par (Aitana HACK): El III Par Craneal emerge en la fosa interpeduncular y pasa justo al lado de la Arteria Comunicante Posterior. Un aneurisma en este punto comprime de inmediato las fibras parasimpáticas periféricas del III par cause midriasis e ptosis.","source":"Neurociencias – Tema 1.5.2 - PARES CRANEALES | entrada I-132 / G1399 del banco canónico | integración: Tema 1.3 + Tema 1.5.2 | pregunta original 70 de la carga nueva | referencias indicadas: 09-11 Clase_ LCR y Vascularización Cerebral / NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #235) / Tema 1.3","topic":"1.5.2","document":"02-TECC29-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.2-176","number":"176","statement":"La Arteria Cerebelosa Superior (SUCA / SCA) nace de la arteria basilar justo antes de su bifurcación terminal. ¿Qué estructuras del tronco y cerebelo irriga principalmente y qué nervio pasa inmediatamente por debajo de ella?:","options":["Irriga la cara superior del cerebelo, el tectum mesencefálico y el pedúnculo cerebeloso superior; el Nervio Oculomotor (III par) pasa entre la SUCA y la ACP.","Irriga el lóbulo frontal y el nervio óptico.","Irriga la amígdala cerebelosa y el nervio hipogloso.","Irriga el bulbo raquídeo inferior y el nervio vago."],"answer":0,"explanation":"No incluida en el material.","hack":"Hack de la \"Pinza Arterial\" del III Par Craneal (ACP vs. SUCA): El Nervio Oculomotor (III Par) emerge en la fosa interpeduncular passando JUSTO ENTRE dos arterias: por arriba la Arteria Cerebral Posterior (ACP) y por abajo la Arteria Cerebelosa Superior (SUCA).","source":"Neurociencias – Tema 1.5.2 - PARES CRANEALES | entrada I-133 / G1404 del banco canónico | integración: Tema 1.3 + Tema 1.5.1 + Tema 1.5.2 + Tema 1.9.3 | pregunta original 75 de la carga nueva | referencias indicadas: 09-12 Clase_ Anatomía vascular cerebral / TEMA 1 – CUBIERTAS Y VASCULARIZACIÓN / 10-27 Clase_ Vía Visual\n\nCONTROL DE INTEGRIDAD\n- Tema: TEMA 1.5.2 - PARES CRANEALES\n- Preguntas tipo test recibidas en el dossier: 176 | entregadas: 176\n- Casos clínicos con alternativas (detección aproximada por palabras clave del enunciado): 13 (cada uno ya es una entrada independiente con el caso completo); subpreguntas adicionales: 0; casos abiertos: 0\n- Preguntas sin clave explícita (Respuesta correcta: NO INDICADA): ninguna\n- Preguntas con claves contradictorias o múltiples (REVISAR): ninguna\n- Preguntas cuyo enunciado no figura en el material de origen (alternativas conservadas, enunciado marcado): ninguna\n- Fragmentos ilegibles o incompletos: ninguno detectado salvo los enunciados ausentes indicados arriba.\n- Se conservaron todas las preguntas, alternativas, claves y justificaciones. Se eliminaron únicamente marcadores de referencia de NotebookLM ([12i], [3], \"generated by NotebookLM to PDF\"), números de nota al pie, pies de página y restos de conversación/índices ajenos a cada pregunta.\n- Siguiente pregunta pendiente: ninguna (entrega completa de este tema).","topic":"1.5.2","document":"02-TECC29-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-1","number":"1","statement":"¿Cuál de los siguientes núcleos o estructuras neuroanatómicas se localiza específicamente en el hipotálamo?:","options":["Habenular","Septal","Mamilar (cuerpos mamilares)","Periacueductal"],"answer":2,"explanation":"No incluida en el material.","hack":"Los cuerpos mamilares constituyen la región mamilar (posterior) de la base del hipotálamo. Los núcleos habenulares pertenecen al epitálamo, los núcleos septales al telencéfalo basal y la sustancia gris periacueductal al mesencéfalo.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada N-001 / G0073 del banco canónico | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Adicional_Parte2.pdf | referencias indicadas: wuolah-free-Examen-Neuro-recu-junio-2023 orc.pdf (Pregunta #28) / wuolah-free- PREGUNTAS-TEST-NEURO-DIENCEFALO-.pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-2","number":"2","statement":"¿Cuál de los siguientes núcleos NO forma parte de la región tuberal (media) del hipotálamo?:","options":["Núcleo dorsomedial","Núcleo hipotalámico anterior","Núcleo ventromedial","Núcleo arcuato (infundibular)"],"answer":1,"explanation":"No incluida en el material.","hack":"Organización Zonal del Hipotálamo: Región Supraóptica (Anterior): Núcleo supraóptico, paraventricular, supraquiasmático y hipotalámico anterior. Región Tuberal (Media): Núcleos dorsomedial, ventromedial y arcuato/infundibular. Trap: La banca coloca el \"núcleo hipotalámico anterior\" entre los tuberales para confundir por proximidad anatómica.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada N-002 / G0074 del banco canónico | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Adicional_Parte2.pdf | referencias indicadas: ex. 2 (respuestas).pdf (Pregunta #22) / wuolah-free-tema-5-preguntas.pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-3","number":"3","statement":"En relación con la organización general y funciones del diencéfalo, señale la relación CORRECTA:","options":["Adherencia intertalámica — Lateral con respecto al tercer ventrículo.","Núcleo pulvinar — Forma parte del grupo nuclear anterior del tálamo.","Núcleos de la habénula — Centros relacionados con el olfato localizados próximos al receso supraquiasmático.","Hipotálamo — Regula respuestas humorales gracias a su relación anatómica directa con la hipófisis."],"answer":3,"explanation":"No incluida en el material.","hack":"Las opciones A, B y C contienen trampas clásicas: la adherencia intertalámica es medial/central (cruza el III ventrículo); el pulvinar es el extremo posterior del tálamo; la habénula se sitúa en el receso epifisario/posterior, no supraquiasmático. La opción D es la única VERDADERA por el control vascular (porta) y neuroaxonal directo sobre la hipófisis.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada N-003 / G0075 del banco canónico | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Adicional_Parte2.pdf | referencias indicadas: wuolah-free-PREGUNTAS-TEST-NEURO-DIENCEFALO-.pdf / TEMA 5 – DIENCÉFALO .pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-4","number":"4","statement":"Sobre la neurofisiología del núcleo arqueado (arcuato) del hipotálamo en el control de la conducta alimentaria, es CIERTO que:","options":["Es superior con respecto al núcleo preóptico medial hipotalámico.","Puede inhibir al área hipotalámica lateral, lo cual inhibe la conducta alimentaria y el hambre.","No responde a los niveles circulantes de leptina.","Sus neuronas liberan neuropeptído Y para inhibir la conducta alimentaria."],"answer":1,"explanation":"No incluida en el material.","hack":"Mecanismo del Núcleo Arcuato: Contiene neuronas anorexigénicas (POMC/CART) que responden a la leptina e inhiben directamente al Área Hipotalámica Lateral (que sintetiza orexinas), cortando el estímulo del hambre. El Neuropeptídeo Y (NPY) estimula la ingesta, no la inhibe.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada N-004 / G0076 del banco canónico | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Adicional_Parte2.pdf | referencias indicadas: wuolah-free-EXAMEN-NEURO-2-SIN-RESPUESTAS.pdf / ex. 2022 (sin respuestas) 2.pdf (Pregunta #26)","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-5","number":"5","statement":"Señale la opción FALSA sobre las funciones homeostáticas del hipotálamo:","options":["El área hipotalámica lateral responde frente al neuropeptído Y (NPY).","Los órganos circunventriculares participan en la regulación de la sed e ingesta de agua.","El hipotálamo es capaz de ayudar en la producción de calor corporal.","El núcleo hipotalámico posterior es el máximo responsable de estimular la conducta alimentaria."],"answer":3,"explanation":"No incluida en el material.","hack":"Es la FALSA porque el centro responsable de estimular la conducta alimentaria (centro del hambre) es el Área Hipotalámica Lateral. El núcleo hipotalámico posterior se encarga de la integración del sistema simpático y de la producción/conservación de calor (tiritona).","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada N-005 / G0077 del banco canónico | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Adicional_Parte2.pdf | referencias indicadas: wuolah-free-Examen-Neuro-recu-junio-2023 orc.pdf (Pregunta #29) / TEMA 5 – DIENCÉFALO .pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-6","number":"6","statement":"¿Qué es el infundíbulo hipotalámico desde el punto de vista de la anatomía del diencéfalo?:","options":["Una estructura del diencéfalo que se extiende desde el tuber cinereum y se continúa con la hipófisis (tallo hipofisario).","Una parte del tálamo posterior que contiene los cuerpos geniculados.","Un tracto de sustancia blanca que une el núcleo rojo con el núcleo subtalámico.","El límite posterior entre el diencéfalo y el cuarto ventrículo."],"answer":0,"explanation":"No incluida en el material.","hack":"El infundíbulo es el tallo de sustancia nerviosa que emerge del tuber cinereum en el piso del III ventrículo para conectar directamente el hipotálamo con la glándula hipófisis, albergando el sistema porta hipofisario y el tracto hipotálamo-hipofisario.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada N-006 / G0080 del banco canónico | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Adicional_Parte2.pdf | referencias indicadas: 09-30 Clase_ Diencéfalo / TEMA 5 – DIENCÉFALO .pdf / wuolah-free-PREGUNTAS-EXAMEN-DE- NEURO.pdf (Pregunta #5)","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-7","number":"7","statement":"En las conexiones del diencéfalo, la profesora Aitana recalca en clase el error típico de examen al confundir la estría terminal con la estría medular del tálamo. Indique la afirmación CORRECTA sobre la trayectoria y destino de la estría medular del tálamo:","options":["Nace en las áreas septales e hipotálamo anterior y discurre por el ángulo dorsomedial del tálamo para terminar en los núcleos habenulares del epitálamo.","Nace en la amígdala y rodea al núcleo caudado para terminar en el cuerpo mamilar.","Conecta directamente la neurohipófisis con la corteza visual primaria (área 17).","Es el tracto eferente que forma las pirámides bulbares."],"answer":0,"explanation":"No incluida en el material.","hack":"Hack de la Profesora Aitana sobre las Estrías (Aviso de Examen en Audio): Estría Terminal: Conecta la Amígdala con el hipotálamo (\"Estría terminal = McDonald's/Amígdala\"). Estría Medular del Tálamo: Bordea el techo del tálamo y termina en la Habénula / Epitálamo (\"Estría medular = a la Habénula\").","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada N-007 / G0081 del banco canónico | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Adicional_Parte2.pdf | referencias indicadas: 09-30 Clase_ Diencéfalo - Tálamo, Hipotálamo y Epitálamo.mp / Nervioso T21-T22- 20250930_163918-Grabación de la reunión 1 (1).mp / TEMA 5 – DIENCÉFALO .pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-8","number":"8","statement":"El núcleo preóptico medial del hipotálamo destaca por presentar dimorfismo sexual (núcleo dimórfico sexual, significativamente mayor en varones). ¿Cuál es su función endocrina y conductual primaria?:","options":["Sintetizar la Hormona Liberadora de Gonadotropinas (GnRH) para regular el eje hipófiso-gonadal y coordinar el comportamiento sexual y reproductor.","Secretar insulina para reducir la glucemia.","Sintetizar melatonina durante el día.","Controlar el movimiento voluntario del pulgar."],"answer":0,"explanation":"No incluida en el material.","hack":"El Núcleo Preóptico Medial es el centro de control gonadotrópico. Produce GnRH que estimula la liberación de LH y FSH en la adenohipófisis, regulando la función testicular/ovárica y la conducta sexual.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada N-008 / G0085 del banco canónico | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Adicional_Parte2.pdf | referencias indicadas: 10-06 Clase_ Neuroanatomía del Hipotálamo / TEMA 5 – DIENCÉFALO .pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-9","number":"9","statement":"En las radiografías y tomografías de cráneo de adultos, la glándula pineal (epífisis) suele aparecer como una pequeña calcificación en la línea media del diencéfalo. ¿Qué nombre reciben estas concreciones de fosfato y carbonato cálcico que aumentan fisiológicamente con la edad?:","options":["Acérvulos cerebrales (o \"arenilla cerebral\" / corpora arenacea)","Cuerpos de Herring","Placas seniles de amiloide","Nódulos de Schmorl"],"answer":0,"explanation":"No incluida en el material.","hack":"Los acérvulos cerebrales (corpora arenacea) son depósitos de calcio en la glándula pineal que carecen de significado patológico y sirven como punto de referencia anatómico fundamental en la línea media en estudios de neuroimagen.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada N-009 / G0096 del banco canónico | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Adicional_Parte2.pdf | referencias indicadas: 09-30 Clase_ Diencéfalo - Tálamo, Hipotálamo y Epitálamo.mp / TEMA 5 – DIENCÉFALO .pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-10","number":"10","statement":"En relación al diencéfalo, señala la relación CORRECTA:","options":["Adherencia intertalámica — Lateral con respecto al tercer ventrículo.","Núcleo pulvinar — Forma parte del grupo anterior del tálamo.","Núcleos de la habénula — Centros relacionados con el olfato localizados próximos al receso supraquiasmático.","Hipotálamo — Regula respuestas humorales gracias a su relación anatómica con la hipófisis."],"answer":3,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada N-010 / G0502 del banco canónico | archivos: Neuro_Parte2.pdf | referencias indicadas: PREGUNTAS-TEST-NEURO-DIENCEFALO-.pdf / ex. 2021 (respuestas).pdf (Pregunta #21 / Test Diencéfalo)","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-11","number":"11","statement":"Sobre la clasificación de los núcleos hipotalámicos, señala la asociación INCORRECTA:","options":["Núcleo dorsomedial — región tuberal.","Núcleo paraventricular — región lateral.","Núcleo supraquiasmático — región supraóptica.","Núcleo arcuato — región tuberal."],"answer":1,"explanation":"[Nota de la clave] O núcleo paraventricular pertence à região supraóptica/medial).","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada N-011 / G0504 del banco canónico | archivos: Neuro_Parte2.pdf | referencias indicadas: ex. 2 (respuestas).pdf (Pregunta #20) / ex. 2 (sin respuestas) (1, 2, 3 y 16).pdf (Pregunta #20)","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-12","number":"12","statement":"¿Cuál de los siguientes núcleos NO forma parte de la región tuberal hipotalámica?:","options":["Dorsomedial.","Núcleo hipotalámico anterior.","Ventromedial.","Arcuato o arqueado."],"answer":1,"explanation":"[Nota de la clave] Pertence à região supraóptica/rostral, e não à região tuberal).","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada N-012 / G0506 del banco canónico | archivos: Neuro_Parte2.pdf | referencias indicadas: ex. 2 (respuestas).pdf (Pregunta #22) / wuolah-free-tema-5- preguntas.pdf (Pregunta #22)","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-13","number":"13","statement":"Sobre la anatomía del tálamo es FALSO que:","options":["La adhesión intertalámica es medial con respecto al giro dentado.","Presenta núcleos como el pulvinar o el ventral anterior.","Tiene una lámina medular externa ubicada entre el núcleo reticular del tálamo y la masa lateral talámica.","Todos sus núcleos son visibles externamente, sin necesidad de realizar corte alguno."],"answer":3,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada N-013 / G0507 del banco canónico | archivos: Neuro_Parte2.pdf | referencias indicadas: wuolah-free-Examen-Neuro-recu-junio-2023 orc.pdf (Pregunta #26) / Tema 1.6 - Diencéfalo 25-26.pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-14","number":"14","statement":"El núcleo geniculado lateral se caracteriza por:","options":["Recibir información visual.","Recibir información auditiva.","Recibir información nociceptiva.","Recibir información propioceptiva desde el cerebelo."],"answer":0,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada N-014 / G0508 del banco canónico | archivos: Neuro_Parte2.pdf | referencias indicadas: wuolah-free-Examen-Neuro-recu-junio-2023 orc.pdf (Pregunta #27) / Recopilación preguntas neuro (1).pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-15","number":"15","statement":"¿Cuál de los siguientes núcleos se encuentra en el hipotálamo?:","options":["Habenular.","Septal.","Mamilar.","Periacueductal."],"answer":2,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada N-015 / G0509 del banco canónico | archivos: Neuro_Parte2.pdf | referencias indicadas: wuolah-free-Examen-Neuro-recu-junio-2023 orc.pdf (Pregunta #28) / wuolah-free-tema-5-preguntas.pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-16","number":"16","statement":"¿Cuál de los siguientes núcleos talámicos forma parte de los circuitos de control motor?","options":["N. Ventral anterior","N. Ventral posterior medial","N. Ventral posterior lateral","N. Intralaminares"],"answer":0,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada N-016 / G0510 del banco canónico | archivos: Neuro_Parte2.pdf | referencias indicadas: ex. 2021 (respuestas).pdf / wuolah-free-EXAMEN-NEURO-2-SIN- RESPUESTAS.pdf (Pregunta #27 / #66)","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-17","number":"17","statement":"¿Cuál de las siguientes regiones hipotalámicas NO está implicada en la regulación del comportamiento alimentario?","options":["N. Supraóptico","N. Arcuato","Núcleos hipotalámicos laterales","Núcleo paraventricular"],"answer":0,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada N-017 / G0512 del banco canónico | archivos: Neuro_Parte2.pdf | referencias indicadas: ex. 2021 (respuestas).pdf / wuolah-free-EXAMEN-2017-2018-1.pdf (Pregunta #29 / #68)","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-18","number":"18","statement":"Sobre el núcleo arqueado (arcuato) del hipotálamo es CIERTO que:","options":["Es superior con respecto al núcleo preóptico medial hipotalámico.","Puede inhibir al área hipotalámica lateral, lo cual inhibe la conducta alimentaria.","No responde a la leptina.","Sus neuronas liberan neuropeptido Y para inhibir la conducta alimentaria."],"answer":1,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada N-018 / G0513 del banco canónico | archivos: Neuro_Parte2.pdf | referencias indicadas: ex. 2022 (sin respuestas) 2.pdf / Exame Neuro 2022.pdf (Pregunta #26)","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-19","number":"19","statement":"Señala la afirmación INCORRECTA sobre la anatomía del diencéfalo:","options":["La adherencia (o adhesión) intertalámica se encuentra medial a los ventrículos laterales.","El quiasma óptico se encuentra en la base del diencéfalo, anterior al hipotálamo.","La glándula pineal se encuentra en la región posteromedial del diencéfalo.","Los núcleos subtalámicos se localizan anteriores con respecto a los cuerpos mamilares."],"answer":3,"explanation":"Aclaración de la usuaria: la D es la afirmación FALSA. El núcleo subtalámico (de Luys) se ubica posterior y dorsolateral a los cuerpos mamilares; la D invierte la relación anteroposterior. La A es VERDADERA: la adherencia intertalámica cruza la línea media dentro del tercer ventrículo y queda medial a los ventrículos laterales (clave del origen: D / A).","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada N-019 / G0514 del banco canónico | archivos: Neuro_Parte2.pdf; NEURO_275_ORGANIZADO_POR_TEMA_HACK24(1).pdf; NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf | referencias indicadas: perguntas neuro julio exame.docx (Pregunta #22)","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-20","number":"20","statement":"Sobre el hipotálamo es FALSO que:","options":["Es capaz de controlar respuestas viscerales gracias a tractos descendentes como el mamilotegmental.","La activación del área hipotalámica lateral provoca una inhibición del apetito.","Las neuronas del núcleo arcuato son sensibles a la leptina.","La presencia de citoquinas proinflamatorias puede activar núcleos hipotalámicos responsables de elevar la temperatura corporal."],"answer":1,"explanation":"[Nota de la clave] Falso: el área lateral estimula el hambre; su lesión provoca anorexia).","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada N-020 / G0515 del banco canónico | archivos: Neuro_Parte2.pdf; NEURO_275_ORGANIZADO_POR_TEMA_HACK24(1).pdf; NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf | referencias indicadas: perguntas neuro julio exame.docx (Pregunta #56)","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-21","number":"21","statement":"¿Qué es el infundíbulo?:","options":["Una estructura del diencéfalo que se continúa con la hipófisis.","Una parte del tálamo que contiene el núcleo supraquiasmático.","Una estructura que contiene los tractos espinotalámico y tracto mamilotalámico.","Es la estructura que delimita el tálamo de diencéfalo.","La parte final del hipotálamo que comunica la glándula pineal con la habénula."],"answer":0,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada N-021 / G0516 del banco canónico | archivos: Neuro_Parte2.pdf | referencias indicadas: wuolah-free-PREGUNTAS-EXAMEN-DE-NEURO.pdf (Pregunta #5)","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-22","number":"22","statement":"La sustancia gris del tálamo:","options":["Se puede dividir en dos grandes grupos: grupo superior y grupo inferior.","Se puede dividir en dos grandes grupos: grupo anterior y grupo posterior.","Se puede dividir en tres grandes grupos: grupo anterior, grupo posterior y grupo medial.","Se puede dividir en tres grandes grupos: grupo anterior, grupo medial y grupo lateral."],"answer":3,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada N-022 / G0518 del banco canónico | archivos: Neuro_Parte2.pdf | referencias indicadas: wuolah-free-tema-5-preguntas.pdf (Pregunta #1) / wuolah-free- Examen-Neuro-1 (1).pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-23","number":"23","statement":"Respecto a los núcleos habenulares del epitálamo, señale la afirmación CORRECTA:","options":["Son parte del subtálamo.","Su principal vía aferente proviene del hipocampo a través de las fibras musgosas.","Se localizan en la región epitalámica (parte posterior del diencéfalo) y participan en la integración de respuestas emocionales y viscerales.","Se encuentran unidos entre sí por el cuerpo calloso."],"answer":2,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada N-023 / G0519 del banco canónico | archivos: Neuro_Parte2.pdf | referencias indicadas: wuolah-free-EXAMEN-2017-2018-1 (1).pdf / ex. 2021 (respuestas).pdf (Pregunta #26)","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-24","number":"24","statement":"El núcleo anterior del tálamo:","options":["Manda axones a los núcleos basales (putamen y globo pálido).","Manda axones al lóbulo frontal exclusivamente a la corteza motora primaria.","Manda axones a la circunvolución del cíngulo.","Manda axones a la corteza somatosensorial primaria."],"answer":2,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada N-024 / G0520 del banco canónico | archivos: Neuro_Parte2.pdf | referencias indicadas: wuolah-free-tema-5-preguntas.pdf (Pregunta #3) / wuolah-free- examen-3.pdf (Pregunta #15)","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-25","number":"25","statement":"La hipófisis (glándula pituitaria) se divide funcionalmente en:","options":["Tres áreas o lóbulos: superior, medial e inferior.","Dos áreas o lóbulos: anterior o adenohipófisis y posterior o neurohipófisis.","Dos áreas o lóbulos: anterior o neurohipófisis y posterior o adenohipófisis.","Dos áreas o lóbulos: superior o neurohipófisis e inferior o adenohipófisis.","Dos áreas o lóbulos: superior o adenohipófisis e inferior o neurohipófisis."],"answer":1,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada N-025 / G0522 del banco canónico | archivos: Neuro_Parte2.pdf | referencias indicadas: wuolah-free-tema-5-preguntas.pdf (Pregunta #5) / wuolah-free- Examen-Neuro-1 (1).pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-26","number":"26","statement":"Los órganos circunventriculares (como el órgano subfornical o el OVLT) se caracterizan histológicamente por:","options":["Presentar una barrera hematoencefálica especialmente reinforced.","No presentar barrera hematoencefálica (capilares fenestrados).","Por contener exclusivamente las células magnocelulares secretoras de oxitocina.","Por ser un núcleo de sustancia gris con forma de anillo dentro del grupo medial del tálamo.","Ninguna de las anteriores es correcta."],"answer":1,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada N-026 / G0523 del banco canónico | archivos: Neuro_Parte2.pdf | referencias indicadas: wuolah-free-tema-5-preguntas.pdf (Pregunta #8) / wuolah-free- Examen-Neuro-1 (1).pdf (Pregunta #20)","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-27","number":"27","statement":"Señala la afirmación FALSA sobre las siguientes funciones hipotalámicas:","options":["El área hipotalámica lateral responde frente al neuropéptido Y.","Los órganos circunventriculares participan en la regulación de la sed- ingesta de agua.","El hipotálamo es capaz de ayudar en la producción de calor corporal.","El núcleo hipotalámico posterior es el máximo responsable de estimular la conducta alimentaria."],"answer":3,"explanation":"[Nota de la clave] O centro da fome e estimulação do comportamento alimentar é a área hipotalâmica lateral; a lesão desta área causa anorexia).","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada N-027 / G0526 del banco canónico | archivos: Neuro_Parte2.pdf | referencias indicadas: wuolah-free-Examen-Neuro-recu-junio-2023 orc.pdf (Pregunta #29) / Tema 1.6 - Diencéfalo 25-26.pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-28","number":"28","statement":"Sobre la anatomía del diencéfalo es CIERTO que:","options":["La adherencia (o adhesión) intertalámica se encuentra lateral con respecto al tercer ventrículo.","La lámina terminal se encuentra en el límite anterior del hipotálamo.","Los cuerpos mamilares se encuentran dorsales con respecto al resto de núcleos hipotalámicos.","El epitálamo se encuentra en el límite anterior del hipotálamo."],"answer":1,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada N-028 / G0527 del banco canónico | archivos: Neuro_Parte2.pdf | referencias indicadas: perguntas neuro julio exame.docx (Pregunta #28) / Tema 1.6 - Diencéfalo 25-26.pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-29","number":"29","statement":"¿Cuál de los siguientes núcleos talámicos establece conexiones eferentes directas con cortezas cerebrales asociativas (como la prefrontal o la del cíngulo)?:","options":["Núcleo ventral lateral posterior.","Núcleo dorsomedial (DM).","Núcleo reticular del tálamo.","Núcleo geniculado medial."],"answer":1,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada N-029 / G0529 del banco canónico | archivos: Neuro_Parte2.pdf | referencias indicadas: examenes neuro compl (1).pdf (Pregunta #55) / wuolah-free-EXAMEN- 2017-2018-1 (1).pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-30","number":"30","statement":"¿Cuál de las siguientes estructuras NO presenta una relación anatómica directa con alguna de las superficies del tálamo?:","options":["Cuerpos mamilares.","III Ventrículo.","Estrato zonal (capa zonal).","Cápsula interna."],"answer":0,"explanation":"[Nota de la clave] Os corpos mamilares pertencem ao hipotálamo inferior/posterior, não estando em contato anatômico direto com a superfície livre do tálamo).","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada N-030 / G0530 del banco canónico | archivos: Neuro_Parte2.pdf | referencias indicadas: Recopilación preguntas neuro (1).pdf / TEMA 5 – DIENCÉFALO .pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-31","number":"31","statement":"En la topografía y orientación espacial del tálamo, la región ventral se corresponde con la zona:","options":["Anterior.","Posterior.","Inferior.","Superior."],"answer":2,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada N-031 / G0531 del banco canónico | archivos: Neuro_Parte2.pdf | referencias indicadas: wuolah-free-Examen-Neuro-recu-junio-2023 orc.pdf (Pregunta #60) / Tema 1.6 - Diencéfalo 25-26.pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-32","number":"32","statement":"Cuando se produce un ayuno prolongado:","options":["Aumenta la cantidad de leptina.","Disminuye la cantidad de leptina.","La activación de las neuronas correspondientes del núcleo arqueado activa la división simpática del sistema nervioso autónomo.","El núcleo paraventricular del hipotálamo activa a la adenohipófisis para que produzca ACTH y TSH.","La activación de las neuronas correspondientes del núcleo arqueado inhibe al área hipotalámica lateral reguladora de la conducta alimentaria."],"answer":1,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada N-032 / G0534 del banco canónico | archivos: Neuro_Parte2.pdf | referencias indicadas: wuolah-free-tema-5-preguntas.pdf (Pregunta #6) / wuolah-free- examen-3.pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-33","number":"33","statement":"Cuando se produce un aumento de la temperatura corporal:","options":["Aumenta la liberación de TSH por parte de la adenohipófisis.","Es detectado por las neuronas del núcleo supraquiasmático del hipotálamo.","Es detectado por las neuronas del núcleo preóptico medial del hipotálamo.","Aumenta la liberación de vasopresina por parte de las células magnocelulares del núcleo paraventricular.","Ninguna de las anteriores es correcta."],"answer":2,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada N-033 / G0535 del banco canónico | archivos: Neuro_Parte2.pdf | referencias indicadas: wuolah-free-tema-5-preguntas.pdf (Pregunta #7) / wuolah-free- examen-3.pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-34","number":"34","statement":"Sobre el hipotálamo es FALSO que:","options":["La lámina terminal marca el límite anterior del hipotálamo.","El fascículo mamilotegmental comunica el hipotálamo con la formación reticular troncoencefálica.","Según la hipótesis lipostática, el aumento de la leptina liberada desde el tejido adiposo activa centros hipotalámicos que activan a su vez las conductas alimentarias.","El hipotálamo regula tanto el aumento como la disminución de la temperatura corporal."],"answer":2,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada N-034 / G0536 del banco canónico | archivos: Neuro_Parte2.pdf | referencias indicadas: wuolah-free-PREGUNTAS-TEST-NEURO-DIENCEFALO-.pdf / ex. 2022 (sin respuestas) 2.pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-35","number":"35","statement":"Los axones de las vías retino-hipotalámicas que transmiten la información sobre el ciclo luz/oscuridad proceden de:","options":["Los fotorreceptores tipo bastón exclusivamente.","Células ganglionares intrínsecamente fotosensibles (ipRGCs).","Las células bipolares de la retina periférica.","Células horizontales de la capa plexiforme externa."],"answer":1,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada N-035 / G0537 del banco canónico | archivos: Neuro_Parte2.pdf | referencias indicadas: wuolah-free-EXAMEN-2017-2018-1 (1).pdf (Pregunta #4) / ex. 2021 (respuestas).pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-36","number":"36","statement":"Indica cuál de los siguientes núcleos NO pertenece al hipotálamo:","options":["Núcleo dorsomedial.","Núcleo infundibular (arcuato).","Núcleo paraventricular.","Núcleo infraóptico."],"answer":3,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada N-036 / G0539 del banco canónico | archivos: Neuro_Parte2.pdf | referencias indicadas: perguntas neuro julio exame.docx (Pregunta #54) / TEMA 5 – DIENCÉFALO .pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-37","number":"37","statement":"Sobre el núcleo reticular del tálamo, señale la afirmación CORRECTA:","options":["Se localiza en la lámina medular interna, junto al núcleo centromediano.","Es el único núcleo talámico que ejerce un efecto inhibidor (GABAérgico) sobre los demás núcleos talámicos para regular su excitabilidad.","Proyecta axones directamente hacia la corteza motora primaria para iniciar el movimiento.","Recibe únicamente aferencias del cerebelo y no se conecta con la corteza cerebral."],"answer":1,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada N-037 / G0541 del banco canónico | archivos: Neuro_Parte2.pdf | referencias indicadas: 10-30 Clase magistral_ Neuroanatomía meníngea, vías medulares.mp / Tema 1.6 - Diencéfalo 25-26.pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-38","number":"38","statement":"¿Cuál de las siguientes regiones hipotalámicas NO está directamente involucrada en la regulación del comportamiento alimentario o la saciedad?:","options":["Núcleo supraóptico.","Núcleo arcuato (arqueado).","Núcleos hipotalámicos laterales.","Núcleo ventromedial."],"answer":0,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada N-038 / G0547 del banco canónico | archivos: Neuro_Parte2.pdf | referencias indicadas: wuolah-free-EXAMEN-2017-2018-1 (1).pdf / ex. 2021 (respuestas).pdf (Pregunta #68)","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-39","number":"39","statement":"La lámina medular interna del tálamo tiene forma de \"Y\" y sirve para dividir la sustancia gris talámica en los grupos anterior, medial y lateral. ¿Qué núcleo específico se encuentra embebido en el interior de dicha lámina?:","options":["Núcleo centromediano (intralaminar).","Núcleo geniculado lateral.","Núcleo pulvinar.","Núcleo ventral anterior."],"answer":0,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada N-039 / G0548 del banco canónico | archivos: Neuro_Parte2.pdf | referencias indicadas: 10-01 Clase_ Neuroanatomía - Tálamo e Hipotálamo.mp / Tema 1.6 - Diencéfalo 25-26.pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-40","number":"40","statement":"En relación al núcleo supraquiasmático del hipotálamo, señala la opción CORRECTA:","options":["Es el principal marcapasos biológico central que regula los ritmos circadianos.","Recibe información visual directamente desde el núcleo geniculado lateral a través de las fibras musgosas.","Se localiza en la región mamilar posterior del hipotálamo.","Inhibe de forma continua la liberación de melatonina durante la noche."],"answer":0,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada N-040 / G0553 del banco canónico | archivos: Neuro_Parte2.pdf | referencias indicadas: wuolah-free-tema-5-preguntas.pdf (Pregunta #15) / wuolah-free- EXAMEN-NEURO-2-SIN-RESPUESTAS.pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-41","number":"41","statement":"¿Qué estructura forma la pared lateral del tercer ventrículo en su porción superior e inferior, respectivamente?:","options":["El cuerpo calloso arriba y el puente abajo.","La cara medial del tálamo (arriba) y la cara medial del hipotálamo (abajo), separados por el surco hipotalámico.","El núcleo caudado arriba y el putamen abajo.","La cápsula interna arriba y la cápsula externa abajo."],"answer":1,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada N-041 / G0554 del banco canónico | archivos: Neuro_Parte2.pdf | referencias indicadas: PREGUNTAS-TEST-NEURO-DIENCEFALO-.pdf / wuolah-free-EXAMEN- 2017-2018-1 (1).pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-42","number":"42","statement":"¿Cuál de los siguientes núcleos hipotalámicos promueve la pérdida de calor (mecanismos de termólisis como la sudoración y vasodilatación) cuando aumenta la temperatura corporal?:","options":["Núcleo hipotalámico posterior.","Área/núcleo preóptico y anterior del hipotálamo.","Cuerpos mamilares.","Núcleo supraóptico."],"answer":1,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada N-042 / G0556 del banco canónico | archivos: Neuro_Parte2.pdf | referencias indicadas: perguntas neuro julio exame.docx (Pregunta #62) / Recopilación preguntas neuro (1).pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-43","number":"43","statement":"El infundíbulo hipotalámico es:","options":["La porción del hipotálamo que se continúa y conecta con la hipófisis.","Un núcleo del grupo lateral del tálamo.","La vía por donde discurren las fibras espinotalámicas.","El límite superior exclusivo del tercer ventrículo."],"answer":0,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada N-043 / G0558 del banco canónico | archivos: Neuro_Parte2.pdf | referencias indicadas: wuolah-free-tema-5-preguntas.pdf / wuolah-free-PREGUNTAS- EXAMEN-DE-NEURO.pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-44","number":"44","statement":"Indica la afirmación CORRECTA sobre la relación anatómica del hipotálamo y la hipófisis:1415","options":["La neurohipófisis (hipófisis posterior) recibe axones directos de neuronas neurosecretoras magnocelulares del hipotálamo.","La adenohipófisis es posterior a la neurohipófisis.","La neurohipófisis secreta ACTH y TSH directamente en respuesta a la leptina.","La adenohipófisis se conecta directamente con el III ventrículo sin pasar por el sistema porta."],"answer":0,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada N-044 / G0564 del banco canónico | archivos: Neuro_Parte2.pdf | referencias indicadas: PREGUNTAS-TEST-NEURO-DIENCEFALO-.pdf / 10-06 Clase_ Neuroanatomía del Hipotálamo","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-45","number":"45","statement":"¿Cuál de los siguientes núcleos talámicos pertenece al grupo anterior y proyecta axones hacia la circunvolución del cíngulo dentro del circuito límbico de Papez?:","options":["Núcleo pulvinar.","Núcleo anterior del tálamo.","Núcleo reticular del tálamo.","Núcleo ventral lateral."],"answer":1,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada N-045 / G0565 del banco canónico | archivos: Neuro_Parte2.pdf | referencias indicadas: wuolah-free-tema-5-preguntas.pdf / ex. 2 (respuestas).pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-46","number":"46","statement":"Sobre los límites anatómicos y relaciones del diencéfalo y del hipotálamo, señale la afirmación CORRECTA:","options":["La adherencia (o adhesión) intertalámica se localiza lateral con respecto al tercer ventrículo.","La lámina terminal marca el límite anatómico anterior del hipotálamo.","Los cuerpos mamilares se sitúan dorsales con respecto al resto de núcleos hipotalámicos.","El epitálamo se encuentra en el límite anterior del hipotálamo."],"answer":1,"explanation":"No incluida en el material.","hack":"Límite anterior del hipotálamo: Formado por la lámina terminal (que se extiende desde la comisura anterior hasta el quiasma óptico). Adherencia intertalámica: Atraviesa transversalmente el tercer ventrículo uniendo ambos tálamos por la línea media (NUNCA lateral al III ventrículo). Epitálamo: Se ubica en el límite posterior y superior/dorsal del diencéfalo, no anterior.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada N-046 / G0873 del banco canónico | archivos: Neuro_Adicional_Parte2.pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #28) / wuolah-free-PREGUNTAS-TEST-NEURO-DIENCEFALO-.pdf / 09-30 Clase_ Diencéfalo","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-47","number":"47","statement":"En la división regional del hipotálamo en sentido anteroposterior (regiones supraóptica, tuberal y mamilar), señale la asociación INCORRECTA entre núcleo y región:","options":["Núcleo dorsomedial — Región tuberal.","Núcleo paraventricular — Región lateral.","Núcleo supraquiasmático — Región supraóptica (anterior).","Núcleo arcuato (infundibular) — Región tuberal."],"answer":1,"explanation":"No incluida en el material.","hack":"Región Supraóptica (Anterior): Contiene los núcleos Supraóptico, Paraventricular, Supraquiasmático y Preóptico. Región Tuberal (Media): Contiene los núcleos Dorsomedial, Ventromedial y Arcuato (Infundibular). Región Mamilar (Posterior): Contiene los Cuerpos Mamilares y el Núcleo Posterior. El núcleo paraventricular se sitúa medialmente en la región supraóptica, NUNCA en la región lateral.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada N-047 / G0875 del banco canónico | archivos: Neuro_Adicional_Parte2.pdf | referencias indicadas: ex. 2 (respuestas).pdf (Pregunta #20) / ex. 2 (sin respuestas) (1, 2, 3 y 16).pdf (Pregunta #20) / TEMA 5 – DIENCÉFALO .pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-48","number":"48","statement":"Con respecto al control de la temperatura corporal ejercido por el hipotálamo, señale la afirmación FALSA:","options":["El área preóptica (hipotálamo anterior) contiene termorreceptores centrales sensibles al calor e inicia respuestas de disipación calórica (sudoración y vasodilatación cutánea).","El área hipotalámica posterior responde al frío e inicia respuestas de conservación y producción de calor (vasoconstricción cutánea y tiritona/escalofríos).","El núcleo hipotalámico posterior es el máximo responsable de estimular las respuestas de disipación de calor mediante tiritona.","Los pirógenos endógenos actúan sobre el área preóptica para reajustar el termostato corporal provocando fiebre."],"answer":2,"explanation":"No incluida en el material.","hack":"Hipotálamo ANTERIOR (Preóptico): \"A/C - Aire Acondicionado\" -> Disipación de calor (sudor, vasodilatación). Hipotálamo POSTERIOR: \"Estufa / Calefacción\" -> Generación y conservación de calor (tiritona, vasoconstricción). La alternativa C es FALSA porque la tiritona es una respuesta de generación/conservación de calor regulada por el hipotálamo posterior, no de disipación.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada N-048 / G0879 del banco canónico | archivos: Neuro_Adicional_Parte2.pdf | referencias indicadas: TEMA 5 – DIENCÉFALO .pdf / 09-30 Clase_ Diencéfalo / wuolah-free- PREGUNTAS-TEST-NEURO-DIENCEFALO-.pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-49","number":"49","statement":"En la región supraóptica (anterior) del hipotálamo, las neuronas neurosecretoras magnocelulares de los núcleos Supraóptico y Paraventricular sintetizan hormonas peptídicas que se transportan por vía axónica. ¿A través de qué tracto y hacia qué estructura neuroendocrina se dirigen para su almacenamiento y liberación a la circulación?:","options":["Tracto hipotálamo-hipofisario hacia la neurohipófisis (lóbulo posterior de la hipófisis).","Sistema porta hipofisario hacia la adenohipófisis.","Fórnix hacia el hipocampo.","Estriado hacia el núcleo caudado."],"answer":0,"explanation":"No incluida en el material.","hack":"Neurohipófisis (Posterior / Tejido Nervioso): Recibe los axones del tracto hipotálamo-hipofisario (de los núcleos supraóptico [ADH] y paraventricular [oxitocina]). No sintetiza hormonas, solo las almacena en los cuerpos de Herring y las libera. Adenohipófisis (Anterior / Tejido Glandular): Controlada por factores liberadores/inhibidores vertidos al sistema porta hipofisario por el tracto tuberoinfundibular (núcleo arcuato).","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada N-049 / G0882 del banco canónico | archivos: Neuro_Adicional_Parte2.pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #60) / TEMA 5 – DIENCÉFALO .pdf / 10-06 Clase_ Neuroanatomía del Hipotálamo","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-50","number":"50","statement":"Experimentos clásicos de lesión en modelos animales permitieron identificar los centros de regulación de la ingesta alimentaria en el hipotálamo. ¿Qué cuadro clínico produce la destrucción bilateral del Núcleo Ventromedial del hipotálamo frente a la destrucción del Área Hipotalámica Lateral?:","options":["La lesión del Núcleo Ventromedial produce hiperfagia u obesidad mórbida (al destruirse el centro de la saciedad), mientras que la lesión del Área Lateral produce afaxia y inanición (al destruirse el centro del hambre).","Ambas lesiones producen pérdida absoluta de peso sin alterar la conducta.","La lesión del Ventromedial causa diabetes insípida únicamente.","La lesión del Área Lateral hiperactiva el apetito."],"answer":0,"explanation":"No incluida en el material.","hack":"Núcleo Ventromedial: Centro de la SACIEDAD -> Lesión causa hiperfagia y obesidad. Hipotálamo Lateral: Centro del HAMBRE / APETITO -> Lesión causa anorexia, adipsia e inanición.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada N-050 / G0884 del banco canónico | archivos: Neuro_Adicional_Parte2.pdf | referencias indicadas: wuolah-free-PREGUNTAS-TEST-NEURO-DIENCEFALO-.pdf / ex. 2021 (respuestas).pdf (Pregunta #29) / TEMA 5 – DIENCÉFALO .pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-51","number":"51","statement":"El núcleo arcuato (infundibular) del hipotálamo, situado en la región tuberal alrededor del receso infundibular del tercer ventrículo, desempeña una función endocrina crucial al:","options":["Sintetizar péptidos hipofisiotrópicos (factores liberadores e inhibidores) que se vierten en el plexo capilar primario del sistema porta hipofisario para regular la adenohipófisis.","Liberar directamente oxitocina en la arteria basilar.","Conducir la propiocepción del pie.","Sintetizar melatonina durante el sueño NREM."],"answer":0,"explanation":"No incluida en el material.","hack":"El núcleo arcuato / infundibular contiene neuronas dopaminérgicas (PIH - Factor Inhibidor de la Prolactina) y secretoras de GnRH, GHRH, etc., que utilizan la vía del sistema porta hipofisario de la eminencia media para controlar la adenohipófisis.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada N-051 / G0886 del banco canónico | archivos: Neuro_Adicional_Parte2.pdf | referencias indicadas: TEMA 5 – DIENCÉFALO .pdf / 09-30 Clase_ Diencéfalo / wuolah-free- tema-5-preguntas.pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-52","number":"52","statement":"El núcleo dorsomedial del tálamo (DM) pertenece al grupo asociativo. ¿Con qué región cortical establece conexiones eferentes y aferentes recíprocas masivas para la integración de la conducta, la afectividad y la toma de decisiones?:","options":["Corteza de asociación prefrontal y estructuras del sistema límbico (amígdala e hipotálamo)","Corteza visual primaria (área 17)","Corteza auditiva primaria (giros de Heschl)","Área motora suplementaria exclusivamente"],"answer":0,"explanation":"No incluida en el material.","hack":"El Núcleo Dorsomedial (DM) es el principal núcleo de asociación del tálamo conectado con el lóbulo prefrontal. Su destrucción o la desconexión de sus fibras (como en la antigua lobotomía prefrontal) produce embotamiento afectivo, falta de previsión y cambios severos en la personalidad.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada N-052 / G0889 del banco canónico | archivos: Neuro_Adicional_Parte2.pdf | referencias indicadas: examenes neuro compl (1).pdf (Pregunta #55) / 10-08 Clase_ Sistema Límbico y Formación de la Memoria / TEMA 5 – DIENCÉFALO .pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-53","number":"53","statement":"Según la hipótesis lipostática de regulación del peso corporal, la leptina es una hormona liberada por el tejido adiposo proporcionalmente a las reservas de grasa. ¿Cuál es su mecanismo de acción sobre el núcleo arcuato (infundibular) del hipotálamo para reducir la ingesta?:","options":["Estimula las neuronas anorexigénicas (POMC/CART) e inhibe las neuronas orexigénicas (NPY/AgRP), disminuyendo el apetito y aumentando el gasto energético.","Inhibe el área preóptica provocando hipertermia severa.","Estimula directamente la secreción de melatonina en la epífisis.","Bloquea la liberación de vasopresina en la neurohipófisis."],"answer":0,"explanation":"No incluida en el material.","hack":"Es el Hack de Inversión de Leptina: En situaciones de ayuno (leptina baja), se activa el Neuropeptídeo Y (NPY) que estimula el hambre. Cuando sube la leptina (saciedad/reservas grasas altas), se inhibe el NPY y se estimula la MSH/POMC para cortar la conducta alimentaria.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada N-053 / G0892 del banco canónico | archivos: Neuro_Adicional_Parte2.pdf | referencias indicadas: wuolah-free-Examen-Neuro-recu-junio-2023 orc.pdf (Pregunta #29) / wuolah-free-tema-5-preguntas.pdf / TEMA 5 – DIENCÉFALO .pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-54","number":"54","statement":"Anatómicamente, el tálamo presenta cuatro caras (superior, inferior, medial y lateral). ¿Cuál de las siguientes estructuras NO presenta una relación anatómica directa con ninguna de las superficies externas del tálamo?:","options":["Cuerpos Mamilares","Tercer Ventrículo","Cápsula Interna (brazo posterior)","Estria terminal / Lámina medular externa"],"answer":0,"explanation":"No incluida en el material.","hack":"Pregunta Fija de Examen de la Profesora Aitana: Los cuerpos mamilares pertenecen anatómicamente al hipotálamo (región mamilar/posterior en la base del encéfalo) y NO tienen contacto ni relación anatómica directa con las caras externas del tálamo. La cara medial del tálamo limita con el III ventrículo y la lateral con la cápsula interna.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada N-054 / G0893 del banco canónico | archivos: Neuro_Adicional_Parte2.pdf | referencias indicadas: Recopilación preguntas neuro (1).pdf (Pregunta #38) / 09-30 Clase_ Diencéfalo / TEMA 5 – DIENCÉFALO .pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-55","number":"55","statement":"Señale la opción CORRECTA respecto a los límites anatómicos del hipotálamo:","options":["Su límite superior está marcado por el surco hipotalámico (de Monro), que lo separa de la cara medial del tálamo.","Su límite anterior es la fosa interpeduncular.","Su límite inferior es la comisura blanca anterior.","Su límite posterior es el quiasma óptico."],"answer":0,"explanation":"No incluida en el material.","hack":"Límites del Hipotálamo (Pregunta de Examen Habitual): Límite Superior: Surco hipotalámico (de Monro). Límite Anterior: Comisura anterior y lámina terminal. Límite Inferior / Suelo: Tuber cinereum, infundíbulo, quiasma óptico y cuerpos mamilares. Límite Posterior: Fosa e interpedúnculo del mesencéfalo.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada N-055 / G0898 del banco canónico | archivos: Neuro_Adicional_Parte2.pdf | referencias indicadas: wuolah-free-tema-5-preguntas.pdf (Pregunta #4) / TEMA 5 – DIENCÉFALO .pdf / 09-30 Clase_ Diencéfalo","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-56","number":"56","statement":"El grupo nuclear medial del tálamo está constituido fundamentalmente por el núcleo dorsomedial (DM). ¿Qué lámina de sustancia blanca lo separa de los grupos nucleares anterior y lateral del tálamo?:","options":["Lámina medular interna (con forma de \"Y\")","Lámina medular externa","Cápsula interna","Adherencia intertalámica"],"answer":0,"explanation":"No incluida en el material.","hack":"La lámina medular interna es una franja intra-talámica de sustancia blanca con forma de \"Y\" que divide al tálamo en tres grandes masas principales: anterior (entre los dos brazos de la Y), medial (medial a la Y) y lateral (lateral a la Y). Contiene además en su interior los núcleos intralaminares (como el centromediano).","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada N-056 / G0899 del banco canónico | archivos: Neuro_Adicional_Parte2.pdf | referencias indicadas: 10-01 Clase_ Neuroanatomía - Tálamo e Hipotálamo / TEMA 5 – DIENCÉFALO .pdf / NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-57","number":"57","statement":"Sobre la anatomía y configuración externa del tálamo, señale la afirmación FALSA:","options":["Todos sus núcleos son visibles externamente en la superficie del cerebro sin necesidad de realizar ningún corte.","Presenta núcleos prominentes como el pulvinar o el ventral anterior.","La adherencia intertalámica se localiza en la pared medial comunicando ambos tálamos a través del III ventrículo.","La lámina medular externa se ubica entre la masa lateral del tálamo y el núcleo reticular talámico."],"answer":0,"explanation":"No incluida en el material.","hack":"Es la FALSA porque el tálamo está compuesto por núcleos profundos cubiertos por sustancia blanca (láminas medulares) y por los hemisferios cerebrales. Solo sus superficies superior y medial asoman libremente a las cavidades ventriculares; sus núcleos internos requieren cortes parenquimatosos para ser visualizados.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada N-057 / G0901 del banco canónico | archivos: Neuro_Adicional_Parte2.pdf | referencias indicadas: wuolah-free-Examen-Neuro-recu-junio-2023 orc.pdf (Pregunta #26) / 09-30 Clase_ Diencéfalo","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-58","number":"58","statement":"¿Qué estructura del epitálamo recibe aferencias del núcleo supraquiasmático hipotalámico para sintetizar y secretar melatonina durante las horas de oscuridad?:","options":["Glándula pineal (epífisis)","Núcleo pulvinar","Zona incierta del subtálamo","Cuerpo mamilar lateral"],"answer":0,"explanation":"No incluida en el material.","hack":"Circuito de Secreción de Melatonina: Luz -> Retina (ipRGC) -> Núcleo Supraquiasmático -> Vía simpática (ganglio cervical superior) -> Glándula Pineal (Epífisis). La luz inhibe la producción de melatonina; la oscuridad la estimula.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada N-058 / G0902 del banco canónico | archivos: Neuro_Adicional_Parte2.pdf | referencias indicadas: 09-30 Clase_ Diencéfalo / TEMA 5 – DIENCÉFALO .pdf / wuolah-free- PREGUNTAS-TEST-NEURO-DIENCEFALO-.pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-59","number":"59","statement":"En el sistema porta hipofisario, los capilares primarios donde las neuronas del núcleo arcuato vierten las hormonas liberadoras e inhibidoras se ubican específicamente en:","options":["La eminencia media del tuber cinereum y el tallo infundibular.","El cuerpo calloso.","La fosa romboidea del cuarto ventrículo.","La comisura blanca posterior."],"answer":0,"explanation":"No incluida en el material.","hack":"La eminencia media es una zona especializada de la base del hipotálamo (tuber cinereum) rica en plexos capilares fenestrados (sin barrera hematoencefálica) donde termina el tracto tuberoinfundibular para verter los péptidos estimuladores/inhibidores que viajan hacia la adenohipófisis.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada N-059 / G0903 del banco canónico | archivos: Neuro_Adicional_Parte2.pdf | referencias indicadas: 10-06 Clase_ Neuroanatomía del Hipotálamo / TEMA 5 – DIENCÉFALO .pdf / NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-60","number":"60","statement":"Señala la afirmación FALSA sobre las siguientes funciones hipotalámicas:","options":["El área hipotalámica lateral responde frente al neuropéptido Y.","Los órganos circunventriculares participan en la regulación de la sed-ingesta de agua.","El hipotálamo es capaz de ayudar en la producción de calor corporal.","El núcleo hipotalámico posterior es el máximo responsable de estimular la conducta alimentaria."],"answer":3,"explanation":"[Nota de la clave] O centro da fome e estimulação do comportamento alimentar é a área hipotalâmica lateral; a lesão desta área causa anorexia).","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada N-060 / G0904 del banco canónico | referencias indicadas: wuolah-free-Examen-Neuro-recu-junio-2023 orc.pdf (Pregunta #29) / Tema 1.6 - Diencéfalo 25-26.pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-61","number":"61","statement":"Con relación a los núcleos talámicos es FALSO que:","options":["El núcleo anterior está involucrado en la fijación de la memoria.","El núcleo ventral posterolateral recibe información sensorial del cuerpo.","El núcleo reticular envía axones a diferentes regiones de la corteza cerebral.","El núcleo geniculado medial es responsable de la transmisión de la información auditiva."],"answer":2,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada N-061 / G0985 del banco canónico | archivos: NEURO_275_ORGANIZADO_POR_TEMA_HACK24(1).pdf; NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf | referencias indicadas: NEURO_275_ORGANIZADO_POR_TEMA_HACK24(1).pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-62","number":"62","statement":"Sobre la hipótesis lipostática es CIERTO que:","options":["El aumento de los niveles de leptina en sangre produce una disminución de la tasa metabólica.","La activación del núcleo paraventricular del hipotálamo estimula la liberación de hormonas por la adenohipófisis.","El núcleo arqueado produce neuropéptido Y para inhibir la conducta alimentaria.","El área hipotalámica lateral se encuentra inhibido cuando los niveles de leptina circulantes disminuyen."],"answer":1,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada N-062 / G0986 del banco canónico | archivos: NEURO_275_ORGANIZADO_POR_TEMA_HACK24(1).pdf; NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf | referencias indicadas: NEURO_275_ORGANIZADO_POR_TEMA_HACK24(1).pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-63","number":"63","statement":"Indica la afirmación FALSA sobre la fisiología hipotalámica:","options":["La disminución del flujo sanguíneo renal induce la producción hipotalámica de vasopresina.","El mecanismo de sed volumétrica conlleva una respuesta de vasodilatación al activar el sistema nervioso parasimpático.","Los receptores del órgano vascular de la lámina terminal informan área hipotalámica lateral de una eventual situación hiperosmolar.","Los pirógenos activan el área preóptica hipotalámica e inician respuestas de disipación de calor."],"answer":1,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada N-063 / G0987 del banco canónico | archivos: NEURO_275_ORGANIZADO_POR_TEMA_HACK24(1).pdf; NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf | referencias indicadas: NEURO_275_ORGANIZADO_POR_TEMA_HACK24(1).pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-64","number":"64","statement":"Sobre la hipótesis lipostática es CIERTO que:","options":["El aumento de los niveles de leptina circulantes conlleva una disminución de la tasa metabólica.","La activación del núcleo paraventricular del hipotálamo estimula la liberación de hormonas por la adenohipófisis.","La activación de las neuronas NPY/AgRP del núcleo arqueado inhibe la conducta alimentaria.","El área hipotalámica lateral se encuentra inhibido cuando los niveles de leptina circulantes disminuyen."],"answer":1,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada N-064 / G0988 del banco canónico | archivos: NEURO_275_ORGANIZADO_POR_TEMA_HACK24(1).pdf; NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf | referencias indicadas: NEURO_275_ORGANIZADO_POR_TEMA_HACK24(1).pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-65","number":"65","statement":"Indica la afirmación FALSA sobre la fisiología hipotalámica:","options":["Los niveles de angiotensina II aumentan al disminuir el flujo sanguíneo renal, induciendo la producción hipotalámica de vasopresina (ADH).","El mecanismo de sed volumétrica conlleva una respuesta de vasodilatación al activar el sistema nervioso parasimpático.","La existencia de órganos circunventriculares, como el órgano vascular de la lámina terminal, permite responder ante modificaciones en la osmolaridad de la sangre.","Los pirógenos activan el área preóptica hipotalámica e inician respuestas de disipación de calor."],"answer":1,"explanation":"[Notas/explicación original separada] La alternativa FALSA es la B) El mecanismo de sed volumétrica conlleva una respuesta de vasodilatación al activar el sistema nervioso parasimpático. A continuación, te detallo por qué esta afirmación es incorrecta y las demás son verdaderas según los documentos: B) FALSA: El mecanismo de sed volumétrica se activa ante un descenso de la presión sanguínea (hipovolemia) y genera exactamente la respuesta contraria a la que indica la opción. Las señales integradas en el hipotálamo inducen una vasoconstricción de las arteriolas, la cual está mediada por el sistema nervioso simpático, con el objetivo de contrarrestar la bajada de presión. A) VERDADERA: En el mecanismo de sed volumétrica, la reducción del flujo sanguíneo renal provoca una elevación de los niveles de angiotensina II. Esta molécula actúa sobre el órgano subfornical, lo que termina activando a las neuronas magnocelulares del hipotálamo para que liberen vasopresina (ADH). C) VERDADERA: El órgano vascular de la lámina terminal es un órgano circunventricular (con la barrera hematoencefálica modificada) que actúa como osmorreceptor. Es el encargado de detectar los aumentos en la osmolaridad de la sangre (sed osmométrica) y activar las respuestas para la liberación de vasopresina y la búsqueda de agua. D) VERDADERA: Aunque el término específico \"pirógenos\" no se detalla en el texto, los apuntes confirman explícitamente que el área preóptica medial del hipotálamo es el centro de control que se activa ante los aumentos de temperatura para iniciar las respuestas de disipación de calor (como el sudor o la búsqueda de frío).","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada N-065 / G0989 del banco canónico | archivos: NEURO_275_ORGANIZADO_POR_TEMA_HACK24(1).pdf; NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf | referencias indicadas: NEURO_275_ORGANIZADO_POR_TEMA_HACK24(1).pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-66","number":"66","statement":"Indica cuál de los siguientes núcleos NO pertenece al hipotálamo:","options":["Núcleo dorsomedial.","Núcleo infundibular (arcuato).","Núcleo paraventricular.","Núcleo infraoptico."],"answer":3,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada N-066 / G0990 del banco canónico | archivos: NEURO_275_ORGANIZADO_POR_TEMA_HACK24(1).pdf; NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf | referencias indicadas: NEURO_275_ORGANIZADO_POR_TEMA_HACK24(1).pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-67","number":"67","statement":"Sobre la anatomía del diencéfalo es CIERTO que:","options":["La adherencia (o adhesión) intertalámica se encuentra lateral con respecto al tercer ventrículo.","La lámina terminal se encuentra en el límite anterior del hipotálamo.","Los cuerpos mamilares se encuentran dorsales con respecto al resto de núcleos hipotalámicos.","El epitálamo se encuentra en el límite posterior del hipotálamo."],"answer":1,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada N-067 / G0991 del banco canónico | archivos: NEURO_275_ORGANIZADO_POR_TEMA_HACK24(1).pdf; NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf | referencias indicadas: NEURO_275_ORGANIZADO_POR_TEMA_HACK24(1).pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-68","number":"68","statement":"Con relación a los núcleos talámicos es FALSO que:","options":["La masa anterior talámica actúa en la fijación de la memoria por su conexión con el sistema límbico.","Los núcleos intralaminares se encuentra en la lámina medular interna.","La sensibilidad táctil corporal y craneofacial releva en núcleos del grupo ventral del tálamo.","El núcleo reticular del tálamo envía axones a diferentes regiones de la corteza cerebral."],"answer":3,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada N-068 / G0992 del banco canónico | archivos: NEURO_275_ORGANIZADO_POR_TEMA_HACK24(1).pdf; NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf | referencias indicadas: NEURO_275_ORGANIZADO_POR_TEMA_HACK24(1).pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-69","number":"69","statement":"De las siguientes estructuras pertenecientes a la vía auditiva ascendente, ¿cuál se encuentra localizada en la posición más superior (rostral / diencefálica)?:","options":["Núcleo geniculado medial del tálamo 11","Colículo inferior del mesencéfalo 11","Lemnisco lateral 11","Complejo olivar superior de la protuberancia 11"],"answer":0,"explanation":"No incluida en el material.","hack":"Hack del Eje Craniocaudal en las Vías Sensoriales (Aviso de Examen de Aitana): Esta pregunta exige ordenar la vía auditiva de inferior (caudal) a superior (rostral) 11: 1. Oliva Superior / Núcleos Cocleares: Protuberancia/Puente (más inferior) 11. 2. Lemnisco Lateral: Tracto que asciende por la protuberancia hacia el mesencéfalo 4 11. 3. Colículo Inferior: Tecto del mesencéfalo 11. 4. Núcleo Geniculado Medial: Tálamo (Diencéfalo) 11. Como el diencéfalo se ubica estructuralmente por encima de todo el tronco del encéfalo, el Núcleo Geniculado Medial es indiscutiblemente la estructura más superior de la lista 11.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-001 / G0030 del banco canónico | integración: Tema 1.5.1 + Tema 1.6 + Tema 1.11.2 | archivos: Todos os exames de Neuro EXTRACAO(1).pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #202 y Notas) / Examem 2025 outro modelo juneka.pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-70","number":"70","statement":"En la organización de las vías somatosensitivas que cruzan el tronco del encéfalo, ¿qué diferencia estructural existe entre el lemnisco medial y el lemnisco espinal?:","options":["El lemnisco medial se origina por la decusación de las fibras arciformes internas en el bulbo (vía grácil y cuneiforme), mientras que el lemnisco espinal corresponde a las fibras espinotalámicas que ya decusaron en la médula espinal.","El lemnisco espinal no llega al tálamo.","El lemnisco medial transporta dolor y temperatura corporal.","El lemnisco espinal se origina en el núcleo motor del trigémino."],"answer":0,"explanation":"[Explicación 1 (Todos os exames de Neuro EXTRACAO(1).pdf Q39)] Hack de Decusación Medular vs. Bulbar: Lemnisco Espinal (Tracto Espinotalámico): Decusa en la médula espinal (comisura blanca anterior) y asciende ipsilateralmente por todo el tronco del encéfalo hacia el tálamo VPL (dolor y temperatura) 53. Lemnisco Medial: Decusa en el bulbo raquídeo (fibras arciformes internas) y asciende por el centro del tegmento hacia el tálamo VPL (tacto epicrítico y propiocepción consciente) 43 53. || [Explicación 2 (Neuro_Adicional_Parte3.pdf Q39)] Hack de Decusación Medular vs. Bulbar: Lemnisco Espinal (Tracto Espinotalámico): Decusa en la médula espinal (comisura blanca anterior) y asciende ipsilateralmente por todo el tronco del encéfalo hacia el tálamo VPL (dolor y temperatura). Lemnisco Medial: Decusa en el bulbo raquídeo (fibras arciformes internas) y asciende por el centro del tegmento hacia el tálamo VPL (tacto epicrítico y propiocepción consciente).","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-002 / G0055 del banco canónico | integración: Tema 1.4 + Tema 1.5.1 + Tema 1.6 + Tema 1.10 | archivos: Todos os exames de Neuro EXTRACAO(1).pdf; Todas as questoes ate tema 1.10.1.pdf; Neuro_Adicional_Parte3.pdf | referencias indicadas: 09-22 Clase_ Ubicación de tractos del tronco del encéfalo / NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #167)","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-71","number":"71","statement":"El lemnisco trigeminal es la vía ascendente que conduce la sensibilidad somática de la cara hacia el tálamo. ¿Dónde se originan las neuronas de segunda orden cuyos axones cruzan la línea media para formar este lemnisco?:","options":["En los núcleos principal (pontino) y espinal (bulbomedular) del nervio trigémino.","En el ganglio de Gasser exclusivamente.","En el núcleo mesencefálico del trigémino.","En el núcleo del tracto solitario."],"answer":0,"explanation":"[Explicación 1 (Todos os exames de Neuro EXTRACAO(1).pdf Q51)] Hack de las Neuronas del Lemnisco Trigeminal: Primera neurona: Somas en el ganglio trigeminal (de Gasser). Segunda neurona: Somas en el Núcleo Principal (tacto fino) y Núcleo Espinal (termoalgesia) del V par en el tronco. Sus axones cruzan al lado opuesto y ascienden como lemnisco trigeminal hacia el núcleo VPM del tálamo.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-003 / G0067 del banco canónico | integración: Tema 1.5.1 + Tema 1.5.2 + Tema 1.6 + Tema 1.10 | archivos: Todos os exames de Neuro EXTRACAO(1).pdf; Todas as questoes ate tema 1.10.1.pdf; Neuro_Adicional_Parte3.pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #204) / 09-26 Clase_ Nervio Trigémino / 10-20 Clase magistral_ Sistema somatosensorial","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-72","number":"72","statement":"Indique la afirmación CORRECTA sobre la neurobiología del diencéfalo:","options":["Núcleo reticular del tálamo — Inhibidor GABAérgico de las neuronas de relevo talámico, especialmente evidente durante el sueño.","Núcleo paraventricular del hipotálamo — Participa en la regulación de la sed pero no está implicado en el balance energético corporal.","Habénula — Estructura hipotalámica relacionada con el sentido del olfato y del gusto.","Órgano subfornical — Órgano circunventricular cuya función principal es regular la temperatura corporal."],"answer":0,"explanation":"No incluida en el material.","hack":"El Núcleo Reticular del Tálamo (NRT) es la única lámina talámica inhibidora que rodea al tálamo. Modula la puerta de entrada de estímulos sensoriales a la corteza durante los ciclos de sueño-vigilia mediante la liberación de GABA.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-004 / G0078 del banco canónico | integración: Tema 1.6 + Tema 1.8 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Adicional_Parte2.pdf | referencias indicadas: wuolah-free-PREGUNTAS-TEST-NEURO-DIENCEFALO-.pdf / TEMA 5 – DIENCÉFALO .pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-73","number":"73","statement":"Los núcleos anterior y dorsomedial (DM) del tálamo se caracterizan funcionalmente por estar integrados en:","options":["El circuito motor extrapiramidal de los ganglios basales.","Las redes del sistema límbico (procesamiento de emociones, memoria y conducta).","El relevo somatosensorial del tono muscular.","La vía visual primaria geniculocalcarina."],"answer":1,"explanation":"No incluida en el material.","hack":"Núcleo Anterior: Recibe del cuerpo mamilar (vía mamilotalámica) -> proyecta al Cíngulo (Circuito de Papez). Núcleo Dorsomedial: Recibe de la amígdala e hipotálamo -> proyecta a la corteza prefrontal. Ambos son los dos grandes pivotes talámicos del Sistema Límbico.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-005 / G0079 del banco canónico | integración: Tema 1.6 + Tema 1.8 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Adicional_Parte2.pdf | referencias indicadas: wuolah-free-tema-5-preguntas.pdf (Pregunta #3) / 09-30 Clase_ Diencéfalo","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-74","number":"74","statement":"El núcleo pulvinar constituye la gran masa prominente del extremo posterior del tálamo. ¿A qué grupo funcional pertenece y con qué cortezas cerebrales establece sus principales conexiones asociativas?:","options":["Pertenece al grupo asociativo multimodal; recibe aferencias del colículo superior y áreas visuales/auditivas, proyectando hacia las cortezas de asociación parietal, occipital y temporal.","Es un núcleo de relevo motor que recibe del globo pálido interno y proyecta a la corteza M1.","Es la única lámina del tálamo encargada de secretar melatonina.","Se ubica en el piso del cuarto ventrículo en el bulbo raquídeo."],"answer":0,"explanation":"No incluida en el material.","hack":"El Pulvinar es el núcleo más volumétrico del extremo posterior del tálamo. No es un núcleo de relevo sensorial primario, sino un núcleo asociativo multimodal clave en la integración de estímulos visuales, acústicos y somatosensoriales hacia la corteza parieto-occipito- temporal.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-006 / G0082 del banco canónico | integración: Tema 1.5.1 + Tema 1.6 + Tema 1.11.2 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Adicional_Parte2.pdf | referencias indicadas: TEMA 5 – DIENCÉFALO .pdf / ex. 2 (respuestas).pdf (Pregunta #21) / 10-01 Clase_ Neuroanatomía - Tálamo e Hipotálamo","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-75","number":"75","statement":"Los núcleos intralaminares del tálamo (entre los que destaca el núcleo centromediano) se encuentran inmersos en el espesor de la lámina medular interna. ¿Cuál es su papel neurofisiológico en la modulación de la actividad cerebral?:","options":["Reciben aferencias de la formación reticular, cerebelo y ganglios basales, y envían proyecciones difusas no específicas a la corteza cerebral para modular el nivel de alerta (arousal) y el dolor crónico.","Relevan de forma específica la información gustativa hacia el área 43 de Brodmann.","Son núcleos motores dedicados exclusivamente a la miosis pupilar.","Inervan las glándulas salivales submandibular y sublingual."],"answer":0,"explanation":"No incluida en el material.","hack":"Los Núcleos Intralaminares (Centromediano) no proyectan a un área cortical única, sino que envían proyecciones difusas a todo el manto neocortical, participando en el mantenimiento de la consciencia, el estado de vigilia y la percepción afectivo-difusa del dolor crónico.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-007 / G0083 del banco canónico | integración: Tema 1.5.1 + Tema 1.6 + Tema 1.7 + Tema 1.9.2 + Tema 1.9.3 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Adicional_Parte2.pdf | referencias indicadas: 10-30 Clase magistral_ Neuroanatomía meníngea / NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #48) / TEMA 5 – DIENCÉFALO .pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-76","number":"76","statement":"El complejo amigdalino del lóbulo temporal comunica con el diencéfalo e hipotálamo a través de dos tractos eferentes. ¿Qué diferencia la Vía Amigdalófuga Ventral de la Estría Terminal?:","options":["La vía amigdalófuga ventral es una ruta directa y corta que discurre ventralmente por la sustancia perforada anterior hacia el hipotálamo, mientras que la estría terminal realiza un largo trayecto curvo sobre el núcleo caudado.","La vía amigdalófuga ventral es una vena del plexo de Batson.","La estría terminal es una estructura motora que inerva el músculo estapedio.","Ambas vías nacen en el núcleo rojo del mesencéfalo."],"answer":0,"explanation":"No incluida en el material.","hack":"Eferencias de la Amígdala: Vía Amigdalófuga Ventral: Ruta corta y directa hacia el hipotálamo y núcleos septales. Estría Terminal: Ruta larga y arqueada que bordea el cuerpo y cola del núcleo caudado en la pared del ventrículo lateral.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-008 / G0084 del banco canónico | integración: Tema 1.6 + Tema 1.9.2 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Adicional_Parte2.pdf | referencias indicadas: Exame Neuro 2022.pdf (Pregunta #38) / Nervioso T21-T22-20250930_163918-Grabación de la reunión 1 (1).mp / TEMA 5 – DIENCÉFALO .pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-77","number":"77","statement":"Un paciente sufre un traumatismo severo en la base del cráneo con sección del tallo infundibular e infarto de los núcleos supraóptico y paraventricular. Clínicamente presenta poliuria masiva (12 L/día de orina muy diluida) y polidipsia secundaria. ¿Qué patología neuroendocrina padece y qué deficiencia hormonal la origina?:","options":["Diabetes Insípida Central (Neurogénica), provocada por la falta de síntesis y liberación de Vasopresina / Hormona Antidiurética (ADH).","Diabetes Mellitus Tipo 1 por déficit de insulina.","Síndrome de Conn por exceso de aldosterona.","Hipotiroidismo primario por falta de TSH."],"answer":0,"explanation":"No incluida en el material.","hack":"Lesión de los núcleos Supraóptico / Paraventricular o del tallo infundibular -> Pérdida de ADH (Vasopresina) -> El túbulo colector renal no reabsorbe agua -> Diabetes Insípida Central (orina hipotónica masiva y sed insaciable).","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-009 / G0086 del banco canónico | integración: Tema 1.6 + Tema 1.12 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Adicional_Parte2.pdf | referencias indicadas: 09-30 Clase_ Diencéfalo / TEMA 5 – DIENCÉFALO .pdf / NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-78","number":"78","statement":"En las clases magistrales se explica la modulación de la excitabilidad talámica por parte de la formación reticular troncoencefálica (complejo ponto-mesencefálico tegmental). ¿Cuál es el mecanismo neurológico mediante el cual este complejo promueve el estado de alerta cortical?:","options":["Inactiva transitoriamente al Núcleo Reticular del Tálamo (NRT), desinhibiendo a los núcleos de relevo talámico para que transmitan información hacia la corteza cerebral (vigilia).","Estimula directamente la secreción de GABA en la corteza motora primaria.","Destruye los plexos coroideos del tercer ventrículo.","Inerva los músculos estriados de la pierna."],"answer":0,"explanation":"No incluida en el material.","hack":"El Complejo Ponto- Mesencefálico Tegmental (colinérgico) envía axones al Núcleo Reticular del Tálamo (NRT). Al bloquear la inhibición GABAérgica del NRT sobre los núcleos de relevo, el tálamo \"abre la puerta\" e inunda la corteza de señales, generando el patrón electroencefálico de vigilia y desincronización.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-010 / G0087 del banco canónico | integración: Tema 1.5.1 + Tema 1.6 + Tema 1.7 + Tema 1.8 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Adicional_Parte2.pdf | referencias indicadas: 10-01C~1.MP3 / 10-30 Clase magistral_ Neuroanatomía meníngea / TEMA 5 – DIENCÉFALO .pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-79","number":"79","statement":"En la cara lateral del tálamo, ¿qué estructuras se disponen adosadas a su superficie separándolo del núcleo lenticular y del núcleo caudado respectivamente?:","options":["La lámina medular externa y el brazo posterior de la cápsula interna (lateralmente) | La estría terminal y la vena talamoestriada (en el surco talamoestriado que lo separa del caudado).","La arteria basilar y la hoz del cerebro.","El quiasma óptico y los cuerpos mamilares.","La fosa romboidea y el pirámide bulbar."],"answer":0,"explanation":"No incluida en el material.","hack":"Anatomía de Relaciones del Tálamo: Lateralmente: Separado del núcleo lenticular por la Lámina Medular Externa y la Cápsula Interna (brazo posterior). Superolateromedial (Surco Talamoestriado): Discurren la Estría Terminal y la Vena Talamoestriada, marcando el límite con el núcleo caudado.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-011 / G0088 del banco canónico | integración: Tema 1.6 + Tema 1.7 + Tema 1.9.2 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Adicional_Parte2.pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #44) / Recopilación preguntas neuro (1).pdf / 09-30 Clase de Neuroanatomía_ Tálamo","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-80","number":"80","statement":"El núcleo Ventral Lateral (VL) del tálamo es una estación clave en la coordinación motora. ¿De qué núcleo cerebeloso profundo recibe la mayor cantidad de aferencias excitadoras a través del pedúnculo cerebeloso superior para proyectar a la corteza motora primaria (área 4)?:","options":["Núcleo Dentado","Núcleo Fastigio","Núcleo Emboliforme","Núcleo Globoso"],"answer":0,"explanation":"No incluida en el material.","hack":"La vía dentato-tálamo-cortical (pedúnculo cerebeloso superior -> decusación de Werneking -> Núcleo VL del tálamo -> corteza motora primaria área 4) es la principal vía eferente del neocerebelo (cerebrocerebelo) para la planificación y ajuste fino del movimiento voluntario.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-012 / G0089 del banco canónico | integración: Tema 1.6 + Tema 1.9.1 + Tema 1.9.3 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Adicional_Parte2.pdf | referencias indicadas: TEMA 5 – DIENCÉFALO .pdf / 12-10 Clase_ Microanatomía y Fisiología del Cerebelo.mp / NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-81","number":"81","statement":"En la conducción de la sensibilidad nociceptiva, el tracto paleoespinotalámico (vía lenta y difusa del dolor) finaliza en núcleos talámicos no específicos. ¿En qué grupo nuclear del tálamo hacen sinapsis sus axones para proyectar de forma difusa a la corteza e ínsula, modulando la respuesta afectiva y motivacional del dolor?:","options":["Núcleos Intralaminares (núcleo centromediano y parafascicular)","Núcleo Geniculado Lateral","Núcleo Ventral PosteroLateral (VPL)","Núcleo Anterior del Tálamo"],"answer":0,"explanation":"No incluida en el material.","hack":"Vía Neoespinotalámica (Dolor agudo/localizado): Termina en el VPL -> proyecta a S1 (localización espacial exacta del dolor). Vía Paleoespinotalámica (Dolor sordo/crónico/difuso): Termina en los Núcleos Intralaminares y Centromediano -> proyectan de forma difusa a la corteza, ínsula y cíngulo (procesamiento emocional y afectivo del dolor).","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-013 / G0090 del banco canónico | integración: Tema 1.6 + Tema 1.7 + Tema 1.10 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Adicional_Parte2.pdf | referencias indicadas: 12-15 Lección_ Neurobiología del Dolor-transcript.txt / TEMA 5 – DIENCÉFALO .pdf / NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-82","number":"82","statement":"Un paciente con antecedente de alcoholismo crónico severo presenta amnesia anterógrada masiva, confabulación (inventa recuerdos para rellenar lagunas amnésicas) y ataxia. La resonancia magnética muestra atrofia y necrosis hemorrágica de los cuerpos mamilares del hipotálamo y del núcleo dorsomedial del tálamo por déficit de tiamina (Vitamina B1). ¿Qué diagnóstico neuropsiquiátrico presenta?:","options":["Síndrome de Korsakoff (o Psicosis de Wernicke-Korsakoff)","Enfermedad de Parkinson","Esclerosis Lateral Amiotrófica","Síndrome de Klüver-Bucy"],"answer":0,"explanation":"No incluida en el material.","hack":"El déficit de Tiamina (Vitamina B1) en alcohólicos provoca degeneración de las estructuras diencefálicas del circuito de la memoria: cuerpos mamilares y núcleo dorsomedial del tálamo. La tríada inicial de Encefalopatía de Wernicke (oftalmoplejía, ataxia, confusión) evoluciona al Síndrome de Korsakoff (amnesia de fijación con confabulación).","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-014 / G0091 del banco canónico | integración: Tema 1.6 + Tema 1.8 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Adicional_Parte2.pdf | referencias indicadas: 10-09 Clase_ Funciones Cerebrales y Memoria.mp / TEMA 5 – DIENCÉFALO .pdf / NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-83","number":"83","statement":"Las células ganglionares fotosensibles de la retina (ipRGC) expresan el fotopigmento melanopsina y no participan en la formación de imágenes conscientes. ¿A qué núcleo hipotalámico proyectan de forma directa para sincronizar el marcapasos circadiano interno con el ciclo de luz/oscuridad ambiental?:","options":["Núcleo Supraquiasmático (NSQ)","Núcleo Ventromedial","Cuerpos Mamilares","Núcleo Arcuato"],"answer":0,"explanation":"No incluida en el material.","hack":"Las ipRGCs (intrinsically photosensitive Retinal Ganglion Cells) usan melanopsina para captar la luz ambiental e inervar directamente el Núcleo Supraquiasmático (NSQ) a través del tracto retinohipotalámico, regulando el reloj circadiano biológico sin pasar por el tálamo visual (CGL).","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-015 / G0092 del banco canónico | integración: Tema 1.6 + Tema 1.11.1 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Adicional_Parte2.pdf | referencias indicadas: 10-24 Clase magistral_ Organización funcional de la retina, vías ON_OFF, ganglionares ipRGC.mp / TEMA 5 – DIENCÉFALO .pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-84","number":"84","statement":"La habénula (núcleo habenular) se ubica en el epitálamo y actúa como un centro de integración entre el sistema límbico y el tronco. ¿A través de qué importante fascículo eferente envía sus axones hacia el núcleo interpeduncular del mesencéfalo para modular las vías dopaminérgicas y serotoninérgicas?:","options":["Fascículo retroflexo de Meynert (tracto habenulo-interpeduncular)","Fascículo mamilotalámico de Vicq d'Azyr","Fórnix","Comisura blanca anterior"],"answer":0,"explanation":"No incluida en el material.","hack":"Eferencia clave de la Habénula: Fascículo Retroflexo de Meynert (vía habenulo-interpeduncular). Conecta el epitálamo con el núcleo interpeduncular del mesencéfalo, regulando respuestas de aversión, decepción y modulación de dopamina/serotonina.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-016 / G0093 del banco canónico | integración: Tema 1.5.1 + Tema 1.6 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Adicional_Parte2.pdf | referencias indicadas: 09-30 Clase_ Diencéfalo - Tálamo, Hipotálamo y Epitálamo.mp / TEMA 5 – DIENCÉFALO .pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-85","number":"85","statement":"Un paciente que sufrió un infarto lacunar en el territorio de las arterias talamoperforadas/talamoestriadas con afectación del núcleo Ventral PosteroLateral (VPL) del tálamo, desarrolla semanas después un cuadro de dolor intolerable, ardiente, paroxístico e hiperalgesia severa en toda la mitad contralateral de su cuerpo, desencadenado por roces mínimos (alodinia). ¿Cómo se conoce este síndrome clínico?:","options":["Síndrome de Déjerine-Roussy (Síndrome de Dolor Talámico)","Síndrome de Wallenberg","Síndrome de Claude Bernard-Horner","Síndrome de Brown-Séquard"],"answer":0,"explanation":"No incluida en el material.","hack":"El Síndrome de Déjerine-Roussy (Dolor Central / Talámico) es causado por lesiones destructivas o isquémicas de los núcleos sensitivos posterolaterales del tálamo (VPL/VPM). Causa una pérdida inicial de sensibilidad seguida de la aparición de dolor central intrincado, alodinia e hiperalgesia contralateral.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-017 / G0094 del banco canónico | integración: Tema 1.6 + Tema 1.10 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Adicional_Parte2.pdf | referencias indicadas: 12-15 Lección_ Neurobiología del Dolor.mp / TEMA 5 – DIENCÉFALO .pdf / NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-86","number":"86","statement":"El tercer ventrículo presenta prolongaciones o recesos del espacio ventricular que se introducen en las estructuras diencefálicas adyacentes. ¿Qué receso ventricular se proyecta en la pared anterior por encima del quiasma óptico y por debajo de la lámina terminal?:","options":["Receso supraóptico (óptico)","Receso pineal","Receso infundibular","Receso suprapineal"],"answer":0,"explanation":"No incluida en el material.","hack":"Recesos del Tercer Ventrículo (Memoria de Imagen Ventricular): Pared Anterior: Receso Supraóptico (sobre el quiasma) y Receso Infundibular (en el tallo hipofisario). Pared Posterior: Receso Pineal (en el tallo epifisario) y Receso Suprapineal (sobre la glándula pineal).","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-018 / G0095 del banco canónico | integración: Tema 1.6 + Tema 1.11.1 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Adicional_Parte2.pdf | referencias indicadas: 09-10 Clase_ LCR, circulación cerebral y polígono de Willis.mp / TEMA 5 – DIENCÉFALO .pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-87","number":"87","statement":"De las siguientes estructuras pertenecientes a la vía auditiva ascendente, ¿cuál se encuentra localizada en la posición más superior (rostral / diencefálica)?:","options":["Núcleo geniculado medial del tálamo","Colículo inferior del mesencéfalo","Lemnisco lateral","Complejo olivar superior de la protuberancia"],"answer":0,"explanation":"[Explicación 1 (Todas as questoes ate tema 1.10.1.pdf Q14)] Hack del Eje Craniocaudal en las Vías Sensoriales (Aviso de Examen de Aitana): Esta pregunta exige ordenar la vía auditiva de inferior (caudal) a superior (rostral): 1. Oliva Superior / Núcleos Cocleares: Protuberancia/Puente (más inferior). 2. Lemnisco Lateral: Tracto que asciende por la protuberancia hacia el mesencéfalo. 3. Colículo Inferior: Tecto del mesencéfalo. 4. Núcleo Geniculado Medial: Tálamo (Diencéfalo). Como el diencéfalo se ubica estructuralmente por encima de todo el tronco del encéfalo, el Núcleo Geniculado Medial es indiscutiblemente la estructura más superior de la lista. || [Explicación 2 (Neuro_Adicional_Parte3.pdf Q14)] Hack del Eje Craniocaudal en las Vías Sensoriales (Aviso de Examen de Aitana): Esta pregunta exige ordenar la vía auditiva de inferior (caudal) a superior (rostral): Oliva Superior / Núcleos Cocleares: Protuberancia/Puente (más inferior). Lemnisco Lateral: Tracto que asciende por la protuberancia hacia el mesencéfalo. Colículo Inferior: Tecto del mesencéfalo. Núcleo Geniculado Medial: Tálamo (Diencéfalo). Como el diencéfalo se ubica estructuralmente por encima de todo el tronco del encéfalo, el Núcleo Geniculado Medial es indiscutiblemente la estructura más superior de la lista.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-019 / G0102 del banco canónico | integración: Tema 1.5.1 + Tema 1.6 + Tema 1.11.2 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Adicional_Parte3.pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #202 y Notas) / Examem 2025 outro modelo juneka.pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-88","number":"88","statement":"En el flujo de información por el lóbulo temporal y el diencéfalo para la génesis y consolidación de la memoria declarativa (Circuito de Papez), señale el orden neuroanatómico correcto de la vía:","options":["Áreas de asociación cortical → Hipocampo → Hipotálamo (Cuerpos Mamilares) → Tálamo (Núcleo Anterior) → Áreas de asociación cortical (Giro del Cíngulo).","Áreas de asociación cortical → Tálamo → Hipocampo → Hipotálamo → Áreas de asociación.","Hipocampo → Áreas de asociación → Tálamo → Hipotálamo → Cíngulo.","Cuerpos Mamilares → Hipocampo → Cíngulo → Tálamo → Áreas motoras."],"answer":0,"explanation":"No incluida en el material.","hack":"Hack de la Secuencia del Circuito de Papez (Pregunta Fija de Examen): Cortezas de asociación -> Corteza Entorrinal / Hipocampo -> Fórnix -> Cuerpos Mamilares (Hipotálamo) -> Tracto Mamilotalámico -> Núcleo Anterior del Tálamo -> Giro del Cíngulo -> Cortezas de asociación.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-020 / G0122 del banco canónico | integración: Tema 1.6 + Tema 1.7 + Tema 1.8 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Adicional_Parte3.pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #54, #152) / 11-06 Tutoría_ Memoria (Papez) / Exame Neuro 2022.pdf (Pregunta #54)","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-89","number":"89","statement":"En la neuroquímica del ciclo sueño-vigilia, ¿cuál es el neurotransmisor promotor del sueño NREM liberado por las neuronas del núcleo preóptico ventrolateral (VLPO) del hipotálamo para inhibir los centros de la vigilia (SARA, locus coeruleus, núcleos del rafe y tuberomamilar)?:","options":["GABA (Ácido Gamma-Aminobutírico) y galanina.","Glutamato y aspartato.","Histamina y dopamina.","Norepinefrina y serotonina."],"answer":0,"explanation":"No incluida en el material.","hack":"Hack del Núcleo VLPO (Interruptor del Sueño): El Núcleo Preóptico Ventrolateral (VLPO) del hipotálamo es el \"interruptor principal del sueño\". Sus neuronas liberan GABA y galanina (neurotransmisores inhibidores) sobre los núcleos monaminérgicos y colinérgicos del arousal (Locus Coeruleus, Rafe, Tuberomamilar), apagando la vigilia e induciendo el sueño NO REM.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-021 / G0136 del banco canónico | integración: Tema 1.5.1 + Tema 1.6 + Tema 1.8 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Adicional_Parte3.pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #182) / 10-13 Clase_ Funciones Cerebrales, Ritmos Circadianos y Sueño / Design sem nome (2).pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-90","number":"90","statement":"El síndrome de Korsakoff es una alteración neuropsiquiátrica inducida por déficit de tiamina (Vitamina B1) en pacientes con alcoholismo crónico. ¿Qué núcleos y estructuras diencefálicas e hipocámpicas del circuito de Papez sufren degeneración, y qué tipo de amnesia y síntoma compensatorio es el más característico?:","options":["Degeneración de los cuerpos mamilares del hipotálamo, núcleo dorsomedial y anterior del tálamo y formación hipocampal; produce amnesia anterógrada severa (incapacidad para formar nuevas memorias declarativas) con presencia de confabulación (inventar recuerdos falsos sin intención de mentir).","Destrucción exclusiva del cerebelo; produce amnesia procedimental pura sin confabulación.","Necrosis del núcleo lenticular y globo pálido; causa amnesia retrógrada aislada sin alteración anterógrada.","Degeneración de la sustancia negra mesencefálica; causa amnesia motora y de los ritmos circadianos."],"answer":0,"explanation":"[Explicación 1 (Todas as questoes ate tema 1.10.1.pdf Q34)] Hack de la Amnesia de Korsakoff: En el Síndrome de Korsakoff, la falta de Vitamina B1 destruye las estructuras clave del circuito de Papez (cuerpos mamilares, núcleo dorsomedial/anterior del tálamo y la formación hipocampal). Esto bloquea la transferencia de memorias inmediatas hacia la corteza, produciendo una amnesia anterógrada predominante. El paciente recurre involuntariamente a la confabulación para rellenar las lagunas amnésicas.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-022 / G0146 del banco canónico | integración: Tema 1.6 + Tema 1.8 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Adicional_Parte3.pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #180, #156) / 10-10 Clase_ Memoria, Emociones / Tema 1.8 - Funciones cerebrales superiores","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-91","number":"91","statement":"Respecto a las funciones del hemisferio derecho en el procesamiento del lenguaje y su interacción con las emociones y el sistema límbico, señale la afirmación INCORRECTA:","options":["El área homóloga a Wernicke en el hemisferio derecho (área 22 derecha) se encarga de comprender los matices prosódicos (entonación y tono afectivo) del lenguaje del interlocutor.","Las áreas homólogas a Broca en el hemisferio derecho (áreas 44 y 45 derechas) permiten modificar la entonación emocional con la que nos expresamos.","La pérdida del cuerpo amigdalino en el lóbulo temporal produce un incremento en la percepción del miedo y un aumento de la agresividad defensiva.","La lesión de las áreas lingüísticas del hemisferio derecho no produce afasia motora o sensitiva pura, sino aprosodia (pérdida de la capacidad para expresar o comprender la emoción en la voz)."],"answer":2,"explanation":"[Explicación 1 (Todas as questoes ate tema 1.10.1.pdf Q35)] Hack de Inversión de la Amígdala e Percepción de Miedo: La pérdida de la amígdala cerebral (como en el Síndrome de Klüver-Bucy o en la enfermedad de Urbach-Wiethe) provoca una DISMINUCIÓN o ABOLICIÓN de la capacidad de percibir o experimentar miedo, así como mansedumbre. Prosodia del Hemisferio Derecho: Las áreas 22, 44 y 45 del hemisferio derecho procesan el componente emocional y prosódico del habla (la entonación y afecto), mientras que el hemisferio izquierdo procesa la sintaxis y gramática.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-023 / G0147 del banco canónico | integración: Tema 1.6 + Tema 1.8 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Adicional_Parte3.pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #177) / 10-10 Clase_ Lenguaje, Cerebro y Afasias / Recopilación preguntas neuro (1).pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-92","number":"92","statement":"Con relación a los mecanismos neuroquímicos y la regulación del ciclo sueño-vigilia, indique la afirmación VERDADERA:","options":["La información lumínica captada por las células ganglionares fotosensibles (ipRGC con melanopsina) viaja por la vía retinohipotalámica al núcleo supraquiasmático (NSQ) del hipotálamo, estimulando la liberación nocturna de melatonina por la glándula pineal a través de la vía simpática hipotálamo-pineal.","Durante el sueño REM se produce una elevada actividad del sistema difuso noradrenérgico del locus coeruleus y una inhibición total de los sistemas colinérgicos.","Las ondas delta en un adulto despierto con los ojos abiertos indican un estado de meditación relajada fisiológica.","El núcleo reticular del tálamo es activado por la acetilcolina durante la vigilia activa para bloquear todos los impulsos sensoriales hacia la corteza."],"answer":0,"explanation":"[Explicación 1 (Todas as questoes ate tema 1.10.1.pdf Q37)] Hack de la Vía Hipotálamo-Pineal y Melatonina: Las células ipRGC (con melanopsina) envían la señal de luz al NSQ. La oscuridad activa la vía simpática (núcleo paraventricular -> columna intermediolateral D1-D2 -> ganglio cervical superior) para que la glándula pineal secrete melatonina. Sueño REM vs Vigilia: En la fase REM la actividad colinérgica está muy ELEVADA (ondas beta) y el locus coeruleus (noradrenérgico) y el rafe (serotoninérgico) están silenciados.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-024 / G0149 del banco canónico | integración: Tema 1.6 + Tema 1.8 + Tema 1.11.1 + Tema 1.12 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Adicional_Parte4.pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #156, #180) / 10-13 Clase_ Funciones Cerebrales, Ritmos Circadianos y Sueño / ex. 2021 (respuestas).pdf (Pregunta #47)","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-93","number":"93","statement":"En la neurobiología del aprendizaje por refuerzo y adicción, el circuito de recompensa conecta estructuras mesencefálicas, límbicas y corticales. ¿Cuál es el trayecto neuroanatómico de este circuito y la función de sus componentes principales?:","options":["Las neuronas dopaminérgicas del Área Tegmental Ventral (VTA) proyectan al Núcleo Accumbens (estriado ventral) e inervan la Corteza Orbitofrontal y Prefrontal Medial; la corteza orbitofrontal asigna la experiencia hedonista subjetiva y el valor al estímulo.","Las neuronas noradrenérgicas del Locus Coeruleus proyectan directamente a la corteza visual V1 para producir alucinaciones.","Las neuronas serotoninérgicas del Rafe inervan exclusivamente al cerebelo para producir placer motor.","El circuito de recompensa discurre únicamente por el nervio vago periférico."],"answer":0,"explanation":"[Explicación 1 (Todas as questoes ate tema 1.10.1.pdf Q39)] Hack del Circuito Mesocorticolímbico de Recompensa: 1. Origen: Neuronas dopaminérgicas del Área Tegmental Ventral (VTA). 2. Destino Vía Mesolímbica: Núcleo Accumbens (estriado ventral - motivación y refuerzo). 3. Destino Vía Mesocortical: Corteza Orbitofrontal y prefrontal (procesamiento del placer hedonista e incentivo). || [Explicación 2 (Neuro_Adicional_Parte4.pdf Q39)] Hack del Circuito Mesocorticolímbico de Recompensa: Origen: Neuronas dopaminérgicas del Área Tegmental Ventral (VTA). Destino Vía Mesolímbica: Núcleo Accumbens (estriado ventral - motivación y refuerzo). Destino Vía Mesocortical: Corteza Orbitofrontal y prefrontal (procesamiento del placer hedonista e incentivo).","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-025 / G0151 del banco canónico | integración: Tema 1.6 + Tema 1.8 + Tema 1.9.2 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Adicional_Parte4.pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #153) / 10-10 Clase_ Memoria, Emociones / TEMA 7 – FUNCIONES CEREBRALES SUPERIORES.pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-94","number":"94","statement":"En el contexto del control motor por los ganglios basales, la activación de la VÍA DIRECTA facilita la ejecución del movimiento voluntario. Señale la secuencia ordenada de acontecimientos que desencadena este circuito:","options":["Activación glutamatérgica de la corteza sobre el estriado → Inhibición GABAérgica del estriado sobre el globo pálido interno → Desinhibición del tálamo motor → Activación glutamatérgica del tálamo sobre la corteza motora.","Inhibición de la corteza → Activación del globo pálido externo → Bloqueo total del tálamo.","Activación del núcleo subtalámico → Estimulación masiva del globo pálido interno → Inhibición de la corteza.","Desinhibición del globo pálido externo → Activación de la sustancia negra pars reticulata."],"answer":0,"explanation":"[Explicación 1 (Todas as questoes ate tema 1.10.1.pdf Q3)] Hack de la Desinhibición Talamocortical en la Vía Directa: La vía directa es un circuito de doble inhibición en serie: 1. El estriado activado inhibe al Globo Pálido Interno (GPi) (salida). 2. Al quedar inhibido el GPi, deja de liberar GABA sobre el tálamo (VA/VL). 3. El tálamo se DESINHIBA y envía impulsos glutamatérgicos excitadores a la corteza motora para iniciar la acción. || [Explicación 2 (Neuro_Adicional_Parte4.pdf Q3)] Hack de la Desinhibición Talamocortical en la Vía Directa: La vía directa es un circuito de doble inhibición en serie: El estriado activado inhibe al Globo Pálido Interno (GPi) (salida). Al quedar inhibido el GPi, deja de liberar GABA sobre el tálamo (VA/VL). El tálamo se DESINHIBA y envía impulsos glutamatérgicos excitadores a la corteza motora para iniciar la acción.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-026 / G0171 del banco canónico | integración: Tema 1.6 + Tema 1.9.1 + Tema 1.9.2 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Adicional_Parte4.pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #141, #209, #245) / wuolah- free-EXAMEN-NEURO-2-SIN-RESPUESTAS.pdf (Pregunta #11) / 10-16 Clase_ Ganglios Basales y Circuitos Motores","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-95","number":"95","statement":"A diferencia de la vía directa, la VÍA INDIRECTA de los ganglios basales actúa como un freno motor para suprimir movimientos no deseados. Señale la asociación CORRECTA entre la estructura intrínseca de esta vía y el neurotransmisor que libera sobre su blanco sináptico:","options":["Núcleo Subtalámico → Libera GLUTAMATO (excitador) sobre el segmento interno del globo pálido (GPi).","Globo Pálido Externo → Libera GLUTAMATO sobre el núcleo subtalámico.","Sustancia Negra pars compacta → Libera GABA sobre el tálamo motor.","Corteza motora suplementaria → Libera GABA sobre el putamen."],"answer":0,"explanation":"[Explicación 1 (Todas as questoes ate tema 1.10.1.pdf Q4)] Hack del Único Núcleo Excitador (Subtalámico): El Núcleo Subtalámico (STN) es el ÚNICO núcleo intrínseco de los ganglios basales que es GLUTAMATÉRGICO / EXCITADOR. Todos los demás núcleos intrínsecos (estriado, GPe, GPi, SNr) son GABAérgicos/inhibidores. La banca intenta confundir afirmando que el GPe libera glutamato o que el subtalámico libera GABA.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-027 / G0172 del banco canónico | integración: Tema 1.6 + Tema 1.9.2 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Adicional_Parte4.pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #210, #244, #265) / 11-06 Tutoría_ Neurofisiología y Neuroanatomía / 10-16 Clase_ Ganglios Basales y Circuitos Motores","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-96","number":"96","statement":"En la patofisiología de la Enfermedad de Parkinson, la destrucción progresiva de las neuronas dopaminérgicas de la sustancia negra pars compacta rompe el equilibrio funcional de los ganglios basales. ¿Qué alteración de circuito explica los síntomas hipocinéticos (acinesia, rigidez y bradicinesia)?:","options":["Pérdida de la estimulación D1 en la vía directa y pérdida de la inhibición D2 en la vía indirecta, provocando una sobreactivación tónica del Globo Pálido Interno que inhibe masivamente al tálamo motor.","Destrucción masiva de interneuronas colinérgicas dentro del globo pálido interno.","Hipertrofia del núcleo caudado con liberación masiva de dopamina a la corteza.","Desaparición del núcleo subtalámico con abolición del GABA."],"answer":0,"explanation":"No incluida en el material.","hack":"Hack del Falso Detalle en Parkinson (Trampa de Aitana): En las alternativas de examen, la banca coloca como distractor que el Parkinson ocurre \"por la destrucción de interneuronas colinérgicas del globo pálido interno\". ¡FALSO! El Parkinson se debe a la pérdida de neuronas dopaminérgicas de la sustancia negra pars compacta.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-028 / G0174 del banco canónico | integración: Tema 1.5.1 + Tema 1.6 + Tema 1.9.2 + Tema 1.11.2 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Adicional_Parte4.pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #99, #100) / ex. 2 (respuestas).pdf (Pregunta #42) / 10-16 Aula_ Ganglios Basales y Patologías del Movimiento","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-97","number":"97","statement":"Los trastornos hipercinéticos se caracterizan por movimientos involuntarios excesivos. Indique la causa neuroanatómica específica que desencadena el Hemibalismo (movimientos balísticos violentos e involuntarios de las extremidades contralaterales):","options":["Lesión destructiva o infarto vascular focal del Núcleo Subtalámico (de Luys).","Degeneración de la corteza visual primaria.","Pérdida de las motoneuronas alpha de la médula espinal.","Oclusión del acueducto de Silvio."],"answer":0,"explanation":"No incluida en el material.","hack":"Hack del Hemibalismo y el Núcleo Subtalámico: Si se destruye el Núcleo Subtalámico, este no puede enviar Glutamato (+) para activar al GPi. Al quedar el GPi inactivo, el tálamo queda sin su freno inhibidor habitual y dispara impulsos descontrolados a la corteza motora, produciendo Hemibalismo contralateral.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-029 / G0175 del banco canónico | integración: Tema 1.6 + Tema 1.9.2 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Adicional_Parte4.pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #99) / ex. 2 (respuestas).pdf (Pregunta #42) / 10-16 Aula_ Ganglios Basales y Patologías del Movimiento","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-98","number":"98","statement":"Con relación a los mecanismos neuroendocrinos del ciclo sueño-vigilia y la producción de melatonina, señale la afirmación VERDADERA:","options":["La oscuridad estimula la síntesis de melatonina en los pinealocitos a través de la vía simpática procedente del ganglio cervical superior, tras la desinhibición del núcleo paraventricular.","La luz solar directa estimula la producción masiva de melatonina en la glándula pineal.","El núcleo supraquiasmático (NSQ) secreta melatonina directamente al cuarto ventrículo.","La glándula pineal recibe inervación exclusivamente parasimpática del nervio vago."],"answer":0,"explanation":"No incluida en el material.","hack":"Hack de Inversión Luz vs. Melatonina: La banca intenta engañar al estudiante afirmando que la luz activa la melatonina. ¡FALSO! La luz inhibe al NSQ; es la OSCURIDAD la que desencadena la señal simpática desde el ganglio cervical superior hacia la glándula pineal para secretar melatonina.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-030 / G0197 del banco canónico | integración: Tema 1.6 + Tema 1.8 + Tema 1.12 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Adicional_Parte4.pdf | referencias indicadas: wuolah-free-EXAMEN-2017-2018-1 (1).pdf (Pregunta #4, #5) / 10-13 Clase_ Funciones Cerebrales, Ritmos Circadianos y Sueño","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-99","number":"99","statement":"El Sistema Activador Reticular Ascendente (SARA) sostiene el estado de alerta y vigilia mediante dos vías principales de proyección hacia el prosencéfalo. Indique la trayectoria neuroanatómica de la vía dorsal y de la vía ventral del SARA:","options":["La vía dorsal proyecta desde el tegmento del tronco hacia los núcleos intralaminares y reticular del tálamo; mientras que la vía ventral atraviesa el hipotálamo lateral y el prosencéfalo basal para inervar directamente la corteza cerebral sin relevo talámico.","La vía dorsal nace en la retina y termina en el cerebelo.","Ambas vías finalizan exclusivamente en la médula espinal sacra.","La vía ventral es exclusivamente motora voluntaria para la lengua."],"answer":0,"explanation":"[Explicación 1 (Todas as questoes ate tema 1.10.1.pdf Q54)] Hack de las Dos Rutas del SARA: Vía Dorsal: Tegmento rostral -> Núcleos Intralaminares del Tálamo -> Activación cortical difusa. Vía Ventral: Tegmento rostral -> Hipotálamo Lateral y Prosencéfalo Basal (Núcleo Basal de Meynert) -> Proyección directa a la corteza sin pasar por el tálamo.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-031 / G0209 del banco canónico | integración: Tema 1.6 + Tema 1.7 + Tema 1.8 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Archivo3_Parte1.pdf | referencias indicadas: 10-13 Clase_ Funciones Cerebrales, Ritmos Circadianos y Sueño / 09-25 Clase_ Neuroanatomía del Mesencéfalo / NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #156, #180)","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-100","number":"100","statement":"En el circuito motor de los ganglios basales, la VÍA INDIRECTA actúa como un freno para suprimir movimientos no deseados o inapropiados. Señale la secuencia correcta de eventos neuroquímicos que se desencadenan en esta vía:","options":["La corteza activa (glutamato) al estriado → El estriado inhibe (GABA) al Globo Pálido Externo (GPe) → El GPe desinhibe al Núcleo Subtalámico (STN) → El STN activa (glutamato) al Globo Pálido Interno (GPi) → El GPi inhibe (GABA) al tálamo motor, reduciendo la activación cortical.","La corteza inhibe al estriado → El estriado activa al GPe → El tálamo se hiperactiva.","El núcleo subtalámico libera GABA sobre el globo pálido externo e inhibe directamente la médula espinal.","La vía indirecta conecta directamente la sustancia negra con las células de Purkinje del cerebelo."],"answer":0,"explanation":"[Explicación 1 (Todas as questoes ate tema 1.10.1.pdf Q9)] Hack de la Vía Indirecta: 1. Estriado inhibe a GPe (salida transitoria). 2. GPe inactivo desinhibe al Núcleo Subtalámico (STN). 3. STN activado envía Glutamato (+) al GPi. 4. GPi hiperactivo libera GABA (-) masivo sobre el tálamo (VA/VL). || [Explicación 2 (Neuro_Archivo3_Parte1.pdf Q9)] Hack de la Vía Indirecta: Estriado inhibe a GPe (salida transitoria). GPe inactivo desinhibe al Núcleo Subtalámico (STN). STN activado envía Glutamato (+) al GPi. GPi hiperactivo libera GABA (-) masivo sobre el tálamo (VA/VL).","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-032 / G0213 del banco canónico | integración: Tema 1.6 + Tema 1.9.2 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Archivo3_Parte1.pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #10, #142) / 10-16 Aula_ Ganglios Basales y Patologías / ex. 2021 (respuestas).pdf (Pregunta #48)","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-101","number":"101","statement":"Respecto a la neurotransmisión y las aferencias que recibe el neoestriado (núcleo caudado y putamen), señale la afirmación CORRECTA:","options":["Recibe aferencias glutamatérgicas excitadoras de la corteza cerebral y del tálamo, y aferencias dopaminérgicas de la sustancia negra pars compacta.","Recibe únicamente axones GABAérgicos de la médula espinal.","Sus principales aferencias son noradrenérgicas procedentes del locus coeruleus.","La corteza motora libera GABA para inhibir directamente al putamen."],"answer":0,"explanation":"[Explicación 1 (Todas as questoes ate tema 1.10.1.pdf Q10)] Hack de las Aferencias Estriatales (Input): El Estriado (Caudado + Putamen) es el principal núcleo de ENTRADA (input) de los ganglios basales. Recibe: 1. Corteza cerebral: Glutamatérgica (+). 2. Tálamo: Glutamatérgica (+). 3. Sustancia Negra pars compacta (SNpc): Dopaminérgica (moduladora). || [Explicación 2 (Neuro_Archivo3_Parte1.pdf Q10)] Hack de las Aferencias Estriatales (Input): El Estriado (Caudado + Putamen) es el principal núcleo de ENTRADA (input) de los ganglios basales. Recibe: Corteza cerebral: Glutamatérgica (+). Tálamo: Glutamatérgica (+). Sustancia Negra pars compacta (SNpc): Dopaminérgica (moduladora).","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-033 / G0214 del banco canónico | integración: Tema 1.5.1 + Tema 1.6 + Tema 1.7 + Tema 1.9.2 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Archivo3_Parte1.pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #118) / 10-16 Clase_ Ganglios Basales y Circuitos Motores / Tema 1.9.2 - Ganglios basales y movimiento","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-102","number":"102","statement":"En un corte coronal o transversal del cerebro, señale la relación anatómica VERDADERA entre el núcleo caudado, la cápsula interna y el tálamo:","options":["En una sección frontal del cerebro, el cuerpo del núcleo caudado se ubica superiormente con respecto al globo pálido interno, estando separado del tálamo por el surco optoestriado.","El núcleo caudado es una parte anatómica del núcleo lenticular.","El putamen es más medial que el tálamo.","La cápsula interna se sitúa lateralmente al putamen."],"answer":0,"explanation":"[Explicación 1 (Todas as questoes ate tema 1.10.1.pdf Q11)] Hack de Relaciones Coronales/Frontales: Caudado: Arriba y medial, bordeando los ventrículos laterales. Cápsula interna: Separa tálamo/caudado (mediales) del núcleo lenticular (lateral). Lenticular (Putamen + Pálido): Lateral a la cápsula interna.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-034 / G0215 del banco canónico | integración: Tema 1.6 + Tema 1.7 + Tema 1.9.2 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Archivo3_Parte1.pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #243) / 09-30 Clase de Neuroanatomía_ Tálamo, Sistema Límbico y Ganglios Basales / exame neuro 2025 transcrito juneka.pdf (Pregunta #12)","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-103","number":"103","statement":"En la patofisiología de la Corea de Huntington (trastorno neurodegenerativo hipercinético hereditario), ¿qué alteración específica de los ganglios basales desencadena los movimientos coréicos e involuntarios?:","options":["Degeneración selectiva de las neuronas de proyección GABAérgicas del estriado que pertenecen a la VÍA INDIRECTA, provocando una menor inhibición talamocortical.","Destrucción aislada del núcleo ventral posterior del tálamo.","Pérdida total de las neuronas dopaminérgicas de la sustancia negra pars compacta.","Hipertrofia del núcleo subtalámico."],"answer":0,"explanation":"[Explicación 1 (Todas as questoes ate tema 1.10.1.pdf Q13)] Hack de Huntington vs. Parkinson: Parkinson: Afecta a la vía directa (pérdida de dopamina en SNpc) -> Hipocinesia. Huntington: Degenera las neuronas estriatales de la vía indirecta -> Se pierde el freno motor -> Hipercinesia.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-035 / G0217 del banco canónico | integración: Tema 1.6 + Tema 1.9.2 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Archivo3_Parte1.pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #10, #209, #245) / 10-16 Aula_ Ganglios Basales y Patologías del Movimiento / wuolah-free-Examen- Neuro-3.pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-104","number":"104","statement":"En un individuo sano en estado de reposo (sin intención de realizar ningún movimiento voluntario), ¿cuál es el estado funcional del Globo Pálido Interno (GPi) sobre el tálamo motor?:","options":["El GPi presenta una actividad eléctrica tónica espontánea y libera GABA continuamente sobre el tálamo, manteniendo bloqueadas las proyecciones talamocorticales.","El GPi está totalmente inactivo y en silencio eléctrico.","El GPi libera glutamato para activar masivamente la corteza frontal.","El GPi envía fibras directo a los músculos para mantener el tono."],"answer":0,"explanation":"No incluida en el material.","hack":"Hack del Reposo y la Inhibición Tónica: En reposo, el GPi está tónicamente activo y suelta GABA de forma ininterrumpida sobre el tálamo (VA/VL). Para movernos, necesitamos inhibir al GPi para desinhibir al tálamo (vía directa).","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-036 / G0218 del banco canónico | integración: Tema 1.6 + Tema 1.9.2 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Archivo3_Parte1.pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #142) / 10-16 Clase_ Ganglios Basales y Circuitos Motores / ex. 2021 (respuestas).pdf (Pregunta #48)","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-105","number":"105","statement":"En las conexiones intrínsecas de los ganglios basales, el Globo Pálido Externo (GPe) realiza un papel modulador clave. Señale la asociación CORRECTA sobre el neurotransmisor que libera sobre sus núcleos diana:","options":["Libera GABA (inhibitorio) sobre el núcleo subtalámico y sobre el globo pálido interno.","Libera Glutamato (excitatorio) sobre la corteza motora primaria.","Libera Dopamina sobre el núcleo caudado.","Libera Acetilcolina sobre la médula espinal."],"answer":0,"explanation":"No incluida en el material.","hack":"Hack de la Eferencia GABAérgica del GPe: Todas las proyecciones eferentes que nacen en el Globo Pálido Externo (GPe) son GABAérgicas (inhibidoras), dirigidas hacia el Núcleo Subtalámico (STN) y hacia el GPi.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-037 / G0221 del banco canónico | integración: Tema 1.6 + Tema 1.9.2 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Archivo3_Parte1.pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #244) / 10-16 Clase_ Ganglios Basales y Circuitos Motores / ex. 2021 (respuestas).pdf (Pregunta #48)","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-106","number":"106","statement":"Los impulsos eferentes de los ganglios basales dirigidos hacia el diencéfalo para retornar a la corteza cerebral hacen relevo sináptico en núcleos talámicos específicos. Indique la pareja de núcleos talámicos implicados primariamente en este bucle motor:","options":["Núcleo Ventral Anterior (VA) y Núcleo Ventral Lateral (VL).","Núcleo Geniculado Lateral y Geniculado Medial.","Núcleo Posterior y Pulvinar.","Núcleo Habenular lateral."],"answer":0,"explanation":"[Explicación 1 (Todas as questoes ate tema 1.10.1.pdf Q19)] Hack de los Núcleos Talámicos Motores: VA (Ventral Anterior) y VL (Ventral Lateral): Núcleos motores de relevo que reciben a GABA del GPi y envían Glutamato (+) a la corteza premotora y motora suplementaria.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-038 / G0223 del banco canónico | integración: Tema 1.6 + Tema 1.7 + Tema 1.9.2 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Archivo3_Parte1.pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #99) / 10-16 Clase_ Ganglios Basales y Circuitos Motores / TEMA 5 – DIENCÉFALO.pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-107","number":"107","statement":"En la vía indirecta de los ganglios basales, ¿cuál es el único núcleo intrínseco de naturaleza GLUTAMATÉRGICA (excitadora) y sobre qué estructuras proyecta sus axones?:","options":["El Núcleo Subtalámico (STN), que proyecta axones excitadores sobre el Globo Pálido Interno (GPi) y la Sustancia Negra pars reticulata.","El Globo Pálido Externo sobre el tálamo.","El Núcleo Caudado sobre la médula espinal.","El Núcleo Accumbens sobre el cerebelo."],"answer":0,"explanation":"No incluida en el material.","hack":"Hack del STN Glutamatérgico: Todos los núcleos de los ganglios basales son GABAérgicos (inhibidores), EXCEPTO el Núcleo Subtalámico, que es el ÚNICO excitador (Glutamato).","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-039 / G0227 del banco canónico | integración: Tema 1.5.1 + Tema 1.6 + Tema 1.9.2 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Archivo3_Parte1.pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #210, #265) / 10-16 Clase_ Ganglios Basales / TEMA 9 – GANGLIOS BASLES Y MOVIMIENTO.pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-108","number":"108","statement":"Ordene la secuencia cronológica de acontecimientos que tiene lugar durante la activación de la VÍA DIRECTA de los ganglios basales para ejecutar un movimiento: 1. Desinhibición de las proyecciones tálamo-corticales. 2. Activación glutamatérgica del estriado por la corteza. 3. Inhibición GABAérgica del globo pálido interno. 4. Activación de la corteza motora suplementaria y ejecución motora.","options":["2 → 3 → 1 → 4.","1 → 2 → 3 → 4.","4 → 3 → 2 → 1.","3 → 1 → 4 → 2."],"answer":0,"explanation":"[Explicación 1 (Todas as questoes ate tema 1.10.1.pdf Q25)] Hack del Orden Numérico de la Vía Directa: 1º Activación estriatal (2). 2º Inhibición de GPi (3). 3º Desinhibición del Tálamo (1). 4º Re-activación Cortical (4).","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-040 / G0229 del banco canónico | integración: Tema 1.6 + Tema 1.9.1 + Tema 1.9.2 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Archivo3_Parte1.pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #141) / 10-16 Clase_ Ganglios Basales y Circuitos Motores / ex. 2021 (respuestas).pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-109","number":"109","statement":"Indique la afirmación VERDADERA sobre la anatomía de los núcleos basales y sus relaciones vasculares/de sustancia blanca:","options":["En una sección transversal del cerebro, la cápsula interna separa al tálamo respecto del globo pálido y putamen.","El putamen es más interno/medial que el globo pálido.","La cola del caudado forma parte del núcleo lenticular.","La cápsula externa separa el tálamo del núcleo caudado."],"answer":0,"explanation":"No incluida en el material.","hack":"Hack de la Cápsula Interna como Frontera: La cápsula interna es la lámina de sustancia blanca que separa medialmente al Tálamo y al Caudado, respecto al Núcleo Lenticular (Putamen + Pálido) ubicado lateralmente.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-041 / G0230 del banco canónico | integración: Tema 1.6 + Tema 1.7 + Tema 1.9.2 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Archivo3_Parte1.pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #208) / 09-30 Clase de Neuroanatomía / Tema 1.9.2 - Ganglios basales","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-110","number":"110","statement":"Un paciente sufre un accidente cerebrovascular isquémico agudo con un pequeño infarto lacunar circunscrito al Núcleo Subtalámico de Luys derecho. ¿Qué síntoma motor contralateral involuntario presentará de inmediato el paciente?:","options":["Hemibalismo izquierdo (movimientos balísticos violentos e incontrolables de las extremidades izquierdas).","Parálisis flácida del ojo derecho.","Pérdida de la audición del oído izquierdo.","Anestesia del dolor corporal."],"answer":0,"explanation":"No incluida en el material.","hack":"Hack del Hemibalismo por Lesión Subtalámica: Si falla el Núcleo Subtalámico (STN), el GPi se queda sin estímulo excitador, el tálamo se desinhibe por completo y la corteza motora dispara descargas balísticas violentas e incontroladas.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-042 / G0233 del banco canónico | integración: Tema 1.6 + Tema 1.9.2 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Archivo3_Parte1.pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #99) / 10-16 Aula_ Ganglios Basales / Recopilación preguntas neuro (1).pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-111","number":"111","statement":"Analice las siguientes afirmaciones sobre la neurobiología de los ganglios basales tomadas directamente de las opciones de examen oficial. Indique la ÚNICA opción VERDADERA:","options":["El Núcleo Subtalámico es el único núcleo intrínseco de los ganglios basales que ejerce una acción sináptica excitadora (glutamatérgica) en la vía indirecta.","El putamen es más medial que el globo pálido interno.","La vía directa produce una inhibición global de la corteza motora.","Los ganglios basales envían axones de proyección directa a las motoneuronas de la médula espinal."],"answer":0,"explanation":"[Explicación 1 (Todas as questoes ate tema 1.10.1.pdf Q32)] Hack Gran Resumen de Ganglios Basales: Option A (VERDADERA): El STN es el único núcleo glutamatérgico excitador. Option B (FALSA): El putamen es LATERAL al globo pálido. Option C (FALSA): La vía directa ACTIVADOR / FACILITADORA de la corteza. Option D (FALSA): NO HAY conexíón directa con la médula.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-043 / G0236 del banco canónico | integración: Tema 1.6 + Tema 1.9.2 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Archivo3_Parte1.pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Preguntas #10, #44, #98, #99, #100, #141, #142, #208, #209, #210, #243, #244, #245, #264, #265) / Tema 1.9.2 - Ganglios basales","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-112","number":"112","statement":"Respecto al Pedúnculo Cerebeloso Superior (Brachium conjunctivum), señale la afirmación VERDADERA:","options":["Es la principal vía de salida (eferente) del cerebelo, transportando axones desde el núcleo dentado e interpósitos hacia el núcleo rojo contralateral y hacia el núcleo ventral lateral (VL) del tálamo.","Es una vía 100% aferente que nace en el núcleo coclear.","Une el cerebelo con el bulbo raquídeo caudal.","Transporta únicamente fibras parasimpáticas para el estómago."],"answer":0,"explanation":"No incluida en el material.","hack":"Hack Eferente del Pedúnculo Superior: El Pedúnculo Cerebeloso Superior conecta el cerebelo con el mesencéfalo y diencéfalo. Es la vía eferente primaria (haces dentadotalámico e interpuestorrúbrico).","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-044 / G0250 del banco canónico | integración: Tema 1.5.1 + Tema 1.6 + Tema 1.9.3 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Archivo3_Parte1.pdf | referencias indicadas: Recopilación preguntas neuro (1).pdf / 10-17 Clase magistral_ Circuitería del cerebelo / NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-113","number":"113","statement":"La vía del cordón posterior-lemnisco medial conduce la sensibilidad táctil epicrítica, propiocepción consciente y sensibilidad vibratoria (palestesia). Señale la ubicación exacta de la decusación de esta vía y el nombre que reciben sus fibras cruzadas:","options":["Decusan en el bulbo raquídeo caudal como fibras arqueadas (arcuatas) internas, formando inmediatamente el lemnisco medial que asciende hacia el tálamo VPL.","Decusan en la comisura blanca anterior de la médula espinal dos segmentos por encima del nivel de entrada.","Decusan en el mesencéfalo a nivel de los colículos superiores.","No decusan en ningún punto y ascienden ipsilateralmente hasta la corteza parietal."],"answer":0,"explanation":"[Explicación 1 (Todas as questoes ate tema 1.10.1.pdf Q8)] Hack de la Decusación Lemniscal (Bulbo) vs. Espinotalámica (Médula): Vía Lemniscal (Tacto fino/Propiocepción): Sube IPSILATERAL por la médula (Grácil/Cuneiforme) -> Decusa en el BULBO (Fibras Arqueadas Internas) -> Lemnisco Medial. Vía Espinotalámica (Dolor/Temperatura): Decusa en la MÉDULA (Comisura blanca anterior) a nivel de entrada.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-045 / G0286 del banco canónico | integración: Tema 1.4 + Tema 1.5.1 + Tema 1.6 + Tema 1.10 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Archivo3_Parte2.pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #17, #110) / 10-20 Clase magistral_ Sistema somatosensorial / ex. 2021 (respuestas).pdf (Pregunta #46)","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-114","number":"114","statement":"En la vía del cordón posterior-lemnisco medial, los axones de las neuronas de segundo orden (que nacen en los núcleos grácil y cuneiforme del bulbo) cruzan la línea media y forman el lemnisco medial. ¿En qué núcleo del tálamo hacen sinapsis con las neuronas de tercer orden?:","options":["Núcleo Ventral Posterolateral (VPL) del tálamo.","Núcleo Ventral Posteromedial (VPM) del tálamo.","Núcleo Anterior del tálamo.","Núcleo Geniculado Lateral del tálamo."],"answer":0,"explanation":"[Explicación 1 (Todas as questoes ate tema 1.10.1.pdf Q14)] Hack VPL (Cuerpo) vs. VPM (Cara): VPL (Ventral Posterolateral): Recibe la sensibilidad táctil, térmica y nociceptiva del CUERPO (vía lemniscal y vía espinotalámica). VPM (Ventral Posteromedial): Recibe la sensibilidad táctil, térmica, nociceptiva y gustativa de la CARA Y CABEZA (vía trigeminal y tracto solitario).","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-046 / G0292 del banco canónico | integración: Tema 1.4 + Tema 1.5.1 + Tema 1.6 + Tema 1.10 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Archivo3_Parte2.pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #92, #148) / ex. 2021 (respuestas).pdf (Pregunta #53) / ex. 2022 (sin respuestas) 2.pdf (Pregunta #64)","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-115","number":"115","statement":"La información exteroceptiva nociceptiva y térmica procedente de la cara y región craneofacial es recogida por las tres ramas del nervio trigémino (V par). ¿En qué núcleo del tronco del encéfalo hacen sinapsis sus neuronas sensitivas de primer orden antes de decusar hacia el tálamo VPM?:","options":["En la porción espinal (núcleo trigeminal espinal), que se extiende desde la protuberancia caudal hasta los primeros segmentos medulares cervicales (C1-C2).","En el núcleo mesencefálico del trigémino.","En el núcleo motor del nervio facial.","En el núcleo gracilis del bulbo."],"answer":0,"explanation":"[Explicación 1 (Todas as questoes ate tema 1.10.1.pdf Q17)] Hack de la Tripartición del Complejo Trigeminal: Núcleo Mesencefálico del V: Propiocepción de músculos masticatorios (¡Somas de 1ª orden dentro del SNC!). Núcleo Principal / Pontino del V: Tacto fino epicrítico de la cara. Núcleo Espinal del V: DOLOR Y TEMPERATURA DE LA CARA.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-047 / G0295 del banco canónico | integración: Tema 1.5.1 + Tema 1.5.2 + Tema 1.6 + Tema 1.10 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Archivo3_Parte2.pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #185, #186) / 10-22C~1.MP3 / 10-20 Clase magistral_ Sistema somatosensorial","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-116","number":"116","statement":"Respecto a la trayectoria del tracto espinotalámico lateral (vía del dolor y la temperatura corporal), señale la afirmación CORRECTA sobre la ubicación de sus neuronas de segundo orden y el nivel de decusación de sus axones:","options":["Sus neuronas de segundo orden se ubican en las astas posteriores de la médula espinal (láminas I y V de Rexed); sus axones decusan inmediatamente en la comisura blanca anterior y ascienden por el cordón lateral contralateral hasta el núcleo VPL del tálamo.","Sus neuronas de segundo orden están en el tálamo y decusan en las pirámides bulbares.","Asciende de forma estrictamente ipsilateral por los cordones posteriores de la médula espinal.","Sus axones decusan en el cuerpo calloso."],"answer":0,"explanation":"No incluida en el material.","hack":"Hack de la Decusación Medular del Espinotalámico: El axón de la segunda neurona del dolor decusa en la MÉDULA ESPINAL (comisura blanca anterior) a nivel de la metámera de entrada. Por eso, una hemisección medular (Síndrome de Brown-Séquard) produce pérdida del dolor y temperatura en el lado CONTRALATERAL por debajo de la lesión.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-048 / G0296 del banco canónico | integración: Tema 1.4 + Tema 1.6 + Tema 1.10 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Archivo3_Parte2.pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #32, #40) / wuolah-free- Examen-Neuro-recu-junio-2023 orc.pdf (Pregunta #56) / 12-15 Lección_ Neurobiología del Dolor","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-117","number":"117","statement":"La corteza somatosensorial primaria (S1, áreas 3, 1 y 2 de Brodmann) presenta una subdivisión funcional interna donde las aferencias específicas procedentes del tálamo (VPL y VPM) no se distribuyen al azar. Indique la capa histológica y la subárea cortical que actúa como puerta de entrada principal para los estímulos cutáneos y propioceptivos:","options":["Las aferencias talámicas llegan masivamente a la capa IV del Área 3 (subárea 3a para propiocepción y subárea 3b para estímulos cutáneos), desde donde se proyectan internamente hacia las áreas 1 y 2.","Las aferencias llegan exclusivamente a la capa I del área 2 sin pasar por el área 3.","Las aferencias sinaptan directamente en la capa VI del lóbulo occipital.","La información somatosensorial ingresa únicamente por el área 4 motor primario."],"answer":0,"explanation":"[Explicación 1 (Todas as questoes ate tema 1.10.1.pdf Q21)] Hack de la Subdivisión de S1 (Área 3a/3b vs. 1 vs. 2): Área 3 (Fondo del surco central): Puerta de entrada primaria (Capa IV). 3a: Propiocepción (músculos y articulaciones). 3b: Estímulos cutáneos (superficiales, térmicos, nociceptivos). Área 1: Discriminación de texturas. Área 2: Discriminación de forma y tamaño de los objetos.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-049 / G0299 del banco canónico | integración: Tema 1.6 + Tema 1.7 + Tema 1.10 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Archivo3_Parte2.pdf | referencias indicadas: 10-21C~1.MP3 / 10-20 Clase magistral_ Sistema somatosensorial / Tema 1.10 - Sistema somatosensorial 25-26.pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-118","number":"118","statement":"Para la percepción y discriminación del tacto epicrítico y la presión fina de la CARA y región craneofacial, ¿qué núcleo del complejo trigeminal recibe las aferencias primarias y cuál es el nombre del tracto que asciende hacia el tálamo VPM?:","options":["Núcleo sensitivo principal (pontino) del trigémino, cuyos axones decusan y forman el lemnisco trigeminal (tracto trigeminotalámico).","Núcleo espinal del trigémino, enviando axones por el fascículo grácil.","Núcleo motor del abducens, proyectando al cerebelo.","Núcleo ambiguo del bulbo raquídeo de forma ipsilateral."],"answer":0,"explanation":"[Explicación 1 (Todas as questoes ate tema 1.10.1.pdf Q22)] Hack del Núcleo Principal vs. Espinal del Trigémino: Núcleo Principal / Pontino: TACTO FINO EPICRÍTICO Y PRESIÓN craneofacial. Núcleo Espinal (Caudal): DOLOR Y TEMPERATURA craneofacial. La banca afirma que el núcleo espinal procesa el tacto fino o que el principal procesa el dolor. ¡FALSO!","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-050 / G0300 del banco canónico | integración: Tema 1.5.1 + Tema 1.5.2 + Tema 1.6 + Tema 1.10 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Archivo3_Parte2.pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #186) / 10-21C~1.MP3 / TEMA 11 – SISTEMA SOMATOSENSORIAL .pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-119","number":"119","statement":"La transmisión nociceptiva asciende hacia el encéfalo diversificándose en dos componentes: el componente sensorial-discriminativo y el componente afectivo-emocional. Indique qué núcleo talámico y qué sistema subcortical procesan la vivencia desagradable y la respuesta emocional del dolor:","options":["Los núcleos intralaminares (y centromediano) del tálamo, proyectando hacia el sistema límbico (corteza del cíngulo anterior e ínsula).","El núcleo geniculado lateral proyectando a la corteza visual.","El núcleo rojo proyectando al órgano de Corti.","El núcleo ambiguo proyectando a la retina."],"answer":0,"explanation":"[Explicación 1 (Todas as questoes ate tema 1.10.1.pdf Q26)] Hack de las Dos Rutas del Dolor (Discriminativo vs. Emocional): Vía Neoespinotalámica (VPL del Tálamo -> S1): Codifica ¿DÓNDE duele?, ¿CUÁNDO?, ¿QUÉ INTENSIDAD?. Vía Paleoespinotalámica / Espinorreticular (Núcleos Intralaminares -> Límbico / Cíngulo / Ínsula): Codifica el sufrimiento, la aversión y la emoción desagradable del dolor.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-051 / G0304 del banco canónico | integración: Tema 1.6 + Tema 1.7 + Tema 1.8 + Tema 1.10 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Archivo3_Parte2.pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #186) / 2025-10-21 16_40_07 merged.mp / TEMA 11 – SISTEMA SOMATOSENSORIAL .pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-120","number":"120","statement":"Indique la diferencia anatómica y de destino cortical/subcortical entre la propiocepción consciente y la propiocepción inconsciente:","options":["La propiocepción consciente asciende por los cordones posteriores (Grácil/Cuneiforme) hasta el tálamo VPL y la corteza parietal S1 (área 3a); mientras que la propiocepción inconsciente asciende por los tractos espinocerebelosos directamente hacia la corteza del cerebelo.","La propiocepción consciente va al cerebelo y la inconsciente a la corteza visual.","Ambas terminan en el hipotálamo sin pasar por la médula espinal.","La propiocepción inconsciente viaja por las fibras gustativas del IX par."],"answer":0,"explanation":"[Explicación 1 (Todas as questoes ate tema 1.10.1.pdf Q37)] Hack Propiocepción Consciente vs. Inconsciente: Consciente: Cordón Posterior -> Lemnisco Medial -> Tálamo VPL -> Corteza Parietal S1 (Área 3a). Inconsciente: Tractos Espinocerebelosos -> Corteza del Cerebelo.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-052 / G0315 del banco canónico | integración: Tema 1.6 + Tema 1.7 + Tema 1.9.3 + Tema 1.10 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Archivo3_Parte2.pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #117, #258) / 12-11 Lección_ Fisiología Sensorial / ex. 2 (respuestas).pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-121","number":"121","statement":"Un paciente sufre una oclusión aguda de la Arteria Espinal Anterior a nivel medular torácico (T6-T8). En la exploración neurológica por debajo del nivel de la lesión, ¿qué disociación sensitiva característica presentará el paciente?:","options":["Pérdida bilateral de la sensibilidad dolorosa y térmica (afectación de los tractos espinotalámicos anteriores y laterales), con conservación intacta del tacto epicrítico, la vibración y la propiocepción consciente (preservación de los cordones posteriores).","Pérdida total de la propiocepción con conservación del dolor y la temperatura.","Anestesia completa en silla de montar exclusivamente.","Pérdida de la sensibilidad en la cara por afectación del trigémino."],"answer":0,"explanation":"[Explicación 1 (Todas as questoes ate tema 1.10.1.pdf Q41)] Hack de la Disociación por Vascularización Medular: Arteria Espinal Anterior: Irriga los 2/3 anteriores de la médula (astas anteriores y cordones anterolaterales) -> Destruye el dolor y la temperatura, dejando intactos los cordones posteriores. Arterias Espinales Posteriores (2): Irrigan el 1/3 posterior (cordones posteriores Grácil y Cuneiforme) -> Si se ocluyen, se pierde el tacto fino y la propiocepción.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-053 / G0319 del banco canónico | integración: Tema 1.4 + Tema 1.6 + Tema 1.10 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Archivo3_Parte2.pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #11, #188) / 10-30 Clase magistral_ Neuroanatomía meníngea, vías medulares / wuolah-free-examenes-2011.pdf (Pregunta #6)","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-122","number":"122","statement":"En la clasificación de los receptores sensoriales del cuerpo humano según la naturaleza del estímulo adecuado, señale cuál de las siguientes opciones NO es un mecanorreceptor cutáneo o somático:","options":["Osmorreceptor del núcleo supraóptico e hipotálamo lateral.","Corpúsculo de Pacini.","Corpúsculo de Meissner.","Discos de Merkel."],"answer":0,"explanation":"[Explicación 1 (Todas as questoes ate tema 1.10.1.pdf Q45)] Hack de la Clasificación de Receptores: Mecanorreceptores: Pacini, Meissner, Merkel, Ruffini, huso neuromuscular y órgano tendinoso de Golgi. Osmorreceptores: Son quimiorreceptores/interorreceptores centralizados en el hipotálamo para detectar la osmolaridad plasmática.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-054 / G0323 del banco canónico | integración: Tema 1.6 + Tema 1.10 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Archivo3_Parte2.pdf | referencias indicadas: wuolah-free-examenes-2011.pdf (Pregunta #14) / 10-20 Clase_ Sistema Sensorial y Receptores Sensitivos / Tema 1.10 - Sistema somatosensorial 25-26.pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-123","number":"123","statement":"En su trayecto ascendente a través de los tres niveles del tronco del encéfalo (bulbo raquídeo, protuberancia y mesencéfalo), ¿en qué posición topográfica se sitúa el Lemnisco Espinal (Tracto Espinotalámico) en relación con el Lemnisco Medial?:","options":["Se ubica continuamente en una posición posterolateral (o ventrolateral externa) con respecto al lemnisco medial.","Ocupa el centro exacto de las pirámides bulbares.","Se sitúa medial al acueducto de Silvio dentro del núcleo rojo.","Desaparece en la protuberancia para reaparecer en la retina."],"answer":0,"explanation":"[Explicación 1 (Todas as questoes ate tema 1.10.1.pdf Q46)] Hack de la Posición en el Tronco (Lemnisco Medial vs. Espinal): Lemnisco Medial (Tacto/Propiocepción): Ocupa una posición MEDIAL cerca de la línea media en el bulbo y protuberancia. Lemnisco Espinal / Espinotalámico (Dolor/Temperatura): Viaja siempre POSTEROLATERAL a lo largo de todo el tronco del encéfalo.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-055 / G0324 del banco canónico | integración: Tema 1.5.1 + Tema 1.6 + Tema 1.10 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Archivo3_Parte2.pdf | referencias indicadas: 09-25 Clase_ Neuroanatomía del Mesencéfalo / NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #21, #185) / TEMA 3 – TRONCO DEL ENCÉFALO.pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-124","number":"124","statement":"Analice las siguientes proposiciones sobre la neurobiología y vías del Sistema Somatosensorial tomadas de las opciones de examen oficial. Indique la ÚNICA combinación donde TODAS las proposiciones sean VERDADERAS: 1. El canal catiónico TRPV1 es activado por calor nocivo (>43 °C), protones (pH ácido) y capsaicina. 2. La vía del cordón posterior-lemnisco medial decusa en el bulbo raquídeo caudal como fibras arqueadas internas y hace su último relevo sensitivo en el núcleo VPL del tálamo. 3. El dolor rápido se transmite por fibras mielínicas pequeñas A-delta y el dolor lento por fibras amielínicas C.","options":["1, 2 y 3 son VERDADERAS.","Solo 1 y 2 son verdaderas.","Solo 2 y 3 son verdaderas.","1, 2 y 3 son falsas."],"answer":0,"explanation":"[Explicación 1 (Todas as questoes ate tema 1.10.1.pdf Q48)] Hack del Gran Resumen del || [Explicación 2 (Neuro_Archivo3_Parte2.pdf Q48)] Hack del Gran Resumen del Tema 1.10:Proposición 1 (VERDADERA): TRPV1 = Calor >43 °C + Capsaicina + Protones (H⁺). Proposición 2 (VERDADERA): Lemnisco Medial = Decusación en Bulbo (Fibras Arqueadas) -> Tálamo VPL.Proposición 3 (VERDADERA): Dolor Agudo (Aδ) vs. Dolor Lento (C).","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-056 / G0326 del banco canónico | integración: Tema 1.4 + Tema 1.5.1 + Tema 1.6 + Tema 1.10 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Archivo3_Parte2.pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Preguntas #16, #49, #92, #94, #95, #106-#118, #148-#151, #185-#188, #250-#259) / Tema 1.10 - Sistema somatosensorial 25- 26.pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-125","number":"125","statement":"Las neuronas ganglionares de la retina procesan la información visual segregándola en vías funcionales paralelas hacia el Núcleo Geniculado Lateral (NGL) del tálamo. ¿Qué tipo de células ganglionares alimentan la vía de alta resolución espacial y en qué capas del NGL hacen sinapsis?:","options":["Las células ganglionares tipo P (parvocelulares), asociadas a los conos, que procesan detalles finos y color, proyectando sobre las capas 3, 4, 5 y 6 del NGL.","Las células ganglionares tipo M (magnocelulares), asociadas a conos, que sinaptan en la capa 3 del NGL.","Las células ganglionares W, que sinaptan exclusivamente en la corteza auditiva V1.","Las células M, que proyectan a las capas 3 a 6 para percibir colores primarios."],"answer":0,"explanation":"[Explicación 1 (Todas as questoes ate tema 1.10.1.pdf Q4)] Hack de las Capas del NGL (Magnocelular vs. Parvocelular): Capas 1 y 2 (MAGNOCELULARES): Reciben aferencias de células M (Magnocelulares / Bastones) -> Vía poco discriminativa, movimiento, contraste. Capas 3, 4, 5 y 6 (PARVOCELULARES): Reciben aferencias de células P (Parvocelulares / Conos) -> Vía de alta resolución, forma detallada y color.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-057 / G0330 del banco canónico | integración: Tema 1.6 + Tema 1.11.1 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Archivo3_Parte2.pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #120, #226) / 10-27 Clase_ Vía Visual y Reflejos / TEMA 12 – VISIÓN.pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-126","number":"126","statement":"La Radiación Óptica (bucle de Meyer y fibras geniculocalcarinas) constituye el tramo final de la vía visual consciente. ¿Cuál es su origen y su destino neuroanatómico exacto?:","options":["Se origina en las neuronas de tercer orden del Núcleo Geniculado Lateral del tálamo y proyecta hacia la Corteza Visual Primaria (V1 / Área 17) en los labios de la cisura calcarina del lóbulo occipital.","Se extiende desde el quiasma óptico directamente hacia el colículo superior del mesencéfalo.","Se origina en la retina y conecta directamente con el núcleo de Edinger-Westphal.","Nace en el lóbulo frontal y finaliza en el órgano de Corti."],"answer":0,"explanation":"No incluida en el material.","hack":"Hack de la Trampa del Trayecto de la Radiación Óptica: La banca intenta afirmar que \"la radiación óptica va desde el quiasma al geniculado\". ¡FALSO! Del quiasma al tálamo se llama TRACTO ÓPTICO. La RADIACIÓN ÓPTICA va exclusivamente del Núcleo Geniculado Lateral a la Corteza V1 (Área 17).","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-058 / G0332 del banco canónico | integración: Tema 1.6 + Tema 1.7 + Tema 1.11.1 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Archivo3_Parte2.pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #58, #226) / 11-06 Tutoría_ Neurofisiología y Neuroanatomía / ex. 2021 (respuestas).pdf (Pregunta #58)","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-127","number":"127","statement":"La Corteza Visual Primaria (V1, Área 17 de Brodmann o corteza estriada) recibe la información geniculocalcarina organizada en seis capas corticales. ¿A qué capa histológica concreta llegan de forma masiva los axones procedentes del Núcleo Geniculado Lateral del tálamo?:","options":["Capa IV (capa granular interna / subcapas IVa, IVb, IVc).","Capa I (capa molecular superficial exclusivamente).","Capa V (capa piramidal interna).","Capa VI (capa multiforme)."],"answer":0,"explanation":"No incluida en el material.","hack":"Hack de la Capa IV Receptorial de V1: Toda la neocorteza sensitiva primaria (y en especial V1 por ser una corteza heterotípica granular / estriada) tiene una Capa IV (Granular Interna) hipertrofiada, que es la destinataria exclusiva de las aferencias del tálamo (NGL).","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-059 / G0335 del banco canónico | integración: Tema 1.6 + Tema 1.7 + Tema 1.11.1 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Archivo3_Parte2.pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #120, #227, #252) / ex. 2 (respuestas).pdf (Pregunta #4) / TEMA 12 – VISIÓN.pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-128","number":"128","statement":"Un subtipo especial de neuronas ganglionares de la retina (las ipRGC o células ganglionares fotosensibles) posee la capacidad intrínseca de responder a la luz azul sin necesidad de intermediación de conos y bastones. ¿Qué fotopigmento expresan y hacia qué núcleo hipotalámico proyectan para sincronizar los ritmos circadianos?:","options":["Expresan melanopsina y proyectan hacia el Núcleo Supraquiasmático del hipotálamo.","Expresan rodopsina y proyectan al núcleo geniculado medial.","Expresan yodopsina y proyectan a las columnas dorsales.","Carecen de pigmento y terminan en la olivas bulbares."],"answer":0,"explanation":"No incluida en el material.","hack":"Hack de la Melanopsina e ipRGC (Pregunta de Aitana): Aitana destaca en clase: \"No solo los conos y bastones captan luz; las células ganglionares ipRGC tienen melanopsina, detectan luz azul y van directamente al Núcleo Supraquiasmático (Vía Retinohipotalámica) para inhibir la melatonina\".","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-060 / G0338 del banco canónico | integración: Tema 1.6 + Tema 1.8 + Tema 1.11.1 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Archivo3_Parte2.pdf | referencias indicadas: 10-17 Clase magistral_ Vía retinohipotalámica / 10-24 Clase magistral_ Organización funcional de la retina / TEMA 12 – VISIÓN.pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-129","number":"129","statement":"Un adenoma hipofisario en crecimiento hacia la silla turca comprime sagitalmente el centro del Quiasma Óptico. ¿Qué defecto campimétrico característico sufrirá el paciente?:","options":["Hemianopsia heterónima bitemporal (pérdida de la visión de los dos campos visuales temporales o laterales).","Hemianopsia homónima izquierda.","Amaurosis total del ojo derecho únicamente.","Ceguera nocturna aislada."],"answer":0,"explanation":"No incluida en el material.","hack":"Hack de la Compresión del Quiasma (Silla Turca): Al comprimir la parte media del quiasma, se lesionan los axones que decusan: los axones de las hemirretinas NASALES de ambos ojos. Como la hemirretina nasal capta el campo visual TEMPORAL, se pierde la visión periférica exterior de ambos ojos (Hemianopsia Bitemporal / \"visión en túnel\").","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-061 / G0344 del banco canónico | integración: Tema 1.6 + Tema 1.11.1 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Archivo3_Parte3.pdf | referencias indicadas: 10-27 Clase_ Vía Visual y Reflejos Oculares / 11-06 Tutoría / TEMA 12 – VISIÓN.pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-130","number":"130","statement":"Una lesión vascular o tumoral que destruye por completo la Cintilla Óptica Derecha (Tracto Óptico Derecho) o el Núcleo Geniculado Lateral Derecho desencadena un patrón de pérdida del campo visual característico. ¿Cuál es?:","options":["Hemianopsia homónima izquierda (pérdida de la visión de la mitad izquierda del campo visual en ambos ojos).","Hemianopsia bitemporal heterónima.","Amaurosis total del ojo derecho.","Pérdida de la audición del oído derecho."],"answer":0,"explanation":"No incluida en el material.","hack":"Hack de la Lesión Post-Quiasmática (Tracto / NGL / V1): Cualquier lesión posterior al quiasma destruye la información del campo visual CONTRALATERAL completo (porque el tracto derecho lleva fibras de la hemirretina temporal derecha y de la hemirretina nasal izquierda). Resultado: Hemianopsia Homónima Contralateral.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-062 / G0349 del banco canónico | integración: Tema 1.6 + Tema 1.11.1 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Archivo3_Parte3.pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #58, #134, #226) / 10-27 Clase_ Vía Visual y Reflejos Oculares / TEMA 12 – VISIÓN.pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-131","number":"131","statement":"Un paciente con destrucción total de la Corteza Visual Primaria V1 (Área 17) bilateral manifiesta ceguera cortical completa. Sin embargo, ante objetos que se mueven rápidamente hacia su rostro, el paciente es capaz de esquivarlos involuntariamente sin \"verlos\" conscientemente (fenómeno de Visión Ciega o Blindsight). ¿Qué vía visual subcortical retinofugal alternativa conserva esta respuesta refleja?:","options":["La vía retinocolicular (proyección desde las células ganglionares M de la retina hacia el Colículo Superior del mesencéfalo y el Núcleo Pulvinar del tálamo).","La vía lemniscal que sube por los cordones posteriores.","La vía retinohipotalámica hacia el núcleo supraquiasmático.","El tracto corticoespinal lateral."],"answer":0,"explanation":"No incluida en el material.","hack":"Hack del Blindsight / Vía Retinocolicular: Un 10% de las fibras del nervio óptico no van al NGL, sino al Colículo Superior (Mesencéfalo). Esta vía subcortical arcaica permite localizar espacialmente y reaccionar ante estímulos en movimiento sin percepción consciente de la visión (independiente de V1).","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-063 / G0359 del banco canónico | integración: Tema 1.5.1 + Tema 1.6 + Tema 1.7 + Tema 1.8 + Tema 1.11.1 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Archivo3_Parte3.pdf | referencias indicadas: 10-27 Clase_ Vía Visual / 11-06 Tutoría_ Neurofisiología / TEMA 12 – VISIÓN.pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-132","number":"132","statement":"A diferencia de los infartos occipitales corticales de la Arteria Cerebral Posterior que suelen presentar \"preservación macular\", las lesiones destructivas vasculares o tumorales completas de la Cintilla Óptica o del Núcleo Geniculado Lateral (NGL) producen:","options":["Hemianopsia homónima contralateral COMPLETA (con afectación de la visión macular central).","Hemianopsia bitemporal heterónima respetando el centro.","Visión doble monocular aislada.","Pérdida exclusiva de la visión en la oscuridad."],"answer":0,"explanation":"[Explicación 1 (Todas as questoes ate tema 1.10.1.pdf Q40)] Hack NGL (Afectación Macular) vs. V1 (Preservación Macular): Lesión de V1 (Corteza Occipital / ACP): Hemianopsia homónima contralateral CON PRESERVACIÓN MACULAR (gracias a la colateral de la ACM). Lesión del NGL o Cintilla Óptica: Hemianopsia homónima contralateral SIN PRESERVACIÓN MACULAR (afecta todo el campo central y periférico).","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-064 / G0366 del banco canónico | integración: Tema 1.3 + Tema 1.6 + Tema 1.7 + Tema 1.11.1 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Archivo3_Parte3.pdf | referencias indicadas: 10-27 Clase_ Vía Visual / TEMA 12 – VISIÓN.pdf / NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #134)","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-133","number":"133","statement":"Analice las siguientes proposiciones sobre la anatomofisiología del Sistema Visual. Indique la ÚNICA combinación donde TODAS las proposiciones sean VERDADERAS: 1. La fototransducción luminosa provoca la hiperpolarización de los fotorreceptores y la disminución de la liberación de glutamato. 2. Los axones de las hemirretinas nasales decusan en el quiasma óptico, mientras que los de las hemirretinas temporales continúan ipsilateralmente. 3. La vía parvocelular (capas 3, 4, 5 y 6 del NGL) procesa la alta resolución espacial, la forma detallada y el color.","options":["1, 2 y 3 son VERDADERAS.","Solo 1 y 2 son verdaderas.","Solo 2 y 3 son verdaderas.","1, 2 y 3 son falsas."],"answer":0,"explanation":"[Explicación 1 (Todas as questoes ate tema 1.10.1.pdf Q42)] Hack del Gran Resumen del || [Explicación 2 (Neuro_Archivo3_Parte3.pdf Q42)] Hack del Gran Resumen del Tema 1.11.1:Proposición 1 (VERDADERA): Luz = Cierre de canales Na⁺ -> Hiperpolarización -> Menos Glutamato. Proposición 2 (VERDADERA): Nasal Decusa / Temporal No Decusa. Proposición 3 (VERDADERA): Parvocelular (3-6) = Forma/Color vs. Magnocelular (1-2) = Movimiento.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-065 / G0368 del banco canónico | integración: Tema 1.6 + Tema 1.11.1 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Archivo3_Parte3.pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Preguntas #37, #58, #119-#122, #131, #133, #134, #224-#227, #248-#252) / Tema 1.11.1 - Sistema visual 25-26.pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-134","number":"134","statement":"La vía auditiva central es una vía ascendente multisináptica con decusaciones parciales a lo largo del tronco del encéfalo. Ordene cronológicamente las estaciones de relevo de esta vía desde la periferia hasta la corteza cerebral:","options":["Ganglio Espiral de Corti → Núcleos Cocleares (Ventral/Dorsal) → Complejo Olivar Superior → Lemnisco Lateral → Colículo Inferior → Núcleo Geniculado Medial del tálamo → Corteza Auditiva Primaria (A1 / Heschl).","Ganglio vestibular → Colículo superior → Núcleo geniculado lateral → Área 17.","Núcleo gracilis → Lemnisco medial → Núcleo VPL → Giro postcentral.","Órgano de Corti → Núcleo rojo → Oliva inferior → Cerebelo."],"answer":0,"explanation":"[Explicación 1 (Todas as questoes ate tema 1.10.1.pdf Q4)] Hack Mnemónico Vía Auditiva \"E-CO-LI-MA\": E: Ganglio Espiral (1ª neurona). CO: Núcleos COcleares (2ª neurona). L: Lemnisco lateral / Complejo Olivar Superior (procesamiento binaural). I: Colículo Inferior del mesencéfalo. M: Núcleo Geniculado MEDIAL del Tálamo (Medial = Música / Medial = Audición; no confundir con Geniculado Lateral = Luz/Visión). A: Corteza Auditiva (Giros transversos de Heschl / Áreas 41 y 42).","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-066 / G0372 del banco canónico | integración: Tema 1.5.1 + Tema 1.5.2 + Tema 1.6 + Tema 1.7 + Tema 1.11.2 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Archivo3_Parte3.pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #123, #189, #229) / 09-24 Clase_ Neuroanatomía - Vías Sensitivas y Auditivas del Tronco Encefálico / TEMA 13 – SENTIDO DE LA AUDICIÓN Y EQUILIBRIO .pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-135","number":"135","statement":"La Corteza Auditiva Primaria (A1, Áreas 41 y 42 de Brodmann) se localiza en los giros transversos de Heschl de la cara superior del giro temporal superior. Señale la afirmación VERDADERA sobre sus aferencias y su organización interna:","options":["Recibe aferencias tonotópicamente organizadas procedentes del Núcleo Geniculado Medial del tálamo; los sonidos de alta frecuencia (agudos) y baja frecuencia (graves) se representan ordenadamente en su superficie.","Recibe sus aferencias principales del núcleo geniculado lateral del tálamo.","Se ubica exclusivamente en el lóbulo parietal posterior de la cara medial.","Presenta un mapa organizado según el volumen o intensidad del sonido expresado en decibelios."],"answer":0,"explanation":"No incluida en el material.","hack":"Hack de la Tonotopía Cortical (Trap Clásica de Examen): La banca intenta engañar afirmando que \"la corteza A1 se organiza por VOLUMEN / INTENSIDAD\". ¡FALSO! Tanto la cóclea como la vía y la corteza A1 se organizan por FRECUENCIA (TONOTOPÍA: Hertz / Hz). Además, las aferencias vienen del Geniculado MEDIAL (no lateral).","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-067 / G0383 del banco canónico | integración: Tema 1.6 + Tema 1.7 + Tema 1.11.2 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Archivo3_Parte3.pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #20, #112, #123, #230) / 10-08 Clase_ Áreas Funcionales de la Corteza Cerebral / ex. 2021 (respuestas).pdf (Pregunta #62)","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-136","number":"136","statement":"Aunque la mayor parte del procesamiento vestibular es reflejo e subcortical, existe una proyección ascendente hacia el córtex cerebral para la percepción consciente de la orientación espacial y la verticalidad. Indique el núcleo talámico y la localización cortical de la Corteza Vestibular Primaria:","options":["Relevo en el Núcleo Ventral Posterolateral (porción oral / VPI) del tálamo, proyectando hacia la Corteza Parieto-Insular Vestibular (PIVC, en la ínsula posterior y opérculo parietal) y áreas 2v / 3a.","Relevo en el núcleo geniculado lateral proyectando al lóbulo occipital V1.","Relevo en las pirámides bulbares proyectando al área de Broca.","Proyección directa a la retina sin pasar por el tálamo."],"answer":0,"explanation":"No incluida en el material.","hack":"Hack de la Corteza Vestibular PIVC: El equilibrio SÍ tiene representación consciente cortical: la Corteza Parieto-Insular Vestibular (PIVC) en el fondo de la cisura lateral de Silvio (ínsula posterior / opérculo parietal). Recibe axones del Tálamo VPLo/VPI.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-068 / G0394 del banco canónico | integración: Tema 1.6 + Tema 1.7 + Tema 1.11.2 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Archivo3_Parte3.pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #124, #189) / 10-27 Aula_ Fisiología de la Audición y el Equilibrio / TEMA 13 – SENTIDO DE LA AUDICIÓN Y EQUILIBRIO .pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-137","number":"137","statement":"En la tectum mesencefálica, el Colículo Inferior constituye una estación central obligada de la vía auditiva ascendente. ¿Qué integración realiza y hacia dónde envía sus axones de proyección?:","options":["Integra todas las aferencias auditivas tonotópicas y binaurales ascendentes procedentes del lemnisco lateral, proyectando a través del brazo del colículo inferior hacia el Núcleo Geniculado Medial del tálamo.","Integra la información visual de la retina y proyecta al nervio óptico.","Recibe impulsos gustativos y los envía al bulbo olfatorio.","Inhibe la producción de saliva en la glándula parótida."],"answer":0,"explanation":"[Explicación 1 (Todas as questoes ate tema 1.10.1.pdf Q32)] Hack Tectum Mesencefálico (Superior vs. Inferior): Colículo SUPERIOR: Vía VISUAL subcortical / Reflejos oculomotores. Colículo INFERIOR: Vía AUDITIVA central / Integración tonotópica -> Envía fibras al Núcleo Geniculado Medial del Tálamo.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-069 / G0400 del banco canónico | integración: Tema 1.5.1 + Tema 1.6 + Tema 1.11.2 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Archivo3_Parte3.pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #123, #229) / 09-24 Clase_ Neuroanatomía - Vías Sensitivas y Auditivas / TEMA 13 – SENTIDO DE LA AUDICIÓN Y EQUILIBRIO .pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-138","number":"138","statement":"Indica la afirmación VERDADERA sobre los núcleos basales:","options":["El putamen es más interno o medial que el globo pálido.","En una sección transversal del cerebro, la cápsula interna separa al tálamo del globo pálido.","El extremo de la cabeza del caudado está más próximo a la sustancia negra que el extremo de la cola.","La cola del caudado es una parte del núcleo lenticular."],"answer":1,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-070 / G0432 del banco canónico | integración: Tema 1.6 + Tema 1.7 + Tema 1.9.2 | archivos: Neuro_Parte2.pdf; NEURO_275_ORGANIZADO_POR_TEMA_HACK24(1).pdf; NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf | referencias indicadas: Examem 2025 outro modelo juneka.pdf / exame neuro 2025 transcrito juneka.pdf / perguntas neuro julio exame.docx","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-139","number":"139","statement":"Indica la relación INCORRECTA al respecto de los siguientes tractos / comunicaciones del telencéfalo y diencéfalo:","options":["La estría medular comunica a los núcleos mamilares con el tegmento del tronco encefálico.","El fascículo longitudinal dorsal comunica el hipotálamo con la formación reticular para regular la actividad cardiovascular.","La cápsula interna separa el tálamo del globo pálido.","El fórnix comunica a la formación hipocampal con el hipotálamo."],"answer":0,"explanation":"[Nota de la clave] É a incorreta; a estría medular conecta o hipotálamo/área septal aos núcleos habenulares).","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-071 / G0451 del banco canónico | integración: Tema 1.6 + Tema 1.7 | archivos: Neuro_Parte2.pdf | referencias indicadas: ex. 2022 (sin respuestas) 2.pdf / Exame Neuro 2022.pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-140","number":"140","statement":"Sobre las capas del neocórtex es CIERTO que:","options":["La capa I contiene principalmente células piramidales grandes responsables de la salida motora.","La capa IV es rica en células granulares y es la principal receptora de aferencias talámicas.","La capa V está compuesta principalmente por interneuronas inhibitorias.","La capa VI es la principal capa de salida para las proyecciones corticocorticales."],"answer":1,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-072 / G0468 del banco canónico | integración: Tema 1.6 + Tema 1.7 | archivos: Neuro_Parte2.pdf; NEURO_275_ORGANIZADO_POR_TEMA_HACK24(1).pdf; NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf | referencias indicadas: perguntas neuro julio exame.docx (Pergunta #28) / Tema 1.7 - Telencéfalo 25-26 (2).pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-141","number":"141","statement":"Ordena la secuencia de acontecimientos que tiene lugar en la activación de la vía directa de los ganglios basales: 1 - Desinhibición de las proyecciones tálamo-corticales 2 - Activación del cuerpo estriado por la corteza 3 - Inhibición del globo pálido interno / sustancia negra reticulada 4 - Activación de la corteza motora","options":["2 → 3 → 1 → 4","3 → 2 → 4 → 1","1 → 2 → 3 → 4","2 → 1 → 3 → 4"],"answer":0,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-073 / G0472 del banco canónico | integración: Tema 1.5.1 + Tema 1.6 + Tema 1.7 + Tema 1.9.1 + Tema 1.9.2 | archivos: Neuro_Parte2.pdf | referencias indicadas: perguntas neuro julio exame.docx / Examem 2025 outro modelo juneka.pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-142","number":"142","statement":"En relación al flujo de información por el lóbulo temporal determinante en la génesis de la memoria declarativa, el orden correcto sería:","options":["Áreas de asociación cortical → Tálamo → Hipocampo → Hipotálamo → Áreas de asociación cortical.","Áreas de asociación cortical → Hipocampo → Hipotálamo → Tálamo → Áreas de asociación cortical.","Áreas de asociación cortical → Hipotálamo → Hipocampo → Áreas de asociación cortical → Tálamo.","Áreas de asociación cortical → Tálamo → Hipotálamo → Áreas de asociación cortical."],"answer":1,"explanation":"NotebookLM - Justificación/Mapa de las Mentiras: Mecanismo Neurológico (Técnica Feynman): El Circuito de Papez es la \"cinta transportadora\" cerrada que usa el cerebro para convertir una experiencia temporal en un recuerdo permanente (memoria declarativa). El flujo es un axioma unidireccional irrompible. Empieza en la corteza (lo que ves y oyes), que envía la información a la fábrica de recuerdos: el Hipocampo. El hipocampo la empaqueta y la manda por el fórnix al Hipotálamo (cuerpos mamilares). El hipotálamo se la pasa al Tálamo (núcleo anterior), y este último la devuelve a la Corteza (giro cingulado) para que quede guardada conscientemente. Prueba Teórica Verbatim: \"van las conexiones a través del fórnix con el hipotálamo... a núcleo anterior del tálamo a través del tracto mamilotalámico y luego del tálamo... a las regiones corticales\". EL MAPA DE LAS MENTIRAS (DISECCIÓN DE DISTRACTORES) Alternativa a): Áreas de asociación cortical -> Tálamo -> Hipocampo -> Hipotálamo -> Áreas de asociación cortical. Por qué es falsa y Hack detectado: Hack 15 (Vectores Invertidos / Desorden Secuencial). El examinador altera el orden del circuito colocando al tálamo antes que al hipocampo. La corteza envía la información primero al hipocampo (vía entorrinal/perforante), no al tálamo, para iniciar la consolidación de un recuerdo nuevo. Corrección: El orden debe ser Corteza -> Hipocampo -> Hipotálamo -> Tálamo. Prueba de Refutación: \"La principal aferencia [al hipocampo] es la vía perforante que se proyecta desde la corteza entorrinal\". Alternativa c): Áreas de asociación cortical -> Hipotálamo -> Hipocampo -> Áreas de asociación cortical -> Tálamo. Por qué es falsa y Hack detectado: Caos Topográfico. Vuelve a romper el circuito de Papez. Es biológicamente imposible que la información fluya directamente de la corteza al hipotálamo para crear memoria sin pasar primero por la estación de codificación del hipocampo. Además, invierte el flujo final sacando al tálamo fuera del bucle de retorno. Corrección: El hipotálamo recibe del hipocampo, no al revés. Prueba de Refutación: \"La principal eferencia [del hipocampo] es el fórnix... que proyecta hasta los núcleos mamilares del hipotálamo\". Alternativa d): Áreas de asociación cortical -> Tálamo -> Hipotálamo -> Áreas de asociación cortical. Por qué es falsa y Hack detectado: Supresión de Estructura Vital (Hack 04). El examinador elimina por completo al Hipocampo del circuito. Sin hipocampo no hay formación de memoria declarativa posible (amnesia anterógrada total). Corrección: Debe incluir forzosamente al hipocampo como receptor primario de la corteza. Prueba de Refutación: \"La memoria declarativa (explícita) es aquella en que somos conscientes... pasa por el hipocampo\".","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-074 / G0482 del banco canónico | integración: Tema 1.6 + Tema 1.7 + Tema 1.8 | archivos: Neuro_Parte2.pdf; tema 1.8 e outros cru notebooklm.pdf | referencias indicadas: Design sem nome (3).pdf / Exame Neuro 2022.pdf (Pergunta 54)","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-143","number":"143","statement":"Al realizar un corte transversal/coronal del telencéfalo, de MEDIAL a LATERAL, la secuencia anatómica correcta de capas de sustancia gris y blanca es:","options":["Tálamo → Cápsula interna → Globo pálido → Putamen → Cápsula externa → Claustro → Cápsula extrema → Ínsula.","Tálamo → Globo pálido → Cápsula interna → Putamen → Claustro → Cápsula externa → Ínsula.","Tálamo → Cápsula interna → Putamen → Globo pálido → Claustro → Cápsula extrema → Ínsula.","Núcleo caudado → Putamen → Cápsula interna → Globo pálido → Claustro → Ínsula."],"answer":0,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-075 / G0490 del banco canónico | integración: Tema 1.6 + Tema 1.7 + Tema 1.9.2 | archivos: Neuro_Parte2.pdf | referencias indicadas: 10-06 Clase de Anatomía_ Organización Anatómica del Telencéfalo- transcript.txt / Nervioso T21-T22-20251006_163846","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-144","number":"144","statement":"Indique la relación CORRECTA sobre el diencéfalo:","options":["Núcleo reticular del tálamo — Inhibidor de las neuronas de relevo talámico, especialmente evidente durante el sueño.","Núcleo paraventricular del hipotálamo — Participa en la regulación de la sed pero no está implicado en la regulación del balance energético corporal.","Habénula — Estructura hipotalámica relacionada con el sentido del olfato y del gusto.","Órgano subfornical — Órgano circunventricular cuya función principal es regular la temperatura corporal."],"answer":0,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-076 / G0503 del banco canónico | integración: Tema 1.6 + Tema 1.8 | archivos: Neuro_Parte2.pdf | referencias indicadas: PREGUNTAS-TEST-NEURO-DIENCEFALO-.pdf / ex. 2022 (sin respuestas) 2.pdf (Pregunta #25)","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-145","number":"145","statement":"Sobre el tálamo, indica la respuesta INCORRECTA:","options":["Lámina medular interna — contiene el núcleo centromediano.","Pulvinar — localizado en la parte posterior del tálamo.","Núcleo ventral anterior (VA, porción lateral) — núcleo motor, recibe aferencia del globo pálido y sustancia negra y proyecta a corteza motora primaria.","Núcleo geniculado lateral — recibe información auditiva del colículo inferior mesencefálico y proyecta a la corteza auditiva primaria."],"answer":3,"explanation":"[Nota de la clave] Incorreta pois quem recebe a informação auditiva é o Núcleo Geniculado Medial; o lateral transmite a visão).","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-077 / G0505 del banco canónico | integración: Tema 1.5.1 + Tema 1.6 + Tema 1.11.2 | archivos: Neuro_Parte2.pdf | referencias indicadas: ex. 2 (respuestas).pdf (Pregunta #21) / ex. 2 (sin respuestas) (1, 2, 3 y 16).pdf (Pregunta #21)","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-146","number":"146","statement":"¿Cuál de los siguientes núcleos hipotalámicos contiene orexinas (hipocretinas) relacionadas con la conducta alimentaria y el mantenimiento del estado de vigilia?","options":["N. Laterales","N. Preóptico","N. Mamilares","N. Supraóptico"],"answer":0,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-078 / G0511 del banco canónico | integración: Tema 1.6 + Tema 1.8 + Tema 1.11.1 | archivos: Neuro_Parte2.pdf | referencias indicadas: ex. 2021 (respuestas).pdf / wuolah-free-EXAMEN-NEURO-2-SIN- RESPUESTAS.pdf (Pregunta #28 / #67)","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-147","number":"147","statement":"¿Cuál de los siguientes núcleos hipotalámicos utiliza la histamina como neurotransmisor principal para promover el estado de vigilia?","options":["N. Ventromedial","N. Tuberomamilar","N. Supraóptico","N. Arcuato"],"answer":1,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-079 / G0517 del banco canónico | integración: Tema 1.6 + Tema 1.8 | archivos: Neuro_Parte2.pdf | referencias indicadas: examenes neuro compl (1).pdf (Pregunta #48)","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-148","number":"148","statement":"En cuanto a los límites anatómicos del hipotálamo, señale la afirmación CORRECTA:","options":["El límite superior lo constituye el tuber cinereum y el inferior el surco hipotalámico.","El límite anterior está constituido por la comisura blanca anterior, la lámina terminal y el quiasma óptico.","El límite posterior lo constituye exclusivamente el agujero de Monro.","Todas las anteriores son correctas."],"answer":1,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-080 / G0521 del banco canónico | integración: Tema 1.4 + Tema 1.6 + Tema 1.11.1 | archivos: Neuro_Parte2.pdf | referencias indicadas: wuolah-free-tema-5-preguntas.pdf (Pregunta #4) / wuolah-free- examen-3.pdf (Pregunta #16)","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-149","number":"149","statement":"Sobre las conexiones y tractos del hipotálamo, señala la afirmación CORRECTA:","options":["Fórnix (o trígono) — principal eferencia de la amígdala que conecta con los cuerpos mamilares hipotalámicos.","Tracto mamilotalámico — conecta los cuerpos mamilares con el núcleo anterior del tálamo, componente del circuito de Papez.","Fascículo longitudinal dorsal (de Schütz) — aferencia hipotalámica que influye indirectamente sobre los núcleos vegetativos del prosencéfalo.","Tracto tuberohipofisario o tuberoinfundibular — conecta el núcleo supraóptico con la adenohipófisis."],"answer":1,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-081 / G0524 del banco canónico | integración: Tema 1.6 + Tema 1.8 | archivos: Neuro_Parte2.pdf | referencias indicadas: perguntas neuro julio exame.docx (Pregunta #19) / examenes neuro compl (1).pdf (Pregunta #19)","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-150","number":"150","statement":"¿Cuál de los siguientes núcleos talámicos es el núcleo principal de relevo para la sensibilidad somática general (tacto, dolor, temperatura y propiocepción)?:","options":["Ventral anterior (VA).","Ventral posterior (VP / VPL-VPM).","Pulvinar.","Ventral lateral (VL).","Dorsomediano (DM)."],"answer":1,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-082 / G0525 del banco canónico | integración: Tema 1.6 + Tema 1.10 | archivos: Neuro_Parte2.pdf | referencias indicadas: wuolah-free-Examen-Neuro-2.pdf (Pregunta #26) / wuolah-free-tema- 5-preguntas.pdf (Pregunta #12)","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-151","number":"151","statement":"El núcleo (cuerpo) geniculado lateral del tálamo:","options":["Manda axones al área visual primaria (área 17 de Brodmann).","Manda axones al área auditiva primaria (áreas 41, 42 de Brodmann).","Manda axones al área gustativa primaria.","Manda axones al área olfatoria primaria.","Manda axones a los núcleos basales."],"answer":0,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-083 / G0528 del banco canónico | integración: Tema 1.6 + Tema 1.7 + Tema 1.11.1 | archivos: Neuro_Parte2.pdf | referencias indicadas: wuolah-free-tema-5-preguntas.pdf (Pregunta #16) / wuolah-free- Examen-Neuro-1 (1).pdf (Pregunta #14)","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-152","number":"152","statement":"Señale cuál de las siguientes afirmaciones acerca de la región hipotalámica periventricular es FALSA:","options":["Está implicada en la regulación de los ritmos circadianos.","Influye en la generación de comportamientos encaminados a la ingesta alimentaria.","Es el regulador exclusivo de la liberación hormonal de la hipófisis posterior.","Limita directamente con la cavidad del III ventrículo."],"answer":2,"explanation":"[Nota de la clave] As neurônios magnocelulares produtoras de oxitocina e vasopressina/ADH residem principalmente nos núcleos supraóptico e paraventricular).","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-084 / G0532 del banco canónico | integración: Tema 1.6 + Tema 1.12 | archivos: Neuro_Parte2.pdf | referencias indicadas: examenes neuro compl (1).pdf (Pregunta #71) / Preguntas temas 3,4,5,6.pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-153","number":"153","statement":"El polo anterior (más estrecho) del tálamo limita directamente con:","options":["El claustro o antemuro.","El pulvinar.","El fórnix y el agujero interventricular (de Monro).","La fisura calcarina."],"answer":2,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-085 / G0533 del banco canónico | integración: Tema 1.6 + Tema 1.7 | archivos: Neuro_Parte2.pdf | referencias indicadas: examenes neuro compl (1).pdf (Pregunta #72) / TEMA 5 – DIENCÉFALO .pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-154","number":"154","statement":"En la vía del cordón posterior-lemnisco medial, las fibras integrantes del lemnisco medial hacen sinapsis en el tálamo concretamente en el:","options":["Núcleo anterior del tálamo.","Núcleo ventromedial del tálamo.","Núcleo ventral posteromedial (VPM) del tálamo.","Núcleo ventral posterolateral (VPL) del tálamo."],"answer":3,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-086 / G0538 del banco canónico | integración: Tema 1.6 + Tema 1.10 | archivos: Neuro_Parte2.pdf | referencias indicadas: examenes neuro compl (1).pdf (Pregunta #56) / Tema 1.6 - Diencéfalo 25-26.pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-155","number":"155","statement":"Indica la afirmación CORRECTA sobre los núcleos de la habénula en el epitálamo:","options":["Reciben eferencias procedentes de los colículos superiores del mesencéfalo para coordinar reflejos pupilares.","Constituyen un centro integrador de vías aferentes olfatorias, viscerales y somáticas conectado con el sistema límbico.","Pertenecen funcionalmente al subtálamo y forman parte de la vía directa de los ganglios basales.","Producen melatonina para regular los ritmos circadianos en respuesta a la oscuridad."],"answer":1,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-087 / G0540 del banco canónico | integración: Tema 1.6 + Tema 1.11.3 | archivos: Neuro_Parte2.pdf | referencias indicadas: wuolah-free-tema-5-preguntas.pdf (Preguntas #23-#24) / TEMA 5 – DIENCÉFALO .pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-156","number":"156","statement":"Los núcleos dorsomedial y anterior del tálamo están relacionados principalmente con:","options":["El control de la vía motora piramidal.","El sistema límbico y el procesamiento de emociones y memoria.","La modulación de la audición primaria.","El reflejo pupilar a la luz."],"answer":1,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-088 / G0542 del banco canónico | integración: Tema 1.6 + Tema 1.8 | archivos: Neuro_Parte2.pdf | referencias indicadas: wuolah-free-tema-5-preguntas.pdf (Pregunta #2) / wuolah-free- Examen-Neuro-1 (1).pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-157","number":"157","statement":"¿Qué tracto de sustancia blanca conecta los cuerpos mamilares del hipotálamo con los núcleos anteriores del tálamo dentro del circuito de Papez?:","options":["El fórnix.","El tracto mamilotalámico (fascículo de Vicq d'Azyr).","La estría medular del tálamo.","El fascículo longitudinal dorsal."],"answer":1,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-089 / G0543 del banco canónico | integración: Tema 1.6 + Tema 1.8 | archivos: Neuro_Parte2.pdf | referencias indicadas: 10-06 Clase_ Neuroanatomía del Hipotálamo / Nervioso T21-T22- 20251006_163846","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-158","number":"158","statement":"Respecto al procesamiento de la información sensorial en el tálamo, ¿cuál de los siguientes sentidos es la ÚNICA excepción que NO realiza relevo sináptico en el tálamo antes de llegar a su corteza primaria?:","options":["Visión.","Gusto.","Olfato.","Audición."],"answer":2,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-090 / G0544 del banco canónico | integración: Tema 1.6 + Tema 1.11.3 | archivos: Neuro_Parte2.pdf | referencias indicadas: Preguntas temas 3,4,5,6.pdf (Pregunta #17 / #25) / wuolah-free-tema- 5-preguntas.pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-159","number":"159","statement":"¿Cuál de los siguientes núcleos hipotalámicos produce orexinas (hipocretinas) estimulando la ingesta alimentaria y manteniendo el estado de vigilia?:","options":["Núcleos laterales del hipotálamo.","Núcleo supraóptico.","Núcleo paraventricular.","Núcleo preóptico medial."],"answer":0,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-091 / G0545 del banco canónico | integración: Tema 1.6 + Tema 1.8 + Tema 1.11.1 | archivos: Neuro_Parte2.pdf | referencias indicadas: PREGUNTAS-TEST-NEURO-DIENCEFALO-.pdf / ex. 2021 (respuestas).pdf (Pregunta #28)","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-160","number":"160","statement":"El núcleo paraventricular del hipotálamo se caracteriza por:","options":["Sintetizar oxitocina y vasopresina (ADH) enviadas a la neurohipófisis.","Ser el único centro regulador de la visión nocturna.","Localizarse en el grupo posterior del tálamo.","Formar parte del núcleo lenticular."],"answer":0,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-092 / G0546 del banco canónico | integración: Tema 1.6 + Tema 1.12 | archivos: Neuro_Parte2.pdf | referencias indicadas: wuolah-free-tema-5-preguntas.pdf (Pregunta #9) / TEMA 5 – DIENCÉFALO .pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-161","number":"161","statement":"¿Qué relación anatómica presenta la glándula pineal (epífisis) con respecto al III ventrículo y al diencéfalo?:","options":["Se ubica en la pared anterior del III ventrículo, sobre el quiasma óptico.","Se localiza en la región posterior del epitálamo, sobre los colículos superiores del mesencéfalo.","Se sitúa en la fosa interpeduncular.","Forma la pared lateral del IV ventrículo."],"answer":1,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-093 / G0549 del banco canónico | integración: Tema 1.5.1 + Tema 1.6 | archivos: Neuro_Parte2.pdf | referencias indicadas: 10-06 Clase_ Neuroanatomía del Hipotálamo / wuolah-free- PREGUNTAS-TEST-NEURO-DIENCEFALO-.pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-162","number":"162","statement":"¿Cuál de las siguientes afirmaciones sobre los núcleos centromediano e intralaminares del tálamo es CORRECTA?:","options":["Pertenecen al grupo lateral de relevo somatosensorial directo hacia la corteza motora primaria.","Están ubicados en el espesor de la lámina medular interna y proyectan de forma difusa a amplias áreas de la corteza cerebral, participando en el mantenimiento de la vigilia.","Reciben información exclusivamente visual procedente de la retina.","Se localizan en la región tuberal del hipotálamo."],"answer":1,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-094 / G0550 del banco canónico | integración: Tema 1.6 + Tema 1.7 + Tema 1.8 | archivos: Neuro_Parte2.pdf | referencias indicadas: wuolah-free-tema-5-preguntas.pdf (Pregunta #10) / TEMA 5 – DIENCÉFALO .pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-163","number":"163","statement":"El núcleo ventral lateral (VL) del tálamo tiene como función principal:","options":["Recibir información sensitiva gustativa.","Servir de relevo de las vías motoras procedentes del cerebelo (núcleo dentado) y los núcleos basales hacia la corteza motora.","Procesar aferencias auditivas directamente desde la cóclea.","Sintetizar la hormona antidiurética (vasopresina)."],"answer":1,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-095 / G0551 del banco canónico | integración: Tema 1.6 + Tema 1.9.1 + Tema 1.9.3 | archivos: Neuro_Parte2.pdf | referencias indicadas: wuolah-free-tema-5-preguntas.pdf (Pregunta #11) / wuolah-free- Examen-Neuro-2.pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-164","number":"164","statement":"Señale la afirmación FALSA sobre el subtálamo (región subtalámica):","options":["Se sitúa ventral al tálamo e intermedio entre el diencéfalo y el tegmento mesencefálico.","Contiene el núcleo subtalámico (de Luys), que pertenece al circuito motor de los ganglios basales.","El núcleo subtalámico ejerce una acción inhibidora GABAérgica sobre el globo pálido interno.","Una lesión del núcleo subtalámico puede provocar hemibalismo en el lado contralateral del cuerpo."],"answer":2,"explanation":"[Nota de la clave] É a afirmação FALSA porque o núcleo subtalâmico é glutamatérgico e exercita uma ação excitadora sobre o globo pálido interno).","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-096 / G0552 del banco canónico | integración: Tema 1.6 + Tema 1.9.2 | archivos: Neuro_Parte2.pdf | referencias indicadas: wuolah-free-EXAMEN-2017-2018-1 (1).pdf (Pregunta #31) / ex. 2021 (respuestas).pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-165","number":"165","statement":"Respecto a las conexiones aferentes del tálamo, es FALSO que:","options":["El núcleo ventral posterior lateral (VPL) recibe el lemnisco medial y el espinotalámico.","El núcleo ventral posterior medial (VPM) recibe aferencias trigeminales y gustativas.","El núcleo geniculado medial (NGM) recibe aferencias de los colículos inferiores a través del brazo del colículo inferior.","El núcleo anterior del tálamo recibe sus principales aferencias directo de la retina."],"answer":3,"explanation":"[Nota de la clave] É a FALSA; o núcleo anterior recebe aferências do corpo mamilar através do trato mamilotalâmico).","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-097 / G0555 del banco canónico | integración: Tema 1.6 + Tema 1.11.1 | archivos: Neuro_Parte2.pdf | referencias indicadas: wuolah-free-Examen-Neuro-recu-junio-2023 orc.pdf (Pregunta #31) / Tema 1.6 - Diencéfalo 25-26.pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-166","number":"166","statement":"Señale la afirmación CORRECTA sobre el núcleo dorsomedial (DM) del tálamo:","options":["Recibe aferencias de la amígdala y el hipotálamo y proyecta a la corteza prefrontal.","Es un núcleo exclusivamente motor que proyecta a la médula espinal.","Es el encargado de enviar la información propioceptiva de los miembros inferiores a la circunvolución postcentral.","Forma parte de la lámina medular externa."],"answer":0,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-098 / G0557 del banco canónico | integración: Tema 1.6 + Tema 1.8 | archivos: Neuro_Parte2.pdf | referencias indicadas: wuolah-free-tema-5-preguntas.pdf (Pregunta #20) / TEMA 5 – DIENCÉFALO .pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-167","number":"167","statement":"El epitálamo se deriva embrionariamente del diencéfalo y está constituido principalmente por:","options":["El núcleo subtalámico de Luys y el área tegmental ventral.","La glándula pineal (epífisis) y los núcleos de la habénula.","El núcleo supraquiasmático y el cuerpo mamilar.","El núcleo geniculado lateral y el núcleo pulvinar."],"answer":1,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-099 / G0559 del banco canónico | integración: Tema 1.2 + Tema 1.6 | archivos: Neuro_Parte2.pdf | referencias indicadas: wuolah-free-tema-5-preguntas.pdf / ex. 2021 (respuestas).pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-168","number":"168","statement":"¿Cuál de los siguientes tractos hipotalámicos conecta los núcleos mamilares con la formación reticular y sustancia gris periacueductal del tronco del encéfalo?:","options":["Tracto mamilotalámico.","Fórnix (trígono).","Fascículo mamilotegmental.","Estría medular del tálamo."],"answer":2,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-100 / G0560 del banco canónico | integración: Tema 1.5.1 + Tema 1.6 | archivos: Neuro_Parte2.pdf | referencias indicadas: wuolah-free-EXAMEN-2017-2018-1 (1).pdf / wuolah-free-tema-5- preguntas.pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-169","number":"169","statement":"¿Qué núcleo talámico sirve de relevo específico para la información sensitiva trigeminal (cara/cabeza) y gustativa hacia la corteza sensitiva primaria y la ínsula?:","options":["Núcleo ventral posterolateral (VPL).","Núcleo ventral posteromedial (VPM).","Núcleo ventral anterior (VA).","Núcleo geniculado lateral (NGL)."],"answer":1,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-101 / G0561 del banco canónico | integración: Tema 1.6 + Tema 1.7 + Tema 1.10 + Tema 1.11.3 | archivos: Neuro_Parte2.pdf | referencias indicadas: wuolah-free-tema-5-preguntas.pdf / ex. 2 (respuestas).pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-170","number":"170","statement":"¿Cuál de los siguientes núcleos hipotalámicos pertenece a la región supraóptica (rostral) e incluye neuronas magnocelulares responsables de la síntesis de vasopresina (hormona antidiurética) y oxitocina?:","options":["Núcleo ventromedial.","Núcleos supraóptico y paraventricular.","Núcleo arcuato (infundibular).","Núcleos mamilares."],"answer":1,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-102 / G0562 del banco canónico | integración: Tema 1.6 + Tema 1.12 | archivos: Neuro_Parte2.pdf | referencias indicadas: wuolah-free-tema-5-preguntas.pdf / 10-06 Clase_ Neuroanatomía del Hipotálamo","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-171","number":"171","statement":"Respecto a la anatomía funcional del tálamo, el Núcleo Geniculado Medial (NGM):","options":["Recibe aferencias visuales y proyecta al área 17 de Brodmann.","Recibe aferencias del colículo inferior mesencefálico y proyecta a la corteza auditiva primaria (áreas 41 y 42).","Recibe aferencias del cerebelo y proyecta a la corteza motora.","Inhibe GABAérgicamente a los demás núcleos talámicos."],"answer":1,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-103 / G0563 del banco canónico | integración: Tema 1.5.1 + Tema 1.6 + Tema 1.11.2 | archivos: Neuro_Parte2.pdf | referencias indicadas: wuolah-free-tema-5-preguntas.pdf / TEMA 5 – DIENCÉFALO .pdf","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.6-172","number":"172","statement":"Señala cuál de las siguientes afirmaciones sobre los tractos de conexión del hipotálamo es FALSA:","options":["Los cuerpos mamilares proyectan hacia el núcleo anterior del tálamo mediante el tracto mamilotalámico.","La formación hipocampal envía axones hacia los cuerpos mamilares a través del fórnix (trígono).","El núcleo mamilar se conecta directamente con el núcleo anterior del tálamo a través del fórnix.","El fascículo longitudinal dorsal comunica el hipotálamo con núcleos vegetativos del tronco del encéfalo."],"answer":2,"explanation":"É a afirmação FALSA. A professora enfatiza explicitamente em aula que o fórnix traz axônios do hipocampo para os corpos mamilares, enquanto a conexão dos corpos mamilares com o tálamo anterior é feita pelo trato mamilotalámico, e não pelo fórnix).","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.6 - DIENCÉFALO | entrada I-104 / G0566 del banco canónico | integración: Tema 1.6 + Tema 1.7 | archivos: Neuro_Parte2.pdf | referencias indicadas: 10-06 Clase_ Neuroanatomía del Hipotálamo / Nervioso T21-T22- 20251006_16384667 (Desafio Oral da Professora Aitana)","topic":"1.6","document":"03-TEA216-1.TXT","subject":"MEFOS"}]);